INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('zlliang/zlliang/reviewing', 'reviewing', 'zlliang', 'zlliang', 'community', 'reviewing zlliang zlliang community AI智能评审工具，用于分享编程、生活和其他方面的想法 AIエージェントによるレビュー、プログラミング、生活、そしてその他のアイデアの共有 AI 리뷰 에이전트를 사용하여 프로그래밍, 삶, 그리고 다른 아이디어를 공유 Revisión de sitios web personales con enfoque en programación y tecnología Révision de sites web personnels avec un focus sur la programmation et la technologie Überprüfung von persönlichen Websites mit Schwerpunkt auf Programmierung und Technologie Os agentes de IA podem ajudar na revisão de código, compartilhando pensamentos sobre programação e muito mais ИИ Агенты могут помочь в проверке кода, обмениваясь мыслями о программировании и многом другом يمكن لوكلاء الذكاء الاصطناعي مساعدتك في مراجعة الكود، ومشاركة الأفكار حول البرمجة وغيرها My personal websites — sharing thoughts on programming, life, and everything in between. 如何使用AI智能评审工具 什么是AI智能评审 AI智能评审工具安装 AI智能评审工具设置指南 AI智能评审工具替代品 AI智能评审工具与其他工具的比较 My personal websites — sharing thoughts on programming, life, and everything in between.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('ivuorinen/branch-usage-checker/release-check', 'community', 'ivuorinen', 'branch-usage-checker', 'ivuorinen/branch-usage-checker', 'release-check', 0, 0, 20, '2026-03-02T01:06:07Z', '2026-03-02T03:53:45.085Z', 'd9727706f3a977d397304473e89e8794a345ee0b1b9d8389fa6bd97aa22943af', '{"id":"ivuorinen/branch-usage-checker/release-check","name":"release-check","description":{"zh":"release-check AI智能工具通过比较项目公众GitHub分支和Packagist分支下载统计，帮助您确定哪些分支可以安全删除","ja":"release-check AIエージェントは、プロジェクトのGitHubブランチとPackagistブランチのダウンロード統計を比較して、安全に削除できるブランチを判断します","ko":"release-check AI 에이전트는 프로젝트의 GitHub 브랜치와 Packagist 브랜치 다운로드 통계를 비교하여安全한 삭제가 가능한 브랜치를 결정합니다","es":"Release-check es una herramienta de AI que verifica ramas públicas de GitHub y estadísticas de descargas de Packagist para determinar si es seguro eliminar ramas.","fr":"Release-check est un outil d''IA qui vérifie les branches publiques Git et les statistiques de téléchargement Packagist pour déterminer si il est sûr de supprimer des branches.","de":"Release-check ist ein KI-Tool, das öffentliche Git-Zweige und Packagist-Download-Statistiken überprüft, um zu bestimmen, ob es sicher ist, Zweige zu löschen.","pt":"O release-check é uma ferramenta de IA que cruza dados de branches públicos do GitHub e estatísticas de downloads do Packagist para determinar a segurança de exclusão de branches","ru":"ИИ Агент release-check - это инструмент, который проверяет общие ветки GitHub и статистику загрузок Packagist, чтобы определить безопасность удаления веток","ar":"أداة release-check هي أداة ذكاء اصطناعي تقوم بفحص الفروع العامة على GitHub وإحصائيات التحميل من Packagist لتحديد أمان حذف الفروع","en":"Cross-check project public GitHub Branches and Packagist branch download statistics to determine are branches safe to delete"},"seo":{"title":{"zh":"AI智能工具：release-check 分支安全删除检测","ja":"A