INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('ruvnet/claude-flow/agent-gossip-coordinator', 'agent-gossip-coordinator', 'ruvnet', 'claude-flow', 'community', 'agent-gossip-coordinator ruvnet claude-flow community agent-gossip-coordinator是领先的AI智能代理协调平台，支持企业级架构和分布式群智能 agent-gossip-coordinatorは先進的なAIエージェントのオーケストレーションプラットフォームで、エンタープライズグレードのアーキテクチャと分散型スウォームインテリジェンスをサポート agent-gossip-coordinator는 선도적인 AI 에이전트 오케스트레이션 플랫폼으로, 엔터프라이즈급 아키텍처와 분산형 스와ーム 인텔리전스를 지원 La plataforma de orquestación de agentes líder para Claude. Despliega enjambres de agentes inteligentes y coordina flujos de trabajo autónomos La plateforme d''orchestration d''agents leader pour Claude. Déployez des essaims d''agents intelligents et coordonnez des flux de travail autonomes Die leitende Agenten-Orchestrierungsplattform für Claude. Bereitstellen Sie intelligente Agentenschwärme und koordinieren Sie autonome Workflows A plataforma Agent Gossip Coordinator é a líder em orquestração de agentes de IA, permitindo o desenvolvimento de sistemas de IA conversacionais com arquitetura empresarial e inteligência de enxame distribuída Платформа ИИ Агенты: Координатор Слухов является лидером в области оркестрации ИИ агентов, позволяя разработать системы ИИ с企业級 архитектурой и распределённой интеллектом роя منصة منسق وكالات الذكاء الاصطناعي هي الرائدة في مجال إدارة وكالات الذكاء الاصطناعي، مما يسمح ببناء أنظمة الذكاء الاصطناعي المحادثية بالهيكل المعماري المؤسسي والذكاء الموزع للروبوتات 🌊 The leading agent orchestration platform for Claude. Deploy intelligent multi-agent swarms, coordinate autonomous workflows, and build conversational AI systems. Features enterprise-grade architecture, distributed swarm intelligence, RAG integration, and native Claude Code support via MCP p... AI智能代理 agent-gossip-coordinator 多代理系统管理 企业级架构 分布式群智能 RAG集成 原生Claude Code支持 如何使用agent-gossip-coordinator agent-gossip-coordinator教程 🌊 The leading agent orchestration platform for Claude. Deploy intelligent multi-agent swarms, coordinate autonomous workflows, and build conversational AI systems. Features enterprise-grade architecture, distributed swarm intelligence, RAG integration, and native Claude Code support via MCP protocol. Ranked #1 in agent-based frameworks.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('willyu1007/Skill_Template_Module/plan-code-refactors', 'community', 'willyu1007', 'Skill_Template_Module', 'willyu1007/Skill_Template_Module', 'plan-code-refactors', 0, 0, 20, '2026-03-04T13:07:01.733Z', '2026-03-04T14:02:09.307Z', '21f5f770b9af94a284c5d8eaae5a8340ce982135a49a5cd0bafe6289b3f856ed', '{"id":"willyu1007/Skill_Template_Module/plan-code-refactors","name":"plan-code-refactors","description":{"zh":"计划代码重构是基于模块化方法的技能模板，具有完整的基本版本功能，并默认启用大多数插件","ja":"コードリファクタリング計画はモジュラーなアプローチに基づくスキルテンプレートであり、基本的なバージョンの機能を備え、ほとんどのプラグインをデフォルトで有効にします","ko":"코드 리팩토링 계획은 모듈화된 접근 방식에 기반한 스킬 템플릿으로 기본 버전의 기능을 완벽하게 갖추고 대부분의 플러그인을 기본적으로 활성화합니다","es":"Nuestro modelo de habilidad ''plan-code-refactors'' permite una planificación y refactorización de código eficientes para Agentes de IA","fr":"Notre modèle de compétence ''plan-code-refactors'' permet une planification et une refactoring de code efficaces pour les Agents d''IA","de":"Unser Fähigkeitsmodell ''plan-code-refactors'' ermöglicht eine effiziente Planung und Refactoring von Code für KI-Agents","pt":"O plano de refatoração de código é uma abordagem modular que oferece funcionalidades básicas e habilita a maioria dos add-ons por padrão","ru":"Планирование рефакторинга кода - это модульный подход, который предоставляет базовые функции и включает большинство дополнений по умолчанию","ar":"خطة إعادة هيكلة الكود هي подход منظم يقدم وظائف أساسية ويمكّن معظم الإضافات بشكل افتراضي","en":"Skill template based on a modular approach, has complete basic version functionality and enables most add-ons by default."},"seo":{"title":{"zh":"AI智能代理计划代码重构","ja":"AIエージェントによるコードリファクタリング計画","ko":"AI 에이전트 코드 리팩토링 계획","es":"Herramientas de planificación y refactorización de código...","fr":"Outils de planification et de refactoring de code pour le...","de":"Planungs- und Refactoring-Tools für KI-Agents","pt":"Ferramentas de Planejamento de Refatoração de Código - Ag...","ru":"Планирование рефакторинга кода - ИИ Агенты","ar":"أدوات تخطيط إعادة هيكلة الكود - وكلاء الذكاء الاصطناعي","en":"plan-code-refactors"},"description":{"zh":"计划代码重构是基于模块化方法的技能模板，具有完整的基本版本功能，并默认启用大多数插件","ja":"コードリファクタリング計画はモジュラーなアプローチに基づくスキルテンプレートであり、基本的なバージョンの機能を備え、ほとんどのプラグインをデフォルトで有効にします","ko":"코드 리팩토링 계획은 모듈화된 접근 방식에 기반한 스킬 템플릿으로 기본 버전의 기능을 완벽하게 갖추고 대부분의 플러그인을 기본적으로 활성화합니다","es":"Nuestro modelo de habilidad ''plan-code-refactors'' permite una planificación y refactorización de código eficientes para Agentes de IA","fr":"Notre modèle de compétence ''plan-code-refactors'' permet une planification et une refactoring de code efficaces pour les Agents d''IA","de":"Unser Fähigkeitsmodell ''plan-code-refactors'' ermöglicht eine effiziente Planung und Refactoring von Code für KI-Agents","pt":"O plano de refatoração de código é uma abordagem modular que oferece funcionalidades básicas e habilita a maioria dos add-ons por padrão","ru":"Планирование рефакторинга кода - это модульный подход, который предоставляет базовые функции и включает большинство дополнений по умолчанию","ar":"خطة إعادة هيكلة الكود هي подход منظم يقدم وظائف أساسية ويمكّن معظم الإضافات بشكل افتراضي","en":"Skill template based on a modular approach, has complete basic version functionality and enables most add-ons by default."},"definition":{"en":"Skill template based on a modular approach, has complete basic version functionality and enables most add-ons by default."},"features":{"zh":["基于模块化方法","完整的基本版本功能","默认启用大多数插件","提高开发效率","改进代码质量"],"ja":["モジュラーなアプローチ","基本的なバージョンの機能","ほとんどのプラグインをデフォルトで有効","開発効率の向上","コード品質の改善"],"ko":["모듈화된 접근 방식","기본 버전의 기능","대부분의 플러그인을 기본적으로 활성화","개발 효율의 향상","코드 품질의 개선"],"es":["Planificación y refactorización de código","Arquitectura modular","Funcionalidad básica completa","Compatibilidad con la mayoría de los complementos","Mejora de la eficiencia y la escalabilidad"],"fr":["Planification et refactoring