INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('willyu1007/Skill_Template_Module/plan-code-refactors', 'plan-code-refactors', 'willyu1007', 'Skill_Template_Module', 'community', 'plan-code-refactors willyu1007 Skill_Template_Module community 计划代码重构是基于模块化方法的技能模板，具有完整的基本版本功能，并默认启用大多数插件 コードリファクタリング計画はモジュラーなアプローチに基づくスキルテンプレートであり、基本的なバージョンの機能を備え、ほとんどのプラグインをデフォルトで有効にします 코드 리팩토링 계획은 모듈화된 접근 방식에 기반한 스킬 템플릿으로 기본 버전의 기능을 완벽하게 갖추고 대부분의 플러그인을 기본적으로 활성화합니다 Nuestro modelo de habilidad ''plan-code-refactors'' permite una planificación y refactorización de código eficientes para Agentes de IA Notre modèle de compétence ''plan-code-refactors'' permet une planification et une refactoring de code efficaces pour les Agents d''IA Unser Fähigkeitsmodell ''plan-code-refactors'' ermöglicht eine effiziente Planung und Refactoring von Code für KI-Agents O plano de refatoração de código é uma abordagem modular que oferece funcionalidades básicas e habilita a maioria dos add-ons por padrão Планирование рефакторинга кода - это модульный подход, который предоставляет базовые функции и включает большинство дополнений по умолчанию خطة إعادة هيكلة الكود هي подход منظم يقدم وظائف أساسية ويمكّن معظم الإضافات بشكل افتراضي Skill template based on a modular approach, has complete basic version functionality and enables most add-ons by default. 如何使用AI智能代理 什么是代码重构 AI智能代理替代品 代码重构工具 代码重构安装 代码重构设置指南 Skill template based on a modular approach, has complete basic version functionality and enables most add-ons by default.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('fwojciec/quiver/work', 'community', 'fwojciec', 'quiver', 'fwojciec/quiver', 'work', 0, 0, 20, '2026-03-04T13:07:01.740Z', '2026-03-04T14:05:23.559Z', '494b4eca63cbf4369e0c7537dc15d4eac6a40d4b74321055df1b730bfa75f6a7', '{"id":"fwojciec/quiver/work","name":"work","description":{"zh":"Work是一个Rust查询引擎，用于从多个来源读取数据，如BigQuery和PostgreSQL，使用Apache Arrow","ja":"Workは、BigQueryやPostgreSQLなどの複数のソースからデータを読み取るためのRustクエリエンジンで、Apache Arrowを使用","ko":"Work는 BigQuery 및 PostgreSQL와 같은 여러 소스에서 데이터를 읽기 위한 Rust 쿼리 엔진으로 Apache Arrow를 사용","es":"Un motor de consultas Rust para leer datos de BigQuery y PostgreSQL con Apache Arrow","fr":"Un moteur de requêtes Rust pour lire des données de BigQuery et PostgreSQL avec Apache Arrow","de":"Ein Rust-Abfragemotor zum Lesen von Daten aus BigQuery und PostgreSQL mit Apache Arrow","pt":"Um motor de consulta Rust para leitura de dados de várias fontes como BigQuery e PostgreSQL usando Apache Arrow","ru":"Rust движок запросов для чтения данных из нескольких источников, таких как BigQuery и PostgreSQL, используя Apache Arrow","ar":"محرك استعلام رست لقراءة البيانات من مصادر متعددة مثل بيج كويري وبوستجرس كول باستخدام أباتشي أرو","en":"A Rust query engine for reading data from multiple sources like BigQuery and PostgreSQL using Apache Arrow."},"seo":{"title":{"zh":"AI智能工具：Work Rust查询引擎","ja":"AIエージェント：Work Rustクエリエンジン","ko":"AI 에이전트: Work Rust 쿼리 엔진","es":"Herramientas de AI: Motor de Consultas Rust para BigQuery...","fr":"Outils d''IA : Moteur de Requêtes Rust pour BigQuery et Po...","de":"KI-Tools: Rust-Abfragemotor für BigQuery und PostgreSQL","pt":"Ferramentas de IA: Motor de Consulta Rust para BigQuery e...","ru":"ИИ Агенты: Rust движок запросов для BigQuery и PostgreSQL","ar":"أدوات الذكاء الاصطناعي: محرك استعلام رست لبيج كويري وبوست...","en":"work"},"description":{"zh":"Work是一个Rust查询引擎，用于从多个来源读取数据，如BigQuery和PostgreSQL，使用Apache Arrow","ja":"Workは、BigQueryやPostgreSQLなどの複数のソースからデータを読み取るためのRustクエリエンジンで、Apache Arrowを使用","ko":"Work는 BigQuery 및 PostgreSQL와 같은 여러 소스에서 데이터를 읽기 위한 Rust 쿼리 엔진으로 Apache Arrow를 사용","es":"Un motor de consultas Rust para leer datos de BigQuery y PostgreSQL con Apache Arrow","fr":"Un moteur de requêtes Rust pour lire des données de BigQuery et PostgreSQL avec Apache Arrow","de":"Ein Rust-Abfragemotor zum Lesen von Daten aus BigQuery und PostgreSQL mit Apache Arrow","pt":"Um motor de consulta Rust para leitura de dados de várias fontes como BigQuery e PostgreSQL usando Apache Arrow","ru":"Rust движок запросов для чтения данных из нескольких источников, таких как BigQuery и PostgreSQL, используя Apache Arrow","ar":"محرك استعلام رست لقراءة البيانات من مصادر متعددة مثل بيج كويري وبوستجرس كول باستخدام أباتشي أرو","en":"A Rust query engine for reading data from multiple sources like BigQuery and PostgreSQL using Apache Arrow."},"definition":{"en":"A Rust query engine for reading data from multiple sources like BigQuery and PostgreSQL using Apache Arrow."},"features":{"zh":["支持多个数据源，如BigQuery和PostgreSQL","使用Apache Arrow进行数据处理","Rust编写的高性能查询引擎","支持多种数据格式","易于使用和集成"],"ja":["BigQueryやPostgreSQLなどの複数のデータソースをサポート","Apache Arrowを使用したデータ処理","Rustで書かれた高性能クエリエンジン","複数のデータ形式をサポート","使用と統合が容易"],"ko":["BigQuery 및 PostgreSQL와 같은 여러 데이터 소스를 지원","Apache Arrow를 사용한 데이터 처리","Rust로 작성된 고성능 쿼리 엔진","여러 데이터 형식을 지원","사용 및 통합이 용이"],"es":["Lee datos de BigQuery y PostgreSQL","Utiliza Apache Arrow para el procesamiento de datos","Escrito en Rust para una mayor eficiencia","Permite la lectura de datos de múltiples fuentes","Es compatible con varias bases de datos"],"fr":["Lit des données de BigQuery et PostgreSQL","Utilise Apache Arrow pour le traitement de données","Écrit en Rust pour une efficacité accrue","Permet la lecture de données à partir de plusieurs sources","Est compatible avec plusieurs bases de données"],"de":["Liest Daten aus BigQuery und PostgreSQL","Verwendet Apache Arrow für die Datenverarbeitung","In Rust geschrieben für eine höhere Effizienz","Ermöglicht das Lesen von Daten aus mehreren Quellen","Ist mit mehreren Datenbanken kompatibel"],"pt":["Leitura de dados de várias fontes","Integração com BigQuery e PostgreSQL","Uso de Apache Arrow","Desenvolvido em Rust","Suporte a consultas complexas"],"ru":["Чтение данных из нескольких источников","Интеграция с BigQuery и PostgreSQL","Использование Apache Arrow","Разработан на Rust","Поддержка сложных запросов"],"ar":["قراءة البيانات من مصادر متعددة","التكامل مع بيج كويري وبوستجرس كول","استخدام أباتشي أرو","تم تطويره بلغة رست","دعم استعلامات معقدة"]},"keywords":{"zh":["如何使用Work Rust查询引擎","Work Rust查询引擎是什么","Work Rust查询引擎替代品","Work Rust查询引擎与其他查询引擎的比较","Work Rust查询引擎安装","Work Rust查询引擎设置指南","Rust查询引擎","Apache Arrow"],"ja":["Work Rustクエリエンジンの使用方法","Work Rustクエリエンジンとは","Work Rustクエリエンジンの代替品","Work Rustクエリエンジンと他のクエリエンジンの比較","Work Rustクエリエンジンのインストール","Work Rustクエリエンジンの設定ガイド","Rustクエリエンジン","Apache Arrow"],"ko":["Work Rust 쿼리 엔진 사용 방법","Work Rust 쿼리 엔진이란","Work Rust 쿼리 엔진 대안","Work Rust 쿼리 엔진과 다른 쿼리 엔진의 비교","Work Rust 쿼리 엔진 설치","Work Rust 쿼리 엔진 설정 가이드","Rust 쿼리 엔진","Apache Arrow"],"es":["herramientas de AI","motor de consultas Rust","BigQuery","PostgreSQL","Apache Arrow","cómo usar Rust","qué es un motor de consultas Rust","alternativas a BigQuery","instalación de Rust"],"fr":["outils d''IA","moteur de requêtes Rust","BigQuery","PostgreSQL","Apache Arrow","comment utiliser Rust","qu''est-ce qu''un moteur de requêtes Rust","alternatives à BigQuery","installation de Rust"],"de":["KI-Tools","Rust-Abfragemotor","BigQuery","PostgreSQL","Apache Arrow","wie man Rust verwendet","was ist ein Rust-Abfragemotor","Alternativen zu BigQuery","Rust-Installation"],"pt":["como usar ferramentas de ia","o que é motor de consulta rust","ferramentas de ia para desenvolvedores","alternativas ao bigquery","rust vs python","instalar motor de consulta rust","guia de configuração do apache arrow"],"ru":["как использовать ии агенты","что такое rust движок запросов","ии агенты для разработчиков","альтернативы bigquery","rust vs python","установить rust движок запросов","руководство по настройке apache arrow"],"ar":["كيفية استخدام أدوات الذكاء الاصطناعي","ما هو محرك استعلام رست","أدوات الذكاء الاصطناعي للمطورين","بديل بيج كويري","رست مقابل بايثون","تثبيت محرك استعلام رست","دليل إعداد أباتشي أرو"]}},"owner":"fwojciec","repo":"quiver","repoPath":"fwojciec/quiver","stars":0,"forks":0,"updatedAt":"2026-03-04T13:07:01.740Z","topics":[],"category":"community","skillMd":{"name":"work","description":"Execute an end-to-end GitHub issue workflow: select an issue, branch, implement with tests, validate, review, and open a PR. Use when asked to work on issue X or deliver a complete implementation workflow.","bodyPreview":"# Work Issue End-to-End\n\nDrive issue work from selection to PR with minimal back-and-forth.\n\n## Phase 1: Preflight + Selection\n\n1. Confirm repo is in a safe starting state (usually clean tree on `main`).\n2. If issue number is missing, list open issues and ask user to pick one.\n3. Fetch issue details (including comments) and create branch `<number>-<kebab-title>`.\n\n## Phase 2: Implement\n\n1. Prefer TDD for behavior changes (red/green/refactor).\n2. Implement non-behavioral wiring/types directly.\n3.","body":"# Work Issue End-to-End\n\nDrive issue work from selection to PR with minimal back-and-forth.\n\n## Phase 1: Preflight + Selection\n\n1. Confirm repo is in a safe starting state (usually clean tree on `main`).\n2. If issue number is missing, list open issues and ask user to pick one.\n3. Fetch issue details (including comments) and create branch `<number>-<kebab-title>`.\n\n## Phase 2: Implement\n\n1. Prefer TDD for behavior changes (red/green/refactor).\n2. Implement non-behavioral wiring/types directly.\n3. Run `make validate` during development.\n4. Keep scope aligned with issue constraints.\n\n## Phase 3: Review\n\n1. Run `code-review` skill.\n2. Run `review-with-gemini` when available.\n3. Apply straightforward fixes automatically.\n4. If blocking feedback remains, pause and present options:\n   - fix and re-review,\n   - proceed with explicit override,\n   - stop and document learnings.\n\n## Phase 4: Finalize\n\n1. Run full checks (`make validate-full` when available, else project equivalent).\n2. Commit cleanly.\n3. Push branch and open PR with summary + test plan + `Closes #<issue>`.\n4. Comment on issue with PR link and validation status.\n\n## Phase 5: Handoff\n\nAfter PR creation, ask whether to:\n1. merge now,\n2. leave for user merge,\n3. keep iterating on branch.\n\nPrefer ending in a clean local state on latest `main` unless user wants continued branch work.\n"},"lastSynced":"2026-03-04T14:05:23.559Z","agentAnalysis":{"suitability":{"en":"Ideal for Development Agents needing streamlined issue management and Apache Arrow integration for data analysis.","zh":"适用于需要简化问题管理和Apache Arrow集成进行数据分析的开发代理。","ja":"Apache Arrowを使用したデータ分析のための問題管理をストリームライン化する必要がある開発エージェントに最適です。","ko":"데이터 분석을 위한 Apache Arrow 통합 및 문제 관리를 간소화해야 하는 개발 에이전트에게 적합합니다.","es":"Ideal para Agentes de Desarrollo que necesitan una gestión de problemas simplificada y la integración de Apache Arrow para el análisis de datos.","fr":"Idéal pour les agents de développement nécessitant une gestion de problèmes simplifiée et une intégration d''Apache Arrow pour l''analyse de données.","de":"Ideal für Entwicklungsmittel benötigende Agenten, die eine vereinfachte Problemmangement und Apache Arrow-Integration für Datenanalyse benötigen.","pt":"Ideal para Agentes de Desenvolvimento que precisam de gerenciamento de problemas simplificado e integração do Apache Arrow para análise de dados.","ru":"Идеально для агентов разработки, которым необходим упрощенный менеджмент проблем и интеграция Apache Arrow для анализа данных.","ar":"مثالي لوكلاء التطوير الذين يحتاجون إلى إدارة مشاكل مبسطة وتكامل Apache Arrow للتحليل البياني."},"recommendation":{"en":"Empowers agents to drive issue work from selection to PR with minimal back-and-forth, utilizing Rust for a query engine that reads data from multiple sources like BigQuery and PostgreSQL, and leveraging Apache Arrow for efficient data processing.","zh":"赋予代理驱动问题工作，从选择到PR，利用Rust进行查询引擎，读取来自BigQuery和PostgreSQL等多个来源的数据，并利用Apache Arrow进行高效的数据处理，减少来回操作。","ja":"エージェントに問題作業を選択からPRまで推進させる力を与え、Rustを使用したクエリエンジンでBigQueryやPostgreSQLなどの複数のソースからのデータを読み取り、Apache Arrowを使用した効率的なデータ処理を実現し、往復作業を最小限に抑えます。","ko":"에이전트가 선택에서 PR까지 문제 작업을 주도하도록 강화하고, Rust를 사용한 쿼리 엔진으로 BigQuery 및 PostgreSQL 등의 여러 소스에서 데이터를 읽어들이며, Apache Arrow를 활용한 효율적인 데이터 처리를 통해 최소한의往復 작업을 수행합니다.","es":"Permite a los agentes impulsar el trabajo de problemas desde la selección hasta PR con un mínimo de idas y venidas, utilizando Rust para un motor de consulta que lee datos de múltiples fuentes como BigQuery y PostgreSQL, y aprovechando Apache Arrow para un procesamiento de datos eficiente.","fr":"Permet aux agents de piloter le travail de problèmes de la sélection à PR avec un minimum d''allers-retours, en utilisant Rust pour un moteur de requête qui lit les données de plusieurs sources comme BigQuery et PostgreSQL, et en exploitant Apache Arrow pour un traitement de données efficace.","de":"Ermöglicht es den Agenten, die Arbeit an Problemen von der Auswahl bis zur PR mit minimalen Hin- und Her-Geschäften zu betreiben, indem Rust für einen Abfrage-Motor verwendet wird, der Daten aus mehreren Quellen wie BigQuery und PostgreSQL liest, und Apache Arrow für effizientes Datenverarbeiten nutzt.","pt":"Habilita os agentes a conduzir o trabalho de problemas desde a seleção até o PR com mínimo vaivém, utilizando Rust para um mecanismo de consulta que lê dados de múltiplas fontes como BigQuery e PostgreSQL, e aproveitando Apache Arrow para processamento eficiente de dados.","ru":"Наделяет агентов возможностью управлять работой проблем от выбора до PR с минимальным обменом, используя Rust для движка запросов, который считывает данные из нескольких источников, таких как BigQuery и PostgreSQL, и использует Apache Arrow для эффективной обработки данных.","ar":"يمنح الوكلاء القدرة على تشغيل عمل المشاكل من التحديد إلى PR مع الحد الأدنى من التبادل، مستخدمين Rust لمحرك استعلام يقرأ البيانات من عدة مصادر مثل BigQuery وPostgreSQL، وتفعيل Apache Arrow للمعالجة الفعالة للبيانات."},"useCases":{"en":["Automating issue tracking with Apache Arrow","Implementing Test-Driven Development for behavior changes","Streamlining code review with direct implementation of non-behavioral wiring/types"],"zh":["使用Apache Arrow自动跟踪问题","为行为更改实现测试驱动开发","使用直接实现非行为连接/类型来简化代码审查"],"ja":["Apache Arrowを使用した問題追跡の自動化","動作の変更に対するテスト駆動開発の実装","非動作的ワイヤリング/タイプの直接実装によるコードレビューのストリームライン化"],"ko":["Apache Arrow를 사용한 문제 추적 자동화","행동 변경에 대한 테스트 주도 개발 구현","비행동 연결/타입의 직접 구현을 통한 코드 리뷰 간소화"],"es":["Automatización del seguimiento de problemas con Apache Arrow","Implementación del Desarrollo Dirigido por Pruebas para cambios de comportamiento","Optimización de la revisión de código con la implementación directa de cableado/tipos no comportamentales"],"fr":["Automatisation du suivi des problèmes avec Apache Arrow","Mise en œuvre du Développement Piloté par les Tests pour les changements de comportement","Optimisation de la revue de code avec la mise en œuvre directe de câblage/types non comportementaux"],"de":["Automatisierung der Problemmverfolgung mit Apache Arrow","Implementierung von Testgetriebenem Entwickeln für Verhaltensänderungen","Optimierung der Code-Überprüfung mit direkter Implementierung von nicht-verhaltensbezogenem Verdrahtung/Typen"],"pt":["Automatizar o acompanhamento de problemas com Apache Arrow","Implementar Desenvolvimento Dirigido por Testes para alterações de comportamento","Simplificar a revisão de código com implementação direta de fiação/tipos não comportamentais"],"ru":["Автоматизировать отслеживание проблем с помощью Apache Arrow","Реализовать разработку, управляемую тестами, для изменений поведения","Упростить проверку кода с прямой реализацией нефункциональной проводки/типов"],"ar":["أتمتة تتبع المشاكل مع Apache Arrow","تنفيذ التطوير الموجه بالاختبار لتغييرات السلوك","تبسيط مراجعة الكود مع التنفيذ المباشر للتركيبات/الأنواع غير السلوكية"]},"limitations":{"en":["Requires Rust environment","Limited to BigQuery and PostgreSQL data sources","Needs a clean repository tree on ''main'' branch"],"zh":["需要Rust环境","仅限BigQuery和PostgreSQL数据源","需要''main''分支上的干净存储库树"],"ja":["Rust環境が必要","BigQueryとPostgreSQLのデータソースのみ","''main''ブランチ上にクリーンなリポジトリツリーが必要"],"ko":["Rust 환경이 필요함","BigQuery 및 PostgreSQL 데이터 소스에만 제한됨","''main'' 브랜치에 깨끗한 저장소 트리가 필요함"],"es":["Requiere un entorno Rust","Limitado a fuentes de datos BigQuery y PostgreSQL","Necesita un árbol de repositorio limpio en la rama ''main''"],"fr":["Nécessite un environnement Rust","Limité aux sources de données BigQuery et PostgreSQL","Nécessite un arbre de référentiel propre sur la branche ''main''"],"de":["Benötigt eine Rust-Umgebung","Begrenzt auf BigQuery- und PostgreSQL-Datenquellen","Benötigt einen sauberen Repository-Baum auf dem ''main''-Zweig"],"pt":["Exige ambiente Rust","Limitado a fontes de dados BigQuery e PostgreSQL","Necessita de uma árvore de repositório limpa na branch ''main''"],"ru":["Требует среды Rust","Ограничен источниками данных BigQuery и PostgreSQL","Требует чистого дерева репозитория в ветке ''main''"],"ar":["يتطلب بيئة Rust","محدود بمصادر البيانات BigQuery وPostgreSQL","يتطلب شجرة مستودع نظيفة في الفرع ''main''"]},"version":3},"contentHash":"494b4eca63cbf4369e0c7537dc15d4eac6a40d4b74321055df1b730bfa75f6a7","qualityScore":20}');
