INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('abpaul/codex-compound-engineering/cloud-transfer', 'cloud-transfer', 'abpaul', 'codex-compound-engineering', 'community', 'cloud-transfer abpaul codex-compound-engineering community 云传输AI代理是基于Rails的Codex技能，提供高效的数据传输和处理解决方案 クラウド転送AIエージェントは、EveryのコンパウンドエンジニアリングにインスパイアされたRailsベースのCodexスキルです 클라우드 전송 AI 에이전트는 레일즈 기반의 코덱스 스킬로 효율적인 데이터 전송과 처리를 제공합니다 Cloud-transfer es una habilidad de AI Agent inspirada en la ingeniería compuesta de Every, diseñada para proyectos de Rails Cloud-transfer est une compétence d''agent IA inspirée de l''ingénierie composite d''Every, conçue pour les projets Rails Cloud-transfer ist eine Fähigkeit des AI-Agents, die von Every''s Composite-Engineering inspiriert ist und für Rails-Projekte konzipiert ist Os agentes de transferência em nuvem são inspirados na engenharia composta da Every, permitindo uma integração perfeita com o Rails Облачные агенты передачи, вдохновленные составной инженерией Every, обеспечивают идеальную интеграцию с Rails وكلاء النقل السحابي يستندون إلى هندسة مركبة من Every، مما يسمح بالتكامل المثالي مع الريلز Rails-first Codex skills and AGENTS setup inspired by Every''s compound engineering 云传输AI代理 基于Rails的Codex技能 高效的数据传输和处理 云计算 数据传输技术 AI工具 如何使用云传输AI代理 云传输AI代理安装 云传输AI代理设置指南 Rails-first Codex skills and AGENTS setup inspired by Every''s compound engineering ');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('joolbits/latitude/latitude-biome-authority', 'community', 'joolbits', 'latitude', 'joolbits/latitude', 'latitude-biome-authority', 0, 0, 20, '2026-03-04T13:07:01.813Z', '2026-03-04T14:34:57.358Z', 'afa1a684f8fe9da6789d820ab8d3ef8fd40650d06bcaf20b0b938bbeff16dc8b', '{"id":"joolbits/latitude/latitude-biome-authority","name":"latitude-biome-authority","description":{"zh":"latitude-biome-authority 是一个 Minecraft Fabric 模組，提供确定性纬度基于生物群落带的功能。使用该模組，可以创建更真实的 globe-style 世界","ja":"latitude-biome-authorityは、Minecraft Fabricモッドの決定的な緯度ベースの生物群落帯を提供するモッドです。よりリアルな globe-style 世界を作成することができます","ko":"latitude-biome-authority는 Minecraft Fabric 모드의 결정적인 위도 기반 생물군계 밴드를 제공하는 모드입니다. 더 리얼한 globe-style 세계를 만들 수 있습니다","es":"El mod latitude-biome-authority es una herramienta de AI para Minecraft que ofrece bandas de biomas deterministas basadas en la latitud para mundos de estilo globo","fr":"Le mod latitude-biome-authority est un outil d''IA pour Minecraft qui propose des bandes de biomes déterministes basées sur la latitude pour les mondes de style globe","de":"Das Mod latitude-biome-authority ist ein KI-Tool für Minecraft, das deterministische Biombänder basierend auf der Breite für Welten im Globus-Stil bietet","pt":"O mod latitude-biome-authority é uma ferramenta de IA para Minecraft Fabric que cria bandas de biomas determinísticas baseadas em latitude","ru":"Мод latitude-biome-authority — это инструмент ИИ для Minecraft Fabric, создающий детерминированные ленточные биомы на основе широты","ar":"مود latitude-biome-authority هو أداة ذكاء اصطناعي لمايكرافت فابريك يخلق حزمًا بيئية محددة بالخطوط العرض","en":"Minecraft Fabric mod — deterministic latitude-based biome bands for globe-style worlds."},"seo":{"title":{"zh":"AIエージェント：latitude-biome-authority Minecraft Fabric 模組","ja":"AIエージェント：latitude-biome-authority Minecraft Fabric モッド"