INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('NoCodeify/aeo/playbook', 'playbook', 'NoCodeify', 'aeo', 'community', 'playbook NoCodeify aeo community Playbook是一款AEO协议工具包，用于优化AI工具的性能和安全性。它支持ChatGPT、Gemini和Google审计 PlaybookはAEOプロトコルツールキットであり、AIエージェントのパフォーマンスとセキュリティを最適化します。ChatGPT、Gemini、Google監査をサポート Playbook는 AI 에이전트의 성능과 보안을 최적화하는 AEO 프로토콜 툴킷입니다. ChatGPT, Gemini, Google 감사 기능을 지원 El playbook es un kit de herramientas AEO Protocol para servidores MCP de ChatGPT, Gemini y auditorías de Google Le playbook est un kit d''outils AEO Protocol pour les serveurs MCP de ChatGPT, Gemini et audits Google Das Playbook ist ein AEO-Protocol-Toolkit für MCP-Server von ChatGPT, Gemini und Google-Audits O Playbook AEO Protocol é uma ferramenta de otimização para MCP servers, ChatGPT, Gemini e auditorias do Google Playbook AEO Protocol - набор инструментов для ИИ Агентов, MCP серверов, ChatGPT, Gemini и аудитов Google playbook بروتوكول AEO هو أداة تحسين لخادم MCP، ChatGPT، Gemini وتحليلات جوجل AEO (Answer Engine Optimization) Protocol toolkit - MCP servers for ChatGPT, Gemini, and Google audits AI工具优化 AEO协议工具包 MCP服务器 ChatGPT优化 Gemini优化 Google审计支持 如何使用Playbook Playbook教程 AI工具比较 AEO (Answer Engine Optimization) Protocol toolkit - MCP servers for ChatGPT, Gemini, and Google audits');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('freelawproject/wiki/shipit', 'community', 'freelawproject', 'wiki', 'freelawproject/wiki', 'shipit', 0, 0, 20, '2026-03-04T01:34:50Z', '2026-03-04T03:51:11.280Z', '3a358ca56a7083f2e60b99782a43d4d81ff4e5558b442f56b9fade13680987d9', '{"id":"freelawproject/wiki/shipit","name":"shipit","description":{"zh":"Shipit 是一个基于开放的维基平台，允许 FLP 员工创建和共享内容","ja":"Shipit は、FLP 職員がコンテンツを作成および共有できるオープンなウィキプラットフォームです","ko":"Shipit은 FLP 직원이 콘텐츠를 생성하고 공유할 수 있는 공개 위키 플랫폼입니다","es":"Shipit es una wiki de código abierto que permite la creación de páginas y directorios privados y restringidos para el personal de FLP","fr":"Shipit est une wiki codée vibe qui permet la création de pages et de répertoires privés et restreints pour le personnel FLP","de":"Shipit ist ein vibe-codiertes Wiki, das die Erstellung privater und eingeschränkter Seiten und Verzeichnisse für FLP-Mitarbeiter ermöglicht","pt":"O shipit é uma wiki de código aberto que permite a criação de páginas e diretórios privados e restritos para equipes de desenvolvimento","ru":"Shipit - это вики с открытым кодом, которая позволяет создавать приватные и ограниченные страницы и директории для команд разработчиков","ar":"shipit هو ويكي مفتوح المصدر يسمح بإنشاء صفحات ومجلدات خاصة ومحدودة للفرق التطويرية","en":"A vibe-coded wiki for use by FLP staff that biases towards openness, but allows private and restricted pages and directories"},"seo":{"title":{"zh":"AI工具 Shipit：基于开放的维基平台","ja":"AIエージェント Shipit：オープンなウィキプラットフォーム","ko":"AI 에이전트 Shipit: 공개 위키 플랫폼","es":"Herramientas de AI: Shipit, wiki de código abierto","fr":"Outils d''IA: Shipit, wiki codée vibe","de":"KI-Tools: Shipit, vibe-codiertes Wiki","pt":"Ferramentas de IA: shipit - Wiki de Código Aberto","ru":"ИИ Агенты: shipit - Вики с открытым кодом","ar":"أدوات الذكاء الاصطناعي: shipit - ويكي مفتوح المصدر","en":"shipit"},"descript