INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('forcedotcom/apex-language-support/packageJson', 'packageJson', 'forcedotcom', 'apex-language-support', 'community', 'packageJson forcedotcom apex-language-support community packageJson 是一个实验性的 AI 智能工具，提供 Node.js 包管理功能 packageJsonは実験的なAIエージェントであり、Node.jsパッケージ管理機能を提供する packageJson는 실험적인 AI 에이전트로 Node.js 패키지 관리 기능을 제공합니다 PackageJson es una herramienta de AI experimental para desarrolladores, no recomendada para uso actual PackageJson est un outil d''IA expérimental pour les développeurs, non recommandé pour une utilisation actuelle PackageJson ist ein experimentelles KI-Tool für Entwickler, nicht für den aktuellen Gebrauch empfohlen O packageJson é uma ferramenta de IA experimental para desenvolvedores, com funcionalidades em desenvolvimento. ИИ Агент packageJson - это экспериментальная ИИ-инструмент для разработчиков с функциями в стадии разработки. أداة الذكاء الاصطناعي packageJson هي أداة تجريبية للمطورين، مع ميزات قيد التطوير. experimental, do not use 如何使用 packageJson 什么是 packageJson packageJson 安装指南 packageJson 代替方案 packageJson 与 npm 比较 Node.js 包管理工具 experimental, do not use');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('cubenlp/ChatTool/dns', 'community', 'cubenlp', 'ChatTool', 'cubenlp/ChatTool', 'dns', 0, 0, 18, '2026-03-04T13:07:01.664Z', '2026-03-04T13:21:03.552Z', 'bf23ce97f2c3bde2e3f5f9016548ed5ff7bc396bc1af50c2684b943015ffa8de', '{"id":"cubenlp/ChatTool/dns","name":"dns","description":{"zh":"DNS工具包允许您管理DNS记录和SSL证书，实现域名管理的自动化。支持列表域名、获取记录、添加/删除记录、动态DNS和Let''s Encrypt证书","ja":"DNSツールキットを使用してDNSレコードとSSL証明書を管理し、ドメイン管理を自動化。ドメインの一覧表示、レコードの取得、レコードの追加/削除、動的DNS、Let''s Encrypt証明書をサポート","ko":"DNS 툴킷을 사용하여 DNS 기록과 SSL 인증서를 관리하여 도메인 관리를 자동화한다. 도메인 목록 표시, 기록 조회, 기록 추가/삭제, 동적 DNS, Let''s Encrypt 인증서를 지원","es":"El toolkit de DNS permite a los desarrolladores gestionar registros DNS y certificados SSL de manera eficiente.","fr":"L''outil DNS permet aux développeurs de gérer les enregistrements DNS et les certificats SSL de manière efficace.","de":"Das DNS-Toolkit ermöglicht es Entwicklern, DNS-Einträge und SSL-Zertifikate effizient zu verwalten.","pt":"O Gerenciador de DNS é uma ferramenta para gerenciar registros DNS e certificados SSL. Ele permite listar domínios, obter registros e modificar registros DNS.","ru":"Менеджер DNS - это инструмент для управления записями DNS и сертификатами SSL. Он позволяет перечислять домены, получать записи и изменять записи DNS.","ar":"مدير DNS هو أداة لإدارة سجلات DNS وشهادات SSL. يسمح بقائمة النطاقات، الحصول على السجلات وتعديل سجلات DNS.","en":"Toolkit for Chat API."},"seo":{"title":{"zh":"DNS工具包 - Chat API域名管理","ja":"DNSツールキット - Chat APIドメイン管理","ko":"DNS 툴킷 - Chat API 도메인 관리","es":"Herramienta DNS para desarrolladores","fr":"Outil DNS pour développeurs","de":"DNS-Toolkit für Entwickler","pt":"Gerenciador de DNS: Ferramentas para Desenvolvedores","ru":"Менеджер DNS: Инструменты для разработчиков","ar":"مدير DNS: أدوات للمطورين","en":"dns"},"description":{"zh":"DNS工具包允许您管理DNS记录和SSL证书，实现域名管理的自动化。支持列表域名、获取记录、添加/删除记录、动态DNS和Let''s Encrypt证书","ja":"DNSツールキットを使用してDNSレコードとSSL証明書を管理し、ドメイン管理を自動化。ドメインの一覧表示、レコードの取得、レコードの追加/削除、動的DNS、Let''s Encrypt証明書をサポート","ko":"DNS 툴킷을 사용하여 DNS 기록과 SSL 인증서를 관리하여 도메인 관리를 자동화한다. 도메인 목록 표시, 기록 조회, 기록 추가/삭제, 동적 DNS, Let''s Encrypt 인증서를 지원","es":"El toolkit de DNS permite a los desarrolladores gestionar registros DNS y certificados SSL de manera eficiente.","fr":"L''outil DNS permet aux développeurs de gérer les enregistrements DNS et les certificats SSL de manière efficace.","de":"Das DNS-Toolkit ermöglicht es Entwicklern, DNS-Einträge und SSL-Zertifikate effizient zu verwalten.","pt":"O Gerenciador de DNS é uma ferramenta para gerenciar registros DNS e certificados SSL. Ele permite listar domínios, obter registros e modificar registros DNS.","ru":"Менеджер DNS - это инструмент для управления записями DNS и сертификатами SSL. Он позволяет перечислять домены, получать записи и изменять записи DNS.","ar":"مدير DNS هو أداة لإدارة سجلات DNS وشهادات SSL. يسمح بقائمة النطاقات، الحصول على السجلات وتعديل سجلات DNS.","en":"Toolkit for Chat API."},"definition":{"en":"Toolkit for Chat API."},"features":{"zh":["列表域名","获取DNS记录","添加/删除DNS记录","动态DNS","Let''s Encrypt证书"],"ja":["ドメインの一覧表示","DNSレコードの取得","レコードの追加/削除","動的DNS","Let''s Encrypt証明書"],"ko":["도메인 목록 표시","DNS 기록 조회","기록 추가/삭제","동적 DNS","Let''s Encrypt 인증서"],"es":["Listado de dominios","Recuperación de registros DNS","Adición y eliminación de registros DNS","Actualización de registros DNS dinámicos","Solicitud y renovación de certificados SSL"],"fr":["Liste des domaines","Récupération des enregistrements DNS","Ajout et suppression d''enregistrements DNS","Mise à jour des enregistrements DNS dynamiques","Demande et renouvellement de certificats SSL"],"de":["Domain-Liste","Abrufen von DNS-Einträgen","Hinzufügen und Löschen von DNS-Einträgen","Aktualisieren von dynamischen DNS-Einträgen","Anfordern und Erneuern von SSL-Zertifikaten"],"pt":["Listar domínios","Obter registros DNS","Modificar registros DNS","Atualizar registros DDNS","Solicitar certificados SSL"],"ru":["Перечислять домены","Получать записи DNS","Изменять записи DNS","Обновлять записи DDNS","Запрашивать сертификаты SSL"],"ar":["قائمة النطاقات","الحصول على السجلات DNS","تعديل سجلات DNS","تحديث سجلات DDNS","طلب شهادات SSL"]},"keywords":{"zh":["DNS管理","Chat API","域名管理","SSL证书","动态DNS","Let''s Encrypt"],"ja":["DNS管理","Chat API","ドメイン管理","SSL証明書","動的DNS","Let''s Encrypt"],"ko":["DNS 관리","Chat API","도메인 관리","SSL 인증서","동적 DNS","Let''s Encrypt"],"es":["dns","registros dns","certificados ssl","desarrollo web","herramientas de dns","gestión de dns"],"fr":["dns","enregistrements dns","certificats ssl","développement web","outils dns","gestion dns"],"de":["dns","dns-einträge","ssl-zertifikate","webentwicklung","dns-tools","dns-verwaltung"],"pt":["dns","gerenciador de dns","registros dns","certificados ssl","desenvolvimento web","ferramentas de desenvolvimento"],"ru":["dns","менеджер dns","записи dns","сертификаты ssl","веб-разработка","инструменты разработки"],"ar":["dns","مدير dns","سجلات dns","شهادات ssl","تطوير الويب","أدوات التطوير"]}},"owner":"cubenlp","repo":"ChatTool","repoPath":"cubenlp/ChatTool","stars":0,"forks":0,"updatedAt":"2026-03-04T13:07:01.664Z","topics":[],"category":"community","skillMd":{"name":"dns","description":"Manages DNS records, DDNS, and SSL certificates using ChatTool. Invoke when user wants to list domains, modify DNS records, or update certificates.","bodyPreview":"# DNS Manager\n\nThis skill allows you to manage DNS records and SSL certificates using the ChatTool library.\n\n## Capabilities\n\n- **List Domains**: View all domains under the configured account (Aliyun/Tencent).\n- **Get Records**: Retrieve DNS records for a specific domain.\n- **Add/Delete Records**: Modify DNS records.\n- **DDNS**: Update dynamic DNS records.\n- **SSL Certificates**: Request or renew Let''s Encrypt certificates.\n\n## Tools\n\nYou should use the available MCP tools for these operations:","body":"# DNS Manager\n\nThis skill allows you to manage DNS records and SSL certificates using the ChatTool library.\n\n## Capabilities\n\n- **List Domains**: View all domains under the configured account (Aliyun/Tencent).\n- **Get Records**: Retrieve DNS records for a specific domain.\n- **Add/Delete Records**: Modify DNS records.\n- **DDNS**: Update dynamic DNS records.\n- **SSL Certificates**: Request or renew Let''s Encrypt certificates.\n\n## Tools\n\nYou should use the available MCP tools for these operations:\n- `dns_list_domains`\n- `dns_get_records`\n- `dns_add_record`\n- `dns_delete_record`\n- `dns_ddns_update`\n- `dns_cert_update`\n\n## Configuration\n\nEnsure the environment variables for the DNS provider are set (e.g., `ALIBABA_CLOUD_ACCESS_KEY_ID`, `TENCENT_CLOUD_SECRET_ID`, etc.).\n"},"lastSynced":"2026-03-04T13:21:03.552Z","agentAnalysis":{"suitability":{"en":"Ideal for Cloud Management Agents requiring automated DNS record management and SSL certificate handling.","zh":"适用于需要自动化 DNS 记录管理和 SSL 证书处理的云管理代理。","ja":"自動化された DNS レコード管理と SSL 証明書の処理を必要とするクラウド管理エージェントに最適です。","ko":"자동화된 DNS 레코드 관리 및 SSL 인증서 처리가 필요한 클라우드 관리 에이전트에 적합합니다.","es":"Ideal para Agentes de Administración de Cloud que requieren una gestión automatizada de registros DNS y manejo de certificados SSL.","fr":"Idéal pour les agents de gestion Cloud nécessitant une gestion automatisée des enregistrements DNS et une gestion de certificats SSL.","de":"Ideal für Cloud-Management-Agenten, die eine automatisierte DNS-Record-Verwaltung und SSL-Zertifikatshandhabung erfordern.","pt":"Ideal para agentes de gerenciamento de nuvem que exigem gerenciamento automatizado de registros DNS e manipulação de certificados SSL.","ru":"Идеально подходит для агентов управления облачными системами, требующих автоматизированного управления записями DNS и обработки сертификатов SSL.","ar":"مثالي لعميل إدارة السحابة الذي يتطلب إدارة سجلات DNS وتعامل شهادات SSL أوتوماتيكيا."},"recommendation":{"en":"Empowers agents to manage DNS records and SSL certificates using the ChatTool library, enabling seamless domain management and dynamic DNS updates via protocols like Let''s Encrypt.","zh":"通过 ChatTool 库赋予代理管理 DNS 记录和 SSL 证书的能力，实现无缝的域名管理和通过 Let''s Encrypt 等协议的动态 DNS 更新。","ja":"ChatTool ライブラリを使用して、エージェントが DNS レコードと SSL 証明書を管理できるようにし、ドメイン管理を簡素化し、Let''s Encrypt などのプロトコルを介した動的 DNS 更新を可能にします。","ko":"ChatTool 라이브러리를 사용하여 에이전트가 DNS 레코드 및 SSL 인증서를 관리할 수 있도록 하여 도메인 관리를 간소화하고 Let''s Encrypt 등의 프로토콜을 통해 동적 DNS 업데이트를 가능하게 합니다.","es":"Habilita a los agentes a gestionar registros DNS y certificados SSL utilizando la biblioteca ChatTool, lo que permite una gestión de dominios sin problemas y actualizaciones de DNS dinámicas a través de protocolos como Let''s Encrypt.","fr":"Permet aux agents de gérer les enregistrements DNS et les certificats SSL en utilisant la bibliothèque ChatTool, ce qui permet une gestion de domaine transparente et des mises à jour DNS dynamiques via des protocoles comme Let''s Encrypt.","de":"Ermächtigt die Agenten, DNS-Records und SSL-Zertifikate mit der ChatTool-Bibliothek zu verwalten, wodurch eine nahtlose Domainverwaltung und dynamische DNS-Updates über Protokolle wie Let''s Encrypt ermöglicht werden.","pt":"Habilita os agentes a gerenciar registros DNS e certificados SSL usando a biblioteca ChatTool, permitindo gerenciamento de domínio sem interrupções e atualizações de DNS dinâmicas via protocolos como Let''s Encrypt.","ru":"Наделяет агентов возможностью управлять записями DNS и сертификатами SSL с помощью библиотеки ChatTool, что позволяет выполнять бесшовное управление доменом и динамические обновления DNS через протоколы, такие как Let''s Encrypt.","ar":"يتمكن العميل من إدارة سجلات DNS وشهادات SSL باستخدام مكتبة ChatTool، مما يسمح بإدارة النطاقات بدون انقطاع وتحديثات DNS ديناميكية عبر بروتوكولات مثل Let''s Encrypt."},"useCases":{"en":["Automating DNS record updates for dynamic IP addresses","Generating and renewing SSL certificates for secured domains","Debugging DNS record configuration issues for Aliyun/Tencent domains"],"zh":["自动更新动态 IP 地址的 DNS 记录","为安全域生成和更新 SSL 证书","调试 Aliyun/Tencent 域的 DNS 记录配置问题"],"ja":["動的 IP アドレスの DNS レコードを自動更新する","セキュア ドメイン用の SSL 証明書を生成および更新する","Aliyun/Tencent ドメインの DNS レコード構成の問題をデバッグする"],"ko":["동적 IP 주소의 DNS 레코드를 자동 업데이트하는 것","보안 도메인에 대한 SSL 인증서를 생성 및 갱신하는 것","Aliyun/Tencent 도메인의 DNS 레코드 구성 문제를 디버깅하는 것"],"es":["Automatización de actualizaciones de registros DNS para direcciones IP dinámicas","Generación y renovación de certificados SSL para dominios seguros","Depuración de problemas de configuración de registros DNS para dominios Aliyun/Tencent"],"fr":["Automatisation des mises à jour des enregistrements DNS pour les adresses IP dynamiques","Génération et renouvellement de certificats SSL pour les domaines sécurisés","Débogage des problèmes de configuration des enregistrements DNS pour les domaines Aliyun/Tencent"],"de":["Automatisierung von DNS-Record-Aktualisierungen für dynamische IP-Adressen","Generierung und Erneuerung von SSL-Zertifikaten für gesicherte Domains","Fehlerbehebung bei der Konfiguration von DNS-Records für Aliyun/Tencent-Domains"],"pt":["Automatizar atualizações de registros DNS para endereços IP dinâmicos","Gerar e renovar certificados SSL para domínios seguros","Depurar problemas de configuração de registros DNS para domínios Aliyun/Tencent"],"ru":["Автоматизировать обновления записей DNS для динамических IP-адресов","Генерировать и продлевать сертификаты SSL для защищенных доменов","Отлаживать проблемы конфигурации записей DNS для доменов Aliyun/Tencent"],"ar":["توفير تحديثات سجلات DNS أوتوماتيكيا لمعرفات IP الديناميكية","إصدار وتجديد شهادات SSL للأماكن الآمنة","تصحيح أخطاء في تكوين سجلات DNS لأماكن Aliyun/Tencent"]},"limitations":{"en":["Requires configured account with Aliyun/Tencent","Limited to Let''s Encrypt certificates"],"zh":["需要配置 Aliyun/Tencent 账户","仅限 Let''s Encrypt 证书"],"ja":["Aliyun/Tencent アカウントの設定が必要","Let''s Encrypt 証明書のみ"],"ko":["Aliyun/Tencent 계정 구성이 필요","Let''s Encrypt 인증서만"],"es":["Requiere una cuenta configurada con Aliyun/Tencent","Limitado a certificados Let''s Encrypt"],"fr":["Nécessite un compte configuré avec Aliyun/Tencent","Limité aux certificats Let''s Encrypt"],"de":["Benötigt ein konfiguriertes Konto mit Aliyun/Tencent","Begrenzt auf Let''s Encrypt-Zertifikate"],"pt":["Exige conta configurada com Aliyun/Tencent","Limitado a certificados Let''s Encrypt"],"ru":["Требует настроенного аккаунта с Aliyun/Tencent","Ограничен сертификатами Let''s Encrypt"],"ar":["يتطلب حسابا مضبوطا مع Aliyun/Tencent","محدود بشهادات Let''s Encrypt"]},"version":3},"contentHash":"bf23ce97f2c3bde2e3f5f9016548ed5ff7bc396bc1af50c2684b943015ffa8de","qualityScore":18}');
