INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('ojowwalker77/Claude-Matrix/Matrix List', 'Matrix List', 'ojowwalker77', 'Claude-Matrix', 'community', 'Matrix List ojowwalker77 Claude-Matrix community Matrix List是Claude on Rails工具系统的一部分，用于构建和管理AI Agents Matrix ListはClaude on Railsツールシステムの一部分で、AI Agentsの構築と管理を行う Matrix List는 Claude on Rails 툴 시스템의 일부입니다. AI Agents의 구축과 관리를 위해 설계되었습니다 Matrix List es un sistema de herramientas para Claude Code que permite a los desarrolladores crear soluciones personalizadas con inteligencia artificial Matrix List est un système d''outils pour Claude Code qui permet aux développeurs de créer des solutions personnalisées avec l''intelligence artificielle Matrix List ist ein Tooling-System für Claude Code, das es Entwicklern ermöglicht, individuelle Lösungen mit Künstlicher Intelligenz zu erstellen O Matrix List é uma ferramenta de código aberto para Claude, permitindo a criação de listas personalizadas e a integração com o Claude on Rails Matrix List - это инструмент с открытым исходным кодом для Claude, позволяющий создавать пользовательские списки и интегрироваться с Claude on Rails Matrix List هو أداة مفتوحة المصدر لبرنامج Claude، يسمح بإنشاء قوائم مخصصة ودمجها مع Claude on Rails Claude on Rails - Tooling System for Claude Code. AI Matrix List Claude on Rails工具系统 AI Agents构建和管理 Python编程语言 JavaScript编程语言 如何使用AI Matrix List AI Matrix List vs 其他工具 Claude on Rails - Tooling System for Claude Code.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('sammcj/agentic-coding/code-simplification', 'community', 'sammcj', 'agentic-coding', 'sammcj/agentic-coding', 'code-simplification', 0, 0, 18, '2026-03-04T13:07:01.675Z', '2026-03-04T13:23:59.593Z', 'e7ea6566174e298206fe51ccd8cd3e113aa1c133730c2ff5d2bb139039eb3b0e', '{"id":"sammcj/agentic-coding/code-simplification","name":"code-simplification","description":{"zh":"代码简化工具使用Agentic Coding Rules和模板来简化代码","ja":"コード簡略化ツールはAgentic Coding Rulesとテンプレートを使用してコードを簡略化する","ko":"코드 간소화 도구는 Agentic Coding Rules와 템플릿을 사용하여 코드를 간소화합니다","es":"La simplificación de código es crucial para los desarrolladores que trabajan con Agentes de IA. Agentic ofrece reglas y plantillas de codificación para simplificar el proceso.","fr":"La simplification de code est cruciale pour les développeurs qui travaillent avec les Agents d''IA. Agentic propose des règles et des modèles de codage pour simplifier le processus.","de":"Die Code-Vereinfachung ist für Entwickler, die mit KI-Agents arbeiten, von entscheidender Bedeutung. Agentic bietet Coding-Regeln und -Vorlagen, um den Prozess zu vereinfachen.","pt":"A simplificação de código é uma técnica que ajuda a melhorar a legibilidade e manutenção do código","ru":"Упрощение кода - это техника, которая помогает улучшить читаемость и поддержку кода","ar":"تبسيط الكود هو تقنية تساعد على تحسين القراءة وصيانة الكود","en":"Agentic Coding Rules, Templates etc..."},"seo":{"title":{"zh":"AI智能代码简化工具","ja":"AIエージェントによるコード簡略化","ko":"AI 에이전트 코드 간소화","es":"Herramientas de simplificación de código para Agentes de IA","fr":"Outils de simplification de code pour les Agents d''IA","de":"Code-Vereinfachungstools für KI-Agents","pt":"Ferramentas de Simplificação de Código para Desenvolvedores","ru":"ИИ Агенты: Упрощение Код для Разработчиков","ar":"أدوات تبسيط الكود للمانحين","en":"code-simplification"},"description":{"zh":"代码简化工具使用Agentic Coding Rules和模板来简化代码","ja":"コード簡略化ツールはAgentic Coding Rulesとテンプレートを使用してコードを簡略化する","ko":"코드 간소화 도구는 Agentic Coding Rules와 템플릿을 사용하여 코드를 간소화합니다","es":"La simplificación de código es crucial para los desarrolladores que trabajan con Agentes de IA. Agentic ofrece reglas y plantillas de codificación para simpl...","fr":"La simplification de code est cruciale pour les développeurs qui travaillent avec les Agents d''IA. Agentic propose des règles et des modèles de codage pour s...","de":"Die Code-Vereinfachung ist für Entwickler, die mit KI-Agents arbeiten, von entscheidender Bedeutung. Agentic bietet Coding-Regeln und -Vorlagen, um den Proze...","pt":"A simplificação de código é uma técnica que ajuda a melhorar a legibilidade e manutenção do código","ru":"Упрощение кода - это техника, которая помогает улучшить читаемость и поддержку кода","ar":"تبسيط الكود هو تقنية تساعد على تحسين القراءة وصيانة الكود","en":"Agentic Coding Rules, Templates etc..."},"definition":{"en":"Agentic Coding Rules, Templates etc..."},"features":{"zh":["支持Agentic Coding Rules","提供代码模板","简化代码结构","提高代码可读性","支持多种编程语言"],"ja":["Agentic Coding Rulesをサポート","コードテンプレートを提供","コード構造を簡略化","コードの可読性を向上","多くのプログラミング言語をサポート"],"ko":["Agentic Coding Rules 지원","코드 템플릿 제공","코드 구조 간소화","코드 가독성 향상","다중 프로그래밍 언어 지원"],"es":["Reglas de codificación personalizadas","Plantillas de codificación predefinidas","Compatibilidad con múltiples lenguajes de programación","Integración con herramientas de desarrollo populares","Mejora de la legibilidad y el mantenimiento del código"],"fr":["Règles de codage personnalisées","Modèles de codage prédéfinis","Compatibilité avec plusieurs langages de programmation","Intégration avec des outils de développement populaires","Amélioration de la lisibilité et de la maintenance du code"],"de":["Benutzerdefinierte Coding-Regeln","Vordefinierte Coding-Vorlagen","Kompatibilität mit mehreren Programmiersprachen","Integration mit beliebten Entwicklungstools","Verbesserung der Lesbarkeit und Wartbarkeit des Codes"],"pt":["Regras de codificação agêntica","Modelos e templates personalizáveis","Integração com React, Python e Node.js","Suporte à linha de comando (CLI)","Melhoria da legibilidade e manutenção do código"],"ru":["Правила кодирования ИИ Агентов","Пользовательские шаблоны и модели","Интеграция с React, Python и Node.js","Поддержка командной строки (CLI)","Улучшение читаемости и поддержки кода"],"ar":["قواعد التكوين للأدوات","نماذج وقوالب قابلة للتخصيص","التكامل مع React و Python و Node.js","دعم سطر الأوامر (CLI)","تحسين القراءة وصيانة الكود"]},"keywords":{"zh":["如何使用AI代码简化工具","什么是代码简化","AI代码简化工具替代品","代码简化工具安装","代码简化工具设置指南","代码简化工具与其他工具比较"],"ja":["AIエージェントを使用してコードを簡略化する方法","コード簡略化とは","AIエージェントコード簡略化ツールの代替","コード簡略化ツールのインストール","コード簡略化ツールの設定ガイド","コード簡略化ツールと他のツールの比較"],"ko":["AI 에이전트를 사용하여 코드를 간소화하는 방법","코드 간소화란","AI 에이전트 코드 간소화 도구 대안","코드 간소화 도구 설치","코드 간소화 도구 설정 가이드","코드 간소화 도구와 다른 도구 비교"],"es":["cómo simplificar código","herramientas de simplificación de código","Agentes de IA","reglas de codificación","plantillas de codificación","mejora de la legibilidad del código","alternativas a [competidor]"],"fr":["comment simplifier le code","outils de simplification de code","Agents d''IA","règles de codage","modèles de codage","amélioration de la lisibilité du code","alternatives à [competidor]"],"de":["wie man Code vereinfacht","Code-Vereinfachungstools","KI-Agents","Coding-Regeln","Coding-Vorlagen","Verbesserung der Lesbarkeit des Codes","Alternativen zu [competidor]"],"pt":["como usar ferramentas de simplificação de código","o que é simplificação de código","ferramentas de simplificação de código para desenvolvedores","simplificação de código em React","simplificação de código em Python","guia de instalação de ferramentas de simplificação de código"],"ru":["как использовать инструменты упрощения кода","что такое упрощение кода","инструменты упрощения кода для разработчиков","упрощение кода в React","упрощение кода в Python","руководство по установке инструментов упрощения кода"],"ar":["كيفية استخدام أدوات تبسيط الكود","ما هي تبسيط الكود","أدوات تبسيط الكود للمانحين","تبسيط الكود في React","تبسيط الكود في Python","دليل تثبيت أدوات تبسيط الكود"]}},"owner":"sammcj","repo":"agentic-coding","repoPath":"sammcj/agentic-coding","stars":0,"forks":0,"updatedAt":"2026-03-04T13:07:01.675Z","topics":[],"category":"community","skillMd":{"name":"code-simplification","description":"Use this skill when you need to review and refactor code to make it simpler, more maintainable, and easier to understand. Helps with identifying overly complex solutions, unnecessary abstractions.","bodyPreview":"The information outlined here aims to help you become an expert system architect and developer with an unwavering commitment to code simplicity.\n\nWhen focusing on code simplification it is your mission to identify and eliminate unnecessary complexity wherever it exists, transforming convoluted solutions into elegant, maintainable code.\n\nYour core principles:\n- **Simplicity First**: Every line of code should have a clear purpose. If it doesn''t contribute directly to solving the problem, it should","body":"The information outlined here aims to help you become an expert system architect and developer with an unwavering commitment to code simplicity.\n\nWhen focusing on code simplification it is your mission to identify and eliminate unnecessary complexity wherever it exists, transforming convoluted solutions into elegant, maintainable code.\n\nYour core principles:\n- **Simplicity First**: Every line of code should have a clear purpose. If it doesn''t contribute directly to solving the problem, it shouldn''t exist.\n- **Readability Over Cleverness**: Code is read far more often than it''s written. Optimise for human understanding, not for showing off technical prowess.\n- **Minimal Abstractions**: Only introduce abstractions when they genuinely reduce complexity. Premature abstraction is a form of complexity.\n- **Clear Intent**: Code should express what it does, not how it does it. The ''why'' should be obvious from reading the code.\n\nWhen reviewing code, you will:\n\n1. **Identify Complexity Hotspots**:\n   - Deeply nested conditionals or loops\n   - Functions doing too many things\n   - Unnecessary design patterns or abstractions\n   - Overly generic solutions for specific problems\n   - Complex boolean logic that could be simplified\n   - Redundant code or repeated patterns\n\n2. **Propose Simplifications**:\n   - Break down complex functions into smaller, focused ones\n   - Replace nested conditionals with early returns or guard clauses\n   - Eliminate intermediate variables that don''t add clarity\n   - Simplify data structures when possible\n   - Remove unused parameters, methods, or classes\n   - Convert complex boolean expressions to well-named functions\n\n3. **Maintain Functionality**:\n   - Ensure all simplifications preserve the original behaviour\n   - Consider edge cases and error handling\n   - Maintain or improve performance characteristics\n   - Keep necessary complexity that serves a real purpose\n\n4. **Provide Clear Refactoring Steps**:\n   - Explain why each change improves simplicity\n   - Show before/after comparisons\n   - Prioritise changes by impact\n   - Suggest incremental refactoring when dealing with large changes\n\n5. **Consider Context**:\n   - Respect project-specific patterns from CLAUDE.md files\n   - Align with established coding standards\n   - Consider the skill level of the team maintaining the code\n   - Balance simplicity with other requirements like performance or security\n\n6. **Consider requirements**:\n   - Don''t remove essential requirements for the proposed or implemented solution.\n   - Ensure that no functionality is lost. If you want to remove functionality, ask for feedback whether that is required.\n\nYour communication style:\n- Be direct and specific about complexity issues\n- Provide concrete examples of simplified code\n- Explain the benefits of each simplification\n- Acknowledge when complexity is necessary and justified\n- Focus on actionable improvements, not criticism\n\nRemember: The best code is not the code that does the most, but the code that does exactly what''s needed with the least cognitive overhead. Every simplification you suggest should make the codebase more approachable for the next developer who reads it.\n"},"lastSynced":"2026-03-04T13:23:59.593Z","agentAnalysis":{"suitability":{"en":"Ideal for Code Analysis Agents requiring advanced simplification capabilities to optimize maintainable code.","zh":"适合需要高级简化功能以优化可维护代码的代码分析代理。","ja":"コード分析エージェントが高度な簡素化機能を必要とする場合に最適です。","ko":"고급 단순화 기능을 사용하여 유지 보수 가능한 코드를 최적화하는 코드 분석 에이전트에 적합합니다.","es":"Ideal para Agentes de Análisis de Código que requieren capacidades de simplificación avanzadas para optimizar el código mantenido.","fr":"Idéal pour les Agents d''Analyse de Code nécessitant des capacités de simplification avancées pour optimiser le code maintenable.","de":"Ideal für Code-Analyse-Agents, die erweiterte Vereinfachungsfähigkeiten benötigen, um wartbares Code zu optimieren.","pt":"Ideal para Agentes de Análise de Código que exigem capacidades de simplificação avançadas para otimizar código mantenedor.","ru":"Идеально подходит для агентов анализа кода, требующих передовых возможностей упрощения для оптимизации поддерживаемого кода.","ar":"مثالي لعميل تحليل الكود الذي يتطلب قابليات تبسيط متقدمة لتحسين كود قابل للصيانة."},"recommendation":{"en":"Empowers agents to eliminate unnecessary complexity using Agentic Coding Rules and Templates, transforming convoluted solutions into elegant code with a clear purpose, adhering to the Simplicity First principle.","zh":"赋予代理使用Agentic Coding Rules和模板消除不必要的复杂性，将复杂的解决方案转化为优雅的代码，具有明确的目的，遵循简洁性第一原则。","ja":"Agentic Coding Rulesおよびテンプレートを使用して不要な複雑さを排除し、複雑なソリューションを明確な目的を持ったエレガントなコードに変換することでエージェントをEmpowerし、シンプリシティファーストの原則に従う。","ko":"에이전트에게 불필요한 복잡성을 제거하여 복잡한 솔루션을 명확한 목적을 가진 우아한 코드로 변환할 수 있도록 Agentic Coding Rules 및 템플릿을 사용하여Empower 하여, 단순성 우선 원칙을 준수합니다.","es":"Habilita a los agentes a eliminar la complejidad innecesaria utilizando Reglas y Plantillas de Codificación Agente, transformando soluciones enrevesadas en código elegante con un propósito claro, ajustándose al principio de Simplicidad Primero.","fr":"Permet aux agents d''éliminer la complexité inutile en utilisant les Règles et Modèles de Codage Agentic, transformant des solutions compliquées en code élégant avec un but clair, en adhérant au principe de Simplicité Première.","de":"Ermöglicht es Agents, unnötige Komplexität mit Hilfe von Agentic Coding-Regeln und -Vorlagen zu eliminieren, verwirrende Lösungen in elegantes Code mit einem klaren Zweck umzuwandeln und sich an das Prinzip Einfachheit zuerst zu halten.","pt":"Habilita agentes a eliminar complexidade desnecessária usando Regras e Modelos de Codificação Agêntica, transformando soluções complicadas em código elegante com um propósito claro, aderindo ao princípio da Simplicidade Primeiro.","ru":"Наделяет агентов возможностью устранять ненужную сложность с помощью агентских правил и шаблонов кодирования, превращая запутанные решения в элегантный код с четкой целью, придерживаясь принципа \"Простота прежде всего\".","ar":"تمكن العميل من القضاء على التعقيد غير الضروري باستخدام قواعدและการ تعليمات الترميز الوكيل، ومحولة حلول معقدة إلى كود أنيق مع غرض واضح، والامتثال لمبدأ البساطة أولاً."},"useCases":{"en":["Simplifying legacy codebases","Refactoring complex algorithms for readability","Eliminating redundant code segments"],"zh":["简化遗留代码库","重构复杂算法以提高可读性","消除冗余代码段"],"ja":["レガシーコードベースの簡素化","複雑なアルゴリズムのリファクタリングによる可読性の向上","冗長なコードセグメントの排除"],"ko":["레거시 코드베이스 단순화","복잡한 알고리즘을 가독성 있게 리팩토링","중복 코드 세그먼트 제거"],"es":["Simplificación de bases de código heredadas","Reestructuración de algoritmos complejos para mejorar la legibilidad","Eliminación de segmentos de código redundantes"],"fr":["Simplification de bases de code héritées","Réorganisation d''algorithmes complexes pour améliorer la lisibilité","Élimination de segments de code redondants"],"de":["Vereinfachung von Legacy-Codebasen","Umstrukturierung komplexer Algorithmen zur Verbesserung der Lesbarkeit","Eliminierung redundanter Code-Segmente"],"pt":["Simplificando bases de código legadas","Reestruturando algoritmos complexos para legibilidade","Eliminando segmentos de código redundantes"],"ru":["Упрощение устаревших баз кода","Переструктуризация сложных алгоритмов для читаемости","Устранение избыточных сегментов кода"],"ar":["تبسيط قواعد بيانات تراثية","إعادة هيكلة خوارزميات معقدة للقراءة","إزالة مقاطع كود زائدة"]},"limitations":{"en":["Requires comprehensive code review","May not be suitable for highly optimized, performance-critical code"],"zh":["需要全面代码审查","可能不适合高度优化的性能关键代码"],"ja":["包括的なコードレビューが必要","高性能な最適化コードには適さない可能性がある"],"ko":["포괄적인 코드 검토가 필요","높은 성능 최적화 코드에는 적합하지 않을 수 있음"],"es":["Requiere una revisión exhaustiva del código","Puede que no sea adecuado para código altamente optimizado y crítico en cuanto a rendimiento"],"fr":["Nécessite une revue exhaustive du code","Peut ne pas être adapté pour le code hautement optimisé et critique en termes de performances"],"de":["Erfordert eine umfassende Code-Überprüfung","Kann für hoch optimierten, leistungs-kritischen Code nicht geeignet sein"],"pt":["Exige uma revisão abrangente do código","Pode não ser adequado para código altamente otimizado e crítico em termos de desempenho"],"ru":["Требует всестороннего обзора кода","Может быть не подходит для высоко оптимизированного и критического для производительности кода"],"ar":["يتطلب مراجعة شاملة للكود","قد لا يكون مناسبًا للكود المت оптимز و الحرج للأداء"]},"version":3},"contentHash":"e7ea6566174e298206fe51ccd8cd3e113aa1c133730c2ff5d2bb139039eb3b0e","qualityScore":18}');
