INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('Birdiz/Birdiz/plan-confirm-workflow', 'plan-confirm-workflow', 'Birdiz', 'Birdiz', 'community', 'plan-confirm-workflow Birdiz Birdiz community plan-confirm-workflow配置文件用于优化GitHub开发工作流程，包括配置和设置 plan-confirm-workflow設定は、GitHub開発ワークフローを最適化するための設定ファイルです plan-confirm-workflow 구성 파일은 GitHub 개발 워크플로우를 최적화하는 데 사용됩니다 El flujo de trabajo de planificación y confirmación permite la configuración de archivos para tu perfil de GitHub Le flux de travail de planification et de confirmation permet la configuration de fichiers pour votre profil GitHub Der Planungs- und Bestätigungs-Workflow ermöglicht die Konfiguration von Dateien für Ihr GitHub-Profil A habilidade de planejamento de fluxo de trabalho de agentes de IA permite configurar arquivos para seu perfil GitHub de forma eficiente. Навык планирования потока работы ИИ Агентов позволяет настроить файлы для своего профиля GitHub эффективно. تمكنك مهارة تخطيط تدفق العمل لأدوات الذكاء الاصطناعي من設定 الملفات لملفك الشخصي على GitHub بشكل فعال. Config files for my GitHub profile. AI智能代理工具 plan-confirm-workflow GitHub开发工作流程 配置文件 开发效率 开发工具 如何使用plan-confirm-workflow plan-confirm-workflow安装 plan-confirm-workflow设置指南 Config files for my GitHub profile.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('MykolaPinchuk/TML-bench/checkpoint', 'community', 'MykolaPinchuk', 'TML-bench', 'MykolaPinchuk/TML-bench', 'checkpoint', 0, 0, 18, '2026-03-04T13:07:01.749Z', '2026-03-04T14:10:57.050Z', '813bb91b0e653ffeb8197ccf8cb9dc015b7b8534a90428b874ca87862024dab5', '{"id":"MykolaPinchuk/TML-bench/checkpoint","name":"checkpoint","description":{"zh":"Checkpoint是一个标准化的表格机器学习基准，帮助开发者评估和优化模型性能。","ja":"CheckpointはタブラーMLベンチマークの標準化されたフレームワークで、開発者がモデルパフォーマンスを評価、最適化するのに役立ちます。","ko":"Checkpoint는 표 형식 머신러닝 벤치마크를 표준화한 프레임워크로 개발자가 모델 성능을 평가하고 최적화하는 데 도움이 됩니다.","es":"Checkpoint es una herramienta de benchmark para ML que permite comparar el rendimiento de diferentes modelos. Está diseñada para ser fácil de usar y personalizar","fr":"Checkpoint est un outil de benchmark pour le ML qui permet de comparer les performances de différents modèles. Il est conçu pour être facile à utiliser et personnalisable","de":"Checkpoint ist ein Benchmark-Tool für ML, mit dem Sie die Leistung verschiedener Modelle vergleichen können. Es ist benutzerfreundlich und anpassbar","pt":"O Checkpoint é uma ferramenta de benchmark de ML em tabela que ajuda a melhorar a eficiência dos projetos de aprendizado de máquina","ru":"Checkpoint - это инструмент для табличной оценки ML, который помогает повысить эффективность проектов машинного обучения","ar":"نقطة التفتيش هي أداة لتحليلات المقارنة لMLE في الجداول تساعد على تحسين كفاءة مشاريع التعلم الآلي","en":"Tabular ML benchmark"},"seo":{"title":{"zh":"AIエージェント：Checkpoint 标准化的表格机器学习基准","ja":"AIエージェント：Checkpoint タブラーMLベンチマーク","ko":"AI 에이전트: Checkpoint 표준화된 표 형식 머신러닝 벤치마크","es":"Herramientas de AI: Checkpoint para benchmark de ML","fr":"Outils d''IA: Checkpoint pour benchmark ML","de":"KI-Tools: Checkpoint für ML-Benchmark","pt":"Ferramentas de IA: Checkpoint para Benchmark de ML","ru":"ИИ Агенты: Checkpoint для табличной оценки ML","ar":"أدوات الذكاء الاصطناعي: نقطة تفتيش للتحليلات المقارنة لMLE","en":"checkpoint"},"description":{"zh":"Checkpoint是一个标准化的表格机器学习基准，帮助开发者评估和优化模型性能。","ja":"CheckpointはタブラーMLベンチマークの標準化されたフレームワークで、開発者がモデルパフォーマンスを評価、最適化するのに役立ちます。","ko":"Checkpoint는 표 형식 머신러닝 벤치마크를 표준화한 프레임워크로 개발자가 모델 성능을 평가하고 최적화하는 데 도움이 됩니다.","es":"Checkpoint es una herramienta de benchmark para ML que permite comparar el rendimiento de diferentes modelos. Está diseñada para ser fácil de usar y personal...","fr":"Checkpoint est un outil de benchmark pour le ML qui permet de comparer les performances de différents modèles. Il est conçu pour être facile à utiliser et pe...","de":"Checkpoint ist ein Benchmark-Tool für ML, mit dem Sie die Leistung verschiedener Modelle vergleichen können. Es ist benutzerfreundlich und anpassbar","pt":"O Checkpoint é uma ferramenta de benchmark de ML em tabela que ajuda a melhorar a eficiência dos projetos de aprendizado de máquina","ru":"Checkpoint - это инструмент для табличной оценки ML, который помогает повысить эффективность проектов машинного обучения","ar":"نقطة التفتيش هي أداة لتحليلات المقارنة لMLE في الجداول تساعد على تحسين كفاءة مشاريع التعلم الآلي","en":"Tabular ML benchmark"},"definition":{"en":"Tabular ML benchmark"},"features":{"zh":["标准化的表格机器学习基准","评估和优化模型性能","提升开发效率","优化性能","支持多种机器学习框架"],"ja":["タブラーMLベンチマークの標準化されたフレームワーク","モデルパフォーマンスの評価、最適化","開発効率の向上","パフォーマンスの最適化","多種の機械学習フレームワークをサポート"],"ko":["표 형식 머신러닝 벤치마크를 표준화한 프레임워크","모델 성능 평가 및 최적화","개발 효율성 향상","성능 최적화","다양한 머신러닝 프레임워크 지원"],"es":["Benchmark de ML para comparar el rendimiento de diferentes modelos","Diseño personalizable para adaptarse a las necesidades del desarrollador","Integración con frameworks de ML populares como TensorFlow y PyTorch","Análisis detallado de los resultados para identificar áreas de mejora","Soporte para múltiples plataformas y entornos de ejecución"],"fr":["Benchmark ML pour comparer les performances de différents modèles","Conception personnalisable pour s''adapter aux besoins du développeur","Intégration avec des frameworks ML populaires tels que TensorFlow et PyTorch","Analyse détaillée des résultats pour identifier les domaines d''amélioration","Prise en charge de plusieurs plateformes et environnements d''exécution"],"de":["ML-Benchmark für den Vergleich der Leistung verschiedener Modelle","Anpassbares Design, um sich an die Bedürfnisse des Entwicklers anzupassen","Integration mit beliebten ML-Frameworks wie TensorFlow und PyTorch","Detaillierte Analyse der Ergebnisse, um Bereiche für Verbesserungen zu identifizieren","Unterstützung für mehrere Plattformen und Ausführungsumgebungen"],"pt":["Benchmark de ML em tabela","Análise de desempenho de modelos de ML","Otimização de projetos de aprendizado de máquina","Integração com ferramentas de desenvolvimento de ML","Relatórios detalhados de desempenho"],"ru":["Табличная оценка ML","Анализ производительности моделей ML","Оптимизация проектов машинного обучения","Интеграция с инструментами разработки ML","Детальные отчеты о производительности"],"ar":["تحليلات المقارنة لMLE في الجداول","تحليل أداء نماذج التعلم الآلي","تحسين مشاريع التعلم الآلي","التكامل مع أدوات تطوير التعلم الآلي","تقارير مفصلة عن الأداء"]},"keywords":{"zh":["如何使用Checkpoint","什么是Checkpoint","Checkpoint替代方案","Checkpoint vs 其他机器学习框架","Checkpoint安装","Checkpoint设置指南","机器学习基准","表格机器学习"],"ja":["Checkpointの使い方","Checkpointとは","Checkpointの代替","Checkpoint vs 他の機械学習フレームワーク","Checkpointのインストール","Checkpointの設定ガイド","機械学習ベンチマーク","タブラー機械学習"],"ko":["Checkpoint 사용법","Checkpoint란","Checkpoint 대체","Checkpoint vs 다른 머신러닝 프레임워크","Checkpoint 설치","Checkpoint 설정 가이드","머신러닝 벤치마크","표 형식 머신러닝"],"es":["herramientas de AI","benchmark de ML","mejorar el rendimiento de los modelos","alternativas a Checkpoint","instalación de Checkpoint","guía de configuración de Checkpoint","uso de Checkpoint con TensorFlow","uso de Checkpoint con PyTorch"],"fr":["outils d''IA","benchmark ML","améliorer les performances des modèles","alternatives à Checkpoint","installation de Checkpoint","guide de configuration de Checkpoint","utilisation de Checkpoint avec TensorFlow","utilisation de Checkpoint avec PyTorch"],"de":["KI-Tools","ML-Benchmark","Leistung der Modelle verbessern","Alternativen zu Checkpoint","Installation von Checkpoint","Konfigurationsanleitung für Checkpoint","Verwendung von Checkpoint mit TensorFlow","Verwendung von Checkpoint mit PyTorch"],"pt":["como usar checkpoint","o que é checkpoint","ferramentas de ia","benchmark de ml","otimização de projetos de ml","alternativas ao checkpoint","checkpoint vs outras ferramentas","instalação do checkpoint","guia de configuração do checkpoint"],"ru":["как использовать checkpoint","что такое checkpoint","инструменты ии","табличная оценка ml","оптимизация проектов ml","альтернативы checkpoint","checkpoint vs другие инструменты","установка checkpoint","руководство по настройке checkpoint"],"ar":["كيفية استخدام نقطة التفتيش","ما هي نقطة التفتيش","أدوات الذكاء الاصطناعي","تحليلات المقارنة لMLE","تحسين مشاريع التعلم الآلي","بدي勒 لنقطة التفتيش","نقطة التفتيش مقابل أدوات أخرى","تثبيت نقطة التفتيش","دليل إعداد نقطة التفتيش"]}},"owner":"MykolaPinchuk","repo":"TML-bench","repoPath":"MykolaPinchuk/TML-bench","stars":0,"forks":0,"updatedAt":"2026-03-04T13:07:01.749Z","topics":[],"category":"community","skillMd":{"name":"checkpoint","description":"Create a safe checkpoint git commit on the current branch (avoid competition data, runs, artifacts, secrets).","bodyPreview":"When invoked (or when the user says `checkpoint`), do this in order.\n\n## 1) Preflight (must do; show output)\n- `git status`\n- `git diff --stat`\n- Verify `agent_logs/current.md` `id:` is synced to the kickoff `AgentNN` for this chat. If stale, fix `current.md` before commit.\n\n## 2) Sanity guardrails (must do)\n- Never run: `git push`, `git commit --amend`, `git rebase`, `git reset --hard`, `git clean -fdx`, or modify git remotes.\n- Never stage/commit secrets/credentials: `.env*`, `*.pem`, `*.key`,","body":"When invoked (or when the user says `checkpoint`), do this in order.\n\n## 1) Preflight (must do; show output)\n- `git status`\n- `git diff --stat`\n- Verify `agent_logs/current.md` `id:` is synced to the kickoff `AgentNN` for this chat. If stale, fix `current.md` before commit.\n\n## 2) Sanity guardrails (must do)\n- Never run: `git push`, `git commit --amend`, `git rebase`, `git reset --hard`, `git clean -fdx`, or modify git remotes.\n- Never stage/commit secrets/credentials: `.env*`, `*.pem`, `*.key`, `id_rsa*`, `id_ed25519*`, tokens.\n- Never stage/commit competition data or run artifacts:\n  - `competitions/**/{public,private,raw,downloads}/**`\n  - `runs/**`\n  - sqlite/db files\n\n## 3) Stage (default: include safe tracked files)\nStage only source/docs/config files and small markdown:\n- root `*.md`, `*.yml`\n- `docs/**`\n- `local_context_enrichments/**`\n- `.codex/**`\n\nIf anything looks suspicious (bulk files, data-like payloads), stop and report before staging.\n\nBefore committing, show:\n- `git diff --cached --stat`\n\n## 4) Commit (auto message)\n- Create a structured message that includes the agent id:\n  - `agentNN: checkpoint(<area>): <short summary>`\n  - Derive `agentNN` from kickoff-synced `agent_logs/current.md` (field `id:`). If missing/ambiguous, stop and ask the human.\n  - Choose `<area>` from: `workflow`, `docs`, `orchestrator`, `competitions`, `prompts`, `ci`, `misc`.\n- Run `git commit -m \"<message>\"`.\n\n## 5) Postflight (must do; show output)\n- `git status`\n- Report the commit hash.\n"},"lastSynced":"2026-03-04T14:10:57.050Z","agentAnalysis":{"suitability":{"en":"Perfect for Version Control Agents needing automated Git workflow management and verification.","zh":"非常适合需要自动化 Git 工作流管理和验证的版本控制代理。","ja":"バージョン管理エージェントが自動化されたGitワークフローの管理と検証を必要とする場合に最適です。","ko":"자동화된 Git 워크플로 관리 및 검증이 필요한 버전 제어 에이전트에 적합합니다.","es":"Perfecto para Agentes de Control de Versiones que necesitan una gestión y verificación automatizada del flujo de trabajo de Git.","fr":"Parfait pour les Agents de Contrôle de Version nécessitant une gestion et une vérification automatisées du workflow Git.","de":"Perfekt für Version Control Agents, die eine automatisierte Git-Workflow-Verwaltung und -Verifizierung benötigen.","pt":"Perfeito para agentes de Controle de Versão que necessitam de gerenciamento e verificação de fluxo de trabalho Git automatizados.","ru":"Идеально подходит для агентов контроля версий, которым требуется автоматизированное управление и проверка рабочего процесса Git.","ar":"مثالي لعميل التحكم في الإصدار الذي يحتاج إلى إدارة وتحقق تلقائي لتدفق العمل Git."},"recommendation":{"en":"Empowers agents to verify repository consistency using `git status` and `git diff --stat`, ensuring data integrity and preventing unintended changes, while safeguarding against operations like `git push`, `git commit --amend`, and `git rebase`.","zh":"赋予代理验证存储库一致性使用 `git status` 和 `git diff --stat`，确保数据完整性并防止意外更改，同时保护免受 `git push`、`git commit --amend` 和 `git rebase` 等操作的影响。","ja":"`git status` と `git diff --stat` を使用してリポジトリの整合性を検証できるようエージェントに権限を与え、データの完全性を確保し、意図しない変更を防止し、`git push`、`git commit --amend`、`git rebase` などの操作から保護します。","ko":"`git status`와 `git diff --stat`를 사용하여 저장소 일관성을 확인할 수 있도록 에이전트를 활성화하여 데이터 무결성을 보장하고 의도하지 않은 변경을 방지하며 `git push`, `git commit --amend`, `git rebase` 등의 작동으로부터 보호합니다.","es":"Habilita a los agentes a verificar la consistencia del repositorio utilizando `git status` y `git diff --stat`, asegurando la integridad de los datos y evitando cambios no deseados, mientras protege contra operaciones como `git push`, `git commit --amend` y `git rebase`.","fr":"Permet aux agents de vérifier la cohérence du référentiel en utilisant `git status` et `git diff --stat`, assurant l''intégrité des données et empêchant les modifications involontaires, tout en protégeant contre des opérations comme `git push`, `git commit --amend` et `git rebase`.","de":"Ermächtigt die Agenten, die Konsistenz des Repositorys mithilfe von `git status` und `git diff --stat` zu überprüfen, um die Datenintegrität sicherzustellen und ungewollte Änderungen zu verhindern, während sie vor Operationen wie `git push`, `git commit --amend` und `git rebase` schützt.","pt":"Habilita os agentes a verificar a consistência do repositório usando `git status` e `git diff --stat`, garantindo a integridade dos dados e prevenindo alterações não intencionais, enquanto protege contra operações como `git push`, `git commit --amend` e `git rebase`.","ru":"Позволяет агентам проверять последовательность репозитория с помощью `git status` и `git diff --stat`, обеспечивая целостность данных и предотвращая непреднамеренные изменения, а также защищая от операций типа `git push`, `git commit --amend` и `git rebase`.","ar":"تمكّن العميل من التحقق من اتساق المستودع باستخدام `git status` و `git diff --stat` ، مما يضمن سلامة البيانات ومنع التغييرات غير المقصودة ، مع حماية العمليات مثل `git push` و `git commit --amend` و `git rebase`."},"useCases":{"en":["Automating pre-commit checks","Verifying Git repository status","Syncing agent logs with kickoff data"],"zh":["自动化提交前检查","验证 Git 存储库状态","同步代理日志与启动数据"],"ja":["コミット前の自動化チェック","Git リポジトリの状態の検証","エージェントログを起動データと同期"],"ko":["提交 전 자동화 확인","Git 저장소 상태 확인","에이전트 로그를 시작 데이터와 동기화"],"es":["Automatizar verificaciones pre-commit","Verificar el estado del repositorio Git","Sincronizar los registros del agente con los datos de kickoff"],"fr":["Automatiser les vérifications pré-commit","Vérifier l''état du référentiel Git","Synchroniser les journaux de l''agent avec les données de kickoff"],"de":["Automatisierung von Pre-Commit-Prüfungen","Überprüfung des Git-Repository-Status","Synchronisierung der Agenten-Protokolle mit den Kickoff-Daten"],"pt":["Automatizar verificações pré-commit","Verificar status do repositório Git","Sincronizar logs de agente com dados de inicialização"],"ru":["Автоматизировать проверки перед фиксацией","Проверять состояние репозитория Git","Синхронизировать журналы агента с начальными данными"],"ar":["توفير التأكيدات التلقائية قبل الالتزام","التحقق من حالة مستودع Git","تمكين سجلات العميل مع بيانات التشغيل"]},"limitations":{"en":["Requires Git installation","Must have write access to `agent_logs/current.md`","Never modifies git remotes or stages secrets/credentials like `.env*`, `*.pem`, `*.key`"],"zh":["需要 Git 安装","必须对 `agent_logs/current.md` 有写入访问权限","永远不会修改 Git 远程仓库或秘钥/凭据，如 `.env*`、`*.pem`、`*.key`"],"ja":["Git のインストールが必要","`agent_logs/current.md` に書き込みアクセス権が必要","Git リモートリポジトリや秘密鍵/資格情報 (`.env*`、`*.pem`、`*.key` など) を変更することはありません"],"ko":["Git 설치가 필요함","`agent_logs/current.md`에 쓰기 액세스 권한이 필요함","Git 원격 저장소 또는 비밀 키/자격 증명(`.env*`, `*.pem`, `*.key` 등)을 수정하지 않음"],"es":["Requiere instalación de Git","Debe tener acceso de escritura a `agent_logs/current.md`","Nunca modifica git remotos ni etapas secretos/credenciales como `.env*`, `*.pem`, `*.key`"],"fr":["Nécessite l''installation de Git","Doit avoir un accès en écriture à `agent_logs/current.md`","Ne modifie jamais les référentiels Git distants ni les étapes de secrets/credentials comme `.env*`, `*.pem`, `*.key`"],"de":["Benötigt Git-Installation","Muss Schreibzugriff auf `agent_logs/current.md` haben","Ändert niemals Git-Fernrepositorys oder Stufen von Geheimnissen/Zugangsdaten wie `.env*`, `*.pem`, `*.key`"],"pt":["Requer instalação do Git","Deve ter acesso de gravação para `agent_logs/current.md`","Nunca modifica remotos Git ou etapas segredos/credenciais como `.env*`, `*.pem`, `*.key`"],"ru":["Требует установки Git","Должен иметь доступ на запись к `agent_logs/current.md`","Никогда не изменяет удаленные репозитории Git или этапы секретов/управления доступом, такие как `.env*`, `*.pem`, `*.key`"],"ar":["يتطلب تثبيت Git","يجب أن يكون لديه quyền الوصول إلى `agent_logs/current.md`","أبدا لا يغير مستودعات Git البعيدة أو مراحل الأسرار / بيانات الاعتماد مثل `.env*` ، `*.pem` ، `*.key`"]},"version":3},"contentHash":"813bb91b0e653ffeb8197ccf8cb9dc015b7b8534a90428b874ca87862024dab5","qualityScore":18}');
