INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('cyzus/suzent/notebook-skill', 'notebook-skill', 'cyzus', 'suzent', 'community', 'notebook-skill cyzus suzent community SUZENT是一款AI智能代理工具，提供数字合作伙伴解决方案 SUZENTはAIエージェントを活用したデジタルコワーカーです SUZENT는 디지털 협업을 위한 AI 에이전트 도구입니다 SUZENT es una herramienta de inteligencia artificial que actúa como compañero digital soberano, mejorando la productividad y eficiencia SUZENT est un outil d''intelligence artificielle qui agit comme coéquipier numérique souverain, améliorant la productivité et l''efficacité SUZENT ist ein KI-Tool, das als souveräner digitaler Co-Arbeiter agiert, um Produktivität und Effizienz zu steigern SUZENT é uma plataforma de IA que atua como um co-trabalhador digital, oferecendo ferramentas avançadas para desenvolvedores SUZENT - это платформа ИИ, которая выступает в качестве цифрового сотрудника, предлагая разработчикам продвинутые инструменты SUZENT هو منصة ذكاء اصطناعي تعمل كمساعد رقمي، وتقدم أدوات متقدمة للمطورين SUZENT: YOUR SOVEREIGN DIGITAL CO-WORKER 如何使用SUZENT SUZENT是什么 SUZENT替代品 SUZENT vs 其他AI工具 SUZENT安装 SUZENT设置指南 AI智能代理工具 数字合作伙伴解决方案 SUZENT: YOUR SOVEREIGN DIGITAL CO-WORKER');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('TheCactusBlue/nixfiles/review', 'community', 'TheCactusBlue', 'nixfiles', 'TheCactusBlue/nixfiles', 'review', 0, 0, 18, '2026-03-04T13:07:01.770Z', '2026-03-04T14:20:20.976Z', '5ee3527acd926248a6cdc74446a2e6e0d65885f7d385034c4f9dbd0505fdbabf', '{"id":"TheCactusBlue/nixfiles/review","name":"review","description":{"zh":"AI智能代理可以帮助您快速设置NixOS，提高开发效率","ja":"AIエージェントは、NixOSの設定を迅速に行い、開発効率を向上させることができます","ko":"AI 에이전트는 NixOS 설정을 빠르게 구현하여 개발 효율을 높일 수 있습니다","es":"Configuración de NixOS para desarrolladores con herramientas de IA","fr":"Installation de NixOS pour les développeurs avec des outils d''IA","de":"NixOS-Einrichtung für Entwickler mit KI-Tools","pt":"O NixOS é um sistema operacional de código aberto que pode ser configurado com ferramentas de IA para melhorar a produtividade do desenvolvedor.","ru":"NixOS - это открытая операционная система, которую можно настроить с помощью ИИ Агентов для улучшения производительности разработчика.","ar":"NixOS هو نظام تشغيل مفتوح المصدر يمكن تعيينه مع أدوات الذكاء الاصطناعي لتحسين إنتاجية المطور.","en":"NixOS setup"},"seo":{"title":{"zh":"AI智能代理NixOS设置指南","ja":"AIエージェントのNixOS設定","ko":"AI 에이전트 NixOS 설정 가이드","es":"Herramientas de IA: Configuración de NixOS","fr":"Outils d''IA: Installation de NixOS","de":"KI-Tools: NixOS Einrichtung","pt":"Ferramentas de IA: Configuração do NixOS","ru":"ИИ Агенты: Настройка NixOS","ar":"أدوات الذكاء الاصطناعي: إعداد NixOS","en":"review"},"description":{"zh":"AI智能代理可以帮助您快速设置NixOS，提高开发效率","ja":"AIエージェントは、NixOSの設定を迅速に行い、開発効率を向上させることができます","ko":"AI 에이전트는 NixOS 설정을 빠르게 구현하여 개발 효율을 높일 수 있습니다","es":"Configuración de NixOS para desarrolladores con herramientas de IA","fr":"Installation de NixOS pour les développeurs avec des outils d''IA","de":"NixOS-Einrichtung für Entwickler mit KI-Tools","pt":"O NixOS é um sistema operacional de código aberto que pode ser configurado com ferramentas de IA para melhorar a produtividade do desenvolvedor.","ru":"NixOS - это открытая операционная система, которую можно настроить с помощью ИИ Агентов для улучшения производительности разработчика.","ar":"NixOS هو نظام تشغيل مفتوح المصدر يمكن تعيينه مع أدوات الذكاء الاصطناعي لتحسين إنتاجية المطور.","en":"NixOS setup"},"definition":{"en":"NixOS setup"},"features":{"zh":["自动化NixOS设置","提高开发效率","支持多种开发环境","易于使用的CLI界面","高级设置选项"],"ja":["NixOSの自動設定","開発効率の向上","複数の開発環境をサポート","使いやすいCLIインターフェース","高度な設定オプション"],"ko":["NixOS 자동 설정","개발 효율성 향상","다중 개발 환경 지원","사용자 친화적 CLI 인터페이스","고급 설정 옵션"],"es":["Configuración de NixOS con herramientas de IA","Mejora de la productividad con herramientas de automatización","Integración con otros herramientas de desarrollo","Soporte para múltiples lenguajes de programación","Seguridad y estabilidad del sistema"],"fr":["Installation de NixOS avec des outils d''IA","Amélioration de la productivité avec des outils d''automatisation","Intégration avec d''autres outils de développement","Support pour plusieurs langages de programmation","Sécurité et stabilité du système"],"de":["NixOS-Einrichtung mit KI-Tools","Produktivitätssteigerung mit Automatisierungstools","Integration mit anderen Entwicklungstools","Unterstützung für mehrere Programmiersprachen","Sicherheit und Stabilität des Systems"],"pt":["Configuração avançada do NixOS","Integração com ferramentas de IA","Otimização do workflow de desenvolvimento","Suporte a múltiplos ambientes de desenvolvimento","Gerenciamento de dependências avançado"],"ru":["Расширенная настройка NixOS","Интеграция с ИИ Агентами","Оптимизация рабочего процесса разработки","Поддержка нескольких сред разработки","Продвинутый менеджмент зависимостей"],"ar":["إعداد متقدم لـ NixOS","التكامل مع أدوات الذكاء الاصطناعي","تحسين تدفق عمل التطوير","دعم بيئات متعددة للتطوير","إدارة متقدمة للتفاعلات"]},"keywords":{"zh":["AI智能代理","NixOS设置","开发效率","自动化设置","CLI工具","NixOS设置指南","AI工具","开发环境"],"ja":["AIエージェント","NixOS設定","開発効率","自動設定","CLIツール","NixOS設定ガイド","AIツール","開発環境"],"ko":["AI 에이전트","NixOS 설정","개발 효율성","자동 설정","CLI 도구","NixOS 설정 가이드","AI 도구","개발 환경"],"es":["herramientas de ia para desarrolladores","configuración de nixos","nixos vs ubuntu","guias de instalación de nixos","mejora de la productividad con herramientas de ia","desarrollo de software con nixos"],"fr":["outils d''ia pour développeurs","installation de nixos","nixos vs ubuntu","guides d''installation de nixos","amélioration de la productivité avec des outils d''ia","développement de logiciels avec nixos"],"de":["ki-tools für entwickler","nixos einrichtung","nixos vs ubuntu","anleitungen zur installation von nixos","produktivitätssteigerung mit ki-tools","software-entwicklung mit nixos"],"pt":["como configurar NixOS","ferramentas de IA para desenvolvedores","NixOS vs outros sistemas operacionais","guia de instalação do NixOS","otimização do workflow de desenvolvimento","desenvolvimento de software com NixOS"],"ru":["настройка NixOS","ИИ Агенты для разработчиков","NixOS против других операционных систем","руководство по установке NixOS","оптимизация рабочего процесса разработки","разработка программного обеспечения с NixOS"],"ar":["كيفية إعداد NixOS","أدوات الذكاء الاصطناعي للمطورين","NixOS مقابل أنظمة تشغيل أخرى","دليل تثبيت NixOS","تحسين تدفق عمل التطوير","تطوير البرمجيات مع NixOS"]}},"owner":"TheCactusBlue","repo":"nixfiles","repoPath":"TheCactusBlue/nixfiles","stars":0,"forks":0,"updatedAt":"2026-03-04T13:07:01.770Z","topics":[],"category":"community","skillMd":{"name":"review","description":"Pre-commit self-review. Use this to catch bugs, security issues, debug artifacts, and style problems in your changes before committing.","bodyPreview":"# Pre-Commit Self-Review\n\n## Overview\n\nReview the current changeset for issues before committing. Analyzes the diff for bugs, security problems, leftover debug code, and style inconsistencies. Presents findings for the user to decide on — does not auto-fix.\n\n## The Process\n\n**Gather the changeset:**\n\n- Run `git diff --staged` to get staged changes\n- If nothing is staged, fall back to `git diff` for unstaged changes\n- If both are empty, inform the user there''s nothing to review\n\n**Check project c","body":"# Pre-Commit Self-Review\n\n## Overview\n\nReview the current changeset for issues before committing. Analyzes the diff for bugs, security problems, leftover debug code, and style inconsistencies. Presents findings for the user to decide on — does not auto-fix.\n\n## The Process\n\n**Gather the changeset:**\n\n- Run `git diff --staged` to get staged changes\n- If nothing is staged, fall back to `git diff` for unstaged changes\n- If both are empty, inform the user there''s nothing to review\n\n**Check project conventions:**\n\n- If `CLAUDE.md` exists at the project root, read it for project-specific rules\n- Note any conventions around naming, error handling, imports, or formatting\n- Use these as additional review criteria alongside the defaults\n\n**Analyze changes for issues:**\n\n- **Bugs and logic errors** - Off-by-one, null/undefined access, wrong comparisons, missing edge cases, race conditions\n- **Leftover debug code** - `console.log`, `debugger`, `print()` statements, `TODO`/`FIXME`/`HACK` comments added in this diff\n- **Security issues** - Hardcoded secrets, SQL injection, XSS, unsanitized input, overly permissive permissions\n- **Missing error handling** - Unhandled promise rejections, unchecked return values, bare `except`/`catch` blocks\n- **Style inconsistencies** - Naming convention mismatches, inconsistent patterns compared to surrounding code\n\n**Present findings:**\n\n- Group issues by severity:\n  - **Blocking** - Bugs, security issues, or errors that must be fixed before committing\n  - **Warning** - Likely problems worth addressing but not strictly required\n  - **Nitpick** - Style or preference issues, take-or-leave\n- For blocking issues, suggest a specific fix with code\n- For warnings and nitpicks, describe the issue and location\n- If the changeset is clean, confirm with a brief summary of what was reviewed\n\n## Key Principles\n\n- **Diff-focused** - Only review what changed, not the entire file\n- **Advisory, not automatic** - Present findings for the user to act on\n- **Convention-aware** - Respect project-specific rules from `CLAUDE.md`\n- **Severity-driven** - Clearly separate must-fix from nice-to-have\n- **Concise** - Don''t repeat the code back; reference file and line, describe the issue, suggest the fix\n"},"lastSynced":"2026-03-04T14:20:20.976Z","agentAnalysis":{"suitability":{"en":"Perfect for Code Review Agents needing comprehensive content analysis and diff inspection capabilities.","zh":"适合需要全面内容分析和差异检查功能的代码审查代理。","ja":"コードレビューエージェントが包括的なコンテンツ分析と差分検査機能を必要とする場合に最適です。","ko":"포괄적인 내용 분석 및 차이점 검사 기능이 필요한 코드 검토 에이전트에 적합합니다.","es":"Perfecto para Agentes de Revisión de Código que necesitan un análisis de contenido integral y capacidades de inspección de diferencias.","fr":"Parfait pour les Agents de Revue de Code nécessitant une analyse de contenu globale et des capacités d''inspection de différences.","de":"Perfekt für Code-Review-Agents, die eine umfassende Inhaltsanalyse und Differenzinspektion benötigen.","pt":"Perfeito para Agentes de Revisão de Código que precisam de análise de conteúdo abrangente e capacidades de inspeção de diferenças.","ru":"Идеально подходит для агентов код-ревью, которым необходима всесторонняя анализ содержания и возможности инспекции различий.","ar":"مثالي للوكلاء المراجعة الكود الذين يحتاجون إلى تحليل محتوى شامل وقدرات فحص الفرق."},"recommendation":{"en":"Empowers agents to inspect Git changesets for bugs, security problems, and style inconsistencies using `git diff` and staged changes analysis, presenting findings for user decision-making without auto-fixing.","zh":"赋予代理检查Git更改集以发现bug、安全问题和风格不一致性，使用`git diff`和暂存更改分析，并为用户决策提供建议而不自动修复。","ja":"`git diff`とステージされた変更の分析を使用して、エージェントがGitの変更セットをバグ、セキュリティの問題、スタイルの不一致性を検査し、自動修復せずにユーザーの意思決定のためにその結果を提示することを可能にします。","ko":"`git diff` 및 스테이징된 변경 사항 분석을 사용하여 에이전트가 Git 변경 사항을 버그, 보안 문제 및 스타일 불일치를 검사하고 자동으로 수정하지 않고 사용자의 의사 결정에 대한 결과를 제시할 수 있도록 합니다.","es":"Habilita a los agentes a inspeccionar conjuntos de cambios de Git para errores, problemas de seguridad y inconsistencias de estilo utilizando `git diff` y análisis de cambios en espera, presentando los resultados para la toma de decisiones del usuario sin corregir automáticamente.","fr":"Permet aux agents d''inspecter les jeux de modifications Git pour les bogues, les problèmes de sécurité et les incohérences de style en utilisant `git diff` et l''analyse des modifications en attente, présentant les résultats pour la prise de décision de l''utilisateur sans correction automatique.","de":"Ermächtigt Agenten, Git-Änderungssätze auf Fehler, Sicherheitsprobleme und Stilinkonsistenzen mit `git diff` und Analyse von gestellten Änderungen zu überprüfen, und präsentiert die Ergebnisse zur Entscheidungsfindung des Benutzers ohne automatische Korrektur.","pt":"Habilita os agentes a inspecionar conjuntos de alterações do Git para bugs, problemas de segurança e inconsistências de estilo usando `git diff` e análise de alterações em estágio, apresentando os resultados para tomada de decisão do usuário sem auto-correção.","ru":"Наделяет агентов возможностью инспектировать наборы изменений Git для ошибок, проблем безопасности и несоответствий стиля с помощью `git diff` и анализа изменений на стадии, представляя результаты для принятия решений пользователем без автоматического исправления.","ar":"يتمكن الوكلاء من فحص مجموعات التغييرات في Git للعثور على الأخطاء وأخطاء الأمان وعدم انتظام الأساليب باستخدام `git diff` وتحليل التغييرات في مرحلة معينة، وتقديم النتائج لاتخاذ قرارات المستخدم دون إصلاح تلقائي."},"useCases":{"en":["Inspecting staged changes for security vulnerabilities","Analyzing unstaged changes for debugging purposes","Reviewing commit history for style inconsistencies"],"zh":["检查暂存的更改以发现安全漏洞","分析未暂存的更改以进行调试","查看提交历史记录以发现风格不一致性"],"ja":["セキュリティ脆弱性を検出するためにステージされた変更を検査する","デバッグのためにステージされていない変更を分析する","スタイルの不一致性を検出するためにコミット履歴を確認する"],"ko":["보안 취약점을 발견하기 위해 스테이징된 변경 사항을 검사하는 것","디버깅을 위해 스테이징되지 않은 변경 사항을 분석하는 것","스타일 불일치를 발견하기 위해 커밋 기록을 검토하는 것"],"es":["Inspeccionar cambios en espera para vulnerabilidades de seguridad","Analizar cambios no en espera para fines de depuración","Revisar el historial de confirmación para inconsistencias de estilo"],"fr":["Inspecter les modifications en attente pour les vulnérabilités de sécurité","Analyser les modifications non en attente pour des fins de débogage","Réviser l''historique de validation pour les incohérences de style"],"de":["Überprüfen von gestellten Änderungen auf Sicherheitsverwundbarkeiten","Analysieren von nicht gestellten Änderungen zu Debugging-Zwecken","Überprüfen des Commit-Verlaufs auf Stilinkonsistenzen"],"pt":["Inspecionar alterações em estágio para vulnerabilidades de segurança","Analizar alterações não em estágio para fins de depuração","Revisar histórico de confirmação para inconsistências de estilo"],"ru":["Проверка изменений на стадии на наличие уязвимостей безопасности","Анализ незафиксированных изменений для целей отладки","Просмотр истории фиксации для несоответствий стиля"],"ar":["فحص التغييرات في مرحلة معينة للكشف عن ثغرات أمنية","تحليل التغييرات غير المرفقة لأغراض التصحيح","استعراض سجل الإنشاء للكشف عن عدم انتظام الأساليب"]},"limitations":{"en":["Requires Git installation and configuration","Limited to analyzing text-based changesets","Does not auto-fix identified issues"],"zh":["需要Git安装和配置","仅限分析基于文本的更改集","不自动修复已识别的问题"],"ja":["Gitのインストールと構成が必要","テキストベースの変更セットのみを分析","検出された問題を自動的に修復しない"],"ko":["Git 설치 및 구성이 필요합니다","텍스트 기반의 변경 사항만 분석","검색된 문제를 자동으로 수정하지 않음"],"es":["Requiere instalación y configuración de Git","Limitado al análisis de conjuntos de cambios basados en texto","No corrige automáticamente los problemas identificados"],"fr":["Nécessite l''installation et la configuration de Git","Limité à l''analyse des jeux de modifications basés sur du texte","Ne corrige pas automatiquement les problèmes identifiés"],"de":["Benötigt Git-Installation und -Konfiguration","Begrenzt auf die Analyse von textbasierten Änderungssätzen","Behebt identifizierte Probleme nicht automatisch"],"pt":["Requer instalação e configuração do Git","Limitado à análise de conjuntos de alterações baseados em texto","Não corrige automaticamente problemas identificados"],"ru":["Требует установки и конфигурации Git","Ограничен анализом текстовых наборов изменений","Не исправляет автоматически выявленные проблемы"],"ar":["يتطلب تثبيت وتكوين Git","محدود بتحليل مجموعات التغييرات القائمة على النص","لا يصحح تلقائيًا المشكلات المحددة"]},"version":3},"contentHash":"5ee3527acd926248a6cdc74446a2e6e0d65885f7d385034c4f9dbd0505fdbabf","qualityScore":18}');
