INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('TbK0ng/silver-bullet-kernel/before-backend-dev', 'before-backend-dev', 'TbK0ng', 'silver-bullet-kernel', 'community', 'before-backend-dev TbK0ng silver-bullet-kernel community 基于Trellis的编程前端开发，使用AIエージェント实现高效开发 Trellisベースのプログラミング前バックエンド開発をAIエージェントで実現 트렐리스 기반 프로그래밍 백엔드 개발을 AI 에이전트로 구현 El skill ''before-backend-dev'' te ayuda a crear un plan final de programación basado en trellis antes de iniciar el desarrollo backend Le skill ''before-backend-dev'' vous aide à créer un plan final de programmation basé sur trellis avant de commencer le développement backend Der Skill ''before-backend-dev'' hilft Ihnen, einen finalen Programmierplan basierend auf trellis zu erstellen, bevor Sie mit der Backend-Entwicklung beginnen O before-backend-dev é uma habilidade de IA que ajuda a criar um plano de programação com base em trellis para desenvolvedores ИИ Агент before-backend-dev помогает создать план программирования на базе trellis для разработчиков الوكلاء الذكاء الاصطناعي before-backend-dev يساعد في إنشاء خطة برمجة باستخدام Trellis للمطورين Try to make a final plan on programming base on trellis. AIエージェント 基于Trellis的编程前端开发 高效开发 AIエージェント工具 Trellis开发环境 开发效率提高 如何使用AIエージェント AIエージェント替代品 Try to make a final plan on programming base on trellis.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('joelklabo/markdowntown-cli/markdowntown-cli', 'community', 'joelklabo', 'markdowntown-cli', 'joelklabo/markdowntown-cli', 'markdowntown-cli', 0, 0, 18, '2026-03-04T13:07:01.780Z', '2026-03-04T14:24:07.668Z', 'deb84f9d8c8578935e2d8322ebc62d1b5515e2f3597b19bb8077efd31fda0e4a', '{"id":"joelklabo/markdowntown-cli/markdowntown-cli","name":"markdowntown-cli","description":{"zh":"markdowntown-cli 是一个用于扫描和优化开发工作流的命令行界面工具","ja":"markdowntown-cli は開発ワークフローのスキャンと最適化に使用されるコマンドラインインターフェイスのツールです","ko":"markdowntown-cli는 개발 워크플로우를 스캔하고 최적화하는 명령줄 인터페이스 도구입니다","es":"markdowntown-cli es una herramienta de escaneo de línea de comandos para desarrolladores que necesitan escanear y analizar datos","fr":"markdowntown-cli est un outil de scan en ligne de commande pour les développeurs qui ont besoin d''analyser des données","de":"markdowntown-cli ist ein Kommandozeilen-Scan-Tool für Entwickler, die Daten scannen und analysieren müssen","pt":"O markdowntown-cli é uma ferramenta de linha de comando para scan e análise de código, desenvolvida em Node.js e CLI","ru":"ИИ Агент markdowntown-cli - это инструмент командной строки для сканирования и анализа кода, разработанный на Node.js и CLI","ar":"أداة markdowntown-cli هي أداة سطر أوامر لتحليل و فحص الكود، تم تطويرها باستخدام Node.js و CLI","en":"markdowntown scan CLI"},"seo":{"title":{"zh":"markdowntown-cli AI工具","ja":"markdowntown-cli AIエージェント","ko":"markdowntown-cli AI 에이전트","es":"Herramientas de AI: markdowntown-cli","fr":"Outils d''IA: markdowntown-cli","de":"KI-Tools: markdowntown-cli","pt":"Ferramentas de IA: markdowntown-cli","ru":"ИИ Агенты: markdowntown-cli","ar":"أدوات الذكاء الاصطناعي: markdowntown-cli","en":"markdowntown-cli"},"description":{"zh":"markdowntown-cli 是一个用于扫描和优化开发工作流的命令行界面工具","ja":"markdowntown-cli は開発ワークフローのスキャンと最適化に使用されるコマンドラインインターフェイスのツールです","ko":"markdowntown-cli는 개발 워크플로우를 스캔하고 최적화하는 명령줄 인터페이스 도구입니다","es":"markdowntown-cli es una herramienta de escaneo de línea de comandos para desarrolladores que necesitan escanear y analizar datos","fr":"markdowntown-cli est un outil de scan en ligne de commande pour les développeurs qui ont besoin d''analyser des données","de":"markdowntown-cli ist ein Kommandozeilen-Scan-Tool für Entwickler, die Daten scannen und analysieren müssen","pt":"O markdowntown-cli é uma ferramenta de linha de comando para scan e análise de código, desenvolvida em Node.js e CLI","ru":"ИИ Агент markdowntown-cli - это инструмент командной строки для сканирования и анализа кода, разработанный на Node.js и CLI","ar":"أداة markdowntown-cli هي أداة سطر أوامر لتحليل و فحص الكود، تم تطويرها باستخدام Node.js و CLI","en":"markdowntown scan CLI"},"definition":{"en":"markdowntown scan CLI"},"features":{"zh":["命令行界面扫描","开发工作流优化","CLI 工具集成","自动化任务执行","代码质量检查"],"ja":["コマンドラインインターフェイスのスキャン","開発ワークフローの最適化","CLI ツールの統合","自動化タスクの実行","コード品質のチェック"],"ko":["명령줄 인터페이스 스캔","개발 워크플로우 최적화","CLI 도구 통합","자동화 태스크 실행","코드 품질 체크"],"es":["Escaneo de datos mediante línea de comandos","Análisis de datos utilizando técnicas de IA","Compatibilidad con múltiples formatos de datos","Integración con herramientas de desarrollo populares","Soporte para Node.js y Python"],"fr":["Analyse de données via la ligne de commande","Analyse de données utilisant des techniques d''IA","Compatibilité avec plusieurs formats de données","Intégration avec des outils de développement populaires","Prise en charge de Node.js et Python"],"de":["Daten-Scannung über die Kommandozeile","Datenanalyse mit KI-Techniken","Unterstützung für mehrere Datenformate","Integration mit beliebten Entwicklungstools","Unterstützung für Node.js und Python"],"pt":["Scan de código","Análise de vulnerabilidades","Integração com Node.js","Interface de linha de comando","Suporte a CLI"],"ru":["Сканирование кода","Анализ уязвимостей","Интеграция с Node.js","Интерфейс командной строки","Поддержка CLI"],"ar":["فحص الكود","تحليل الثغرات","التكامل مع Node.js","واجهة سطر الأوامر","دعم CLI"]},"keywords":{"zh":["markdowntown-cli 安装","如何使用 markdowntown-cli","markdowntown-cli 教程","markdowntown-cli 替代品","CLI 工具比较","开发工作流优化技巧"],"ja":["markdowntown-cli のインストール","markdowntown-cli の使い方","markdowntown-cli のチュートリアル","markdowntown-cli の代替品","CLI ツールの比較","開発ワークフローの最適化テクニック"],"ko":["markdowntown-cli 설치","markdowntown-cli 사용법","markdowntown-cli 튜토리얼","markdowntown-cli 대체품","CLI 도구 비교","개발 워크플로우 최적화 技巧"],"es":["cómo usar markdowntown-cli","qué es markdowntown-cli","alternativas a markdowntown-cli","markdowntown-cli vs otras herramientas","instalación de markdowntown-cli","guía de configuración de markdowntown-cli","herramientas de IA para desarrolladores","escaneo de datos con markdowntown-cli"],"fr":["comment utiliser markdowntown-cli","qu''est-ce que markdowntown-cli","alternatives à markdowntown-cli","markdowntown-cli vs d''autres outils","installation de markdowntown-cli","guide de configuration de markdowntown-cli","outils d''IA pour les développeurs","analyse de données avec markdowntown-cli"],"de":["wie man markdowntown-cli verwendet","was ist markdowntown-cli","alternativen zu markdowntown-cli","markdowntown-cli vs andere tools","installation von markdowntown-cli","konfigurationsanleitung für markdowntown-cli","KI-Tools für Entwickler","daten-scannung mit markdowntown-cli"],"pt":["como usar markdowntown-cli","o que é markdowntown-cli","ferramentas de ia para desenvolvedores","markdowntown-cli vs outras ferramentas","instalar markdowntown-cli","guia de configuração do markdowntown-cli"],"ru":["как использовать markdowntown-cli","что такое markdowntown-cli","инструменты ии для разработчиков","markdowntown-cli vs другие инструменты","установить markdowntown-cli","руководство по настройке markdowntown-cli"],"ar":["كيفية استخدام markdowntown-cli","ما هي markdowntown-cli","أدوات الذكاء الاصطناعي للمطورين","markdowntown-cli مقابل أدوات أخرى","تثبيت markdowntown-cli","دليل إعداد markdowntown-cli"]}},"owner":"joelklabo","repo":"markdowntown-cli","repoPath":"joelklabo/markdowntown-cli","stars":0,"forks":0,"updatedAt":"2026-03-04T13:07:01.780Z","topics":[],"category":"community","skillMd":{"name":"markdowntown-cli","description":"Repo workflow for markdowntown CLI development and scans.","bodyPreview":"# markdowntown-cli\n\n- Build the scan CLI per `cli/docs/scan-spec-v1.md`.\n- Prefer `rg` for search and keep changes small and deterministic.\n- Run `cd cli && make lint` and `cd cli && make test`; CI must be green before finishing.\n- Avoid destructive git commands unless explicitly asked.\n- For web app changes, follow `apps/web/AGENTS.md`.","body":"# markdowntown-cli\n\n- Build the scan CLI per `cli/docs/scan-spec-v1.md`.\n- Prefer `rg` for search and keep changes small and deterministic.\n- Run `cd cli && make lint` and `cd cli && make test`; CI must be green before finishing.\n- Avoid destructive git commands unless explicitly asked.\n- For web app changes, follow `apps/web/AGENTS.md`.\n"},"lastSynced":"2026-03-04T14:24:07.668Z","agentAnalysis":{"suitability":{"en":"Perfect for CLI-focused Agents needing efficient search and scan capabilities with rg","zh":"适合需要使用rg进行高效搜索和扫描的CLI专注代理","ja":"CLI中心のエージェントがrgを使用して効率的な検索とスキャンを行うのに最適","ko":"rg를 사용하여 효율적인 검색 및 스캔이 필요한 CLI 중심 에이전트에 적합","es":"Ideal para Agentes centrados en CLI que necesitan capacidades eficientes de búsqueda y escaneo con rg","fr":"Parfait pour les Agents axés sur l''interface CLI ayant besoin de capacités de recherche et d''analyse efficaces avec rg","de":"Perfekt für CLI-basierte Agents, die effiziente Such- und Scan-Fähigkeiten mit rg benötigen","pt":"Perfeito para Agentes focados em CLI que necessitam de capacidades eficientes de busca e verificação com rg","ru":"Идеально подходит для Агентов, ориентированных на CLI, которым требуются эффективные возможности поиска и сканирования с помощью rg","ar":"مثالي لوكلاء يركزون على واجهة سطر الأوامر (CLI) ويحتاجون إلى قدرات بحث وفحص فعالة باستخدام rg"},"recommendation":{"en":"Empowers agents to perform deterministic searches using rg, while ensuring code quality with make lint and make test, and following specific guidelines for web app changes as outlined in apps/web/AGENTS.md","zh":"赋予代理使用rg进行确定性搜索的能力，同时通过make lint和make test确保代码质量，并按照apps/web/AGENTS.md中概述的特定指南进行web应用更改","ja":"エージェントがrgを使用して決定性検索を実行する能力を提供し、make lintとmake testを使用してコード品質を確保し、apps/web/AGENTS.mdに概説されている特定のガイドラインに従ってWebアプリケーションの変更を実行","ko":"에이전트가 rg를 사용하여 결정적 검색을 수행할 수 있는 기능을 제공하며, make lint와 make test를 사용하여 코드 품질을 보장하고, apps/web/AGENTS.md에 정리된 특정 지침에 따라 웹 애플리케이션 변경을 수행","es":"Permite a los agentes realizar búsquedas determinísticas utilizando rg, mientras garantiza la calidad del código con make lint y make test, y sigue las directrices específicas para cambios en aplicaciones web como se describe en apps/web/AGENTS.md","fr":"Permet aux agents d''effectuer des recherches déterministes en utilisant rg, tout en garantissant la qualité du code avec make lint et make test, et en suivant les directives spécifiques pour les modifications d''applications web comme décrit dans apps/web/AGENTS.md","de":"Ermöglicht Agents, deterministische Suchen mit rg durchzuführen, während die Codequalität mit make lint und make test sichergestellt wird und spezifische Richtlinien für Web-App-Änderungen gemäß apps/web/AGENTS.md befolgt werden","pt":"Capacita os agentes a realizar pesquisas determinísticas usando rg, garantindo a qualidade do código com make lint e make test, e seguindo diretrizes específicas para alterações em aplicativos web conforme descrito em apps/web/AGENTS.md","ru":"Позволяет агентам выполнять детерминистический поиск с помощью rg, обеспечивая качество кода с помощью make lint и make test, и следуя конкретным рекомендациям для изменений в веб-приложениях, как изложено в apps/web/AGENTS.md","ar":"يمكّن الوكلاء من إجراء عمليات بحث حتمية باستخدام rg، مع ضمان جودة التعليمات البرمجية عن طريق make lint و make test، واتباع إرشادات محددة لتغييرات تطبيقات الويب كما هو موضح في apps/web/AGENTS.md"},"useCases":{"en":["Building the scan CLI according to scan-spec-v1.md","Running automated tests with make test","Performing code linting with make lint"],"zh":["根据scan-spec-v1.md构建扫描CLI","使用make test运行自动化测试","使用make lint执行代码linting"],"ja":["scan-spec-v1.mdに基づいてスキャンCLIを構築","make testを使用して自動テストを実行","make lintを使用してコードのlintingを実行"],"ko":["scan-spec-v1.md에 따라 스캔 CLI를 구축","make test를 사용하여 자동화된 테스트를 실행","make lint를 사용하여 코드 linting을 수행"],"es":["Construir la CLI de escaneo según scan-spec-v1.md","Ejecutar pruebas automatizadas con make test","Realizar linting de código con make lint"],"fr":["Construire l''interface CLI d''analyse selon scan-spec-v1.md","Exécuter des tests automatisés avec make test","Effectuer le linting du code avec make lint"],"de":["Aufbau der Scan-CLI gemäß scan-spec-v1.md","Ausführung automatisierter Tests mit make test","Durchführung von Code-Linting mit make lint"],"pt":["Construir a CLI de verificação de acordo com scan-spec-v1.md","Executar testes automatizados com make test","Realizar linting de código com make lint"],"ru":["Создание CLI для сканирования в соответствии с scan-spec-v1.md","Запуск автоматизированных тестов с помощью make test","Выполнение линтинга кода с помощью make lint"],"ar":["بناء واجهة سطر الأوامر (CLI) للفحص وفقًا لـ scan-spec-v1.md","تشغيل الاختبارات الآلية باستخدام make test","إجراء فحص جودة التعليمات البرمجية (linting) باستخدام make lint"]},"limitations":{"en":["Requires rg for search","Must follow apps/web/AGENTS.md for web app changes","CI must be green before finishing","Avoids destructive git commands unless explicitly asked"],"zh":["需要rg进行搜索","必须按照apps/web/AGENTS.md进行web应用更改","CI必须是绿色才能完成","除非明确要求，否则避免使用破坏性的git命令"],"ja":["検索にはrgが必要","Webアプリケーションの変更にはapps/web/AGENTS.mdに従う必要がある","CIは完了する前に緑色である必要がある","明示的に要求されない限り、破壊的なgitコマンドを避ける"],"ko":["검색에는 rg가 필요","웹 애플리케이션 변경에는 apps/web/AGENTS.md를 따라야 함","CI는 완료되기 전에 녹색이어야 함","명시적으로 요청되지 않는 한, 파괴적인 git 명령을 피함"],"es":["Requiere rg para búsquedas","Debe seguir apps/web/AGENTS.md para cambios en aplicaciones web","CI debe estar en verde antes de finalizar","Evita comandos git destructivos a menos que se soliciten explícitamente"],"fr":["Nécessite rg pour la recherche","Doit suivre apps/web/AGENTS.md pour les modifications d''applications web","Le CI doit être vert avant de terminer","Évite les commandes git destructives sauf demande explicite"],"de":["Erfordert rg für die Suche","Muss apps/web/AGENTS.md für Web-App-Änderungen befolgen","CI muss grün sein vor dem Abschluss","Vermeidet destruktive Git-Befehle, sofern nicht explizit angefragt"],"pt":["Requer rg para pesquisa","Deve seguir apps/web/AGENTS.md para alterações em aplicativos web","O CI deve estar verde antes de finalizar","Evita comandos destrutivos do git, a menos que explicitamente solicitado"],"ru":["Требуется rg для поиска","Необходимо следовать apps/web/AGENTS.md для изменений в веб-приложениях","CI должен быть зеленым перед завершением","Избегает деструктивных команд git, если явно не указано иное"],"ar":["يتطلب rg للبحث","يجب اتباع apps/web/AGENTS.md لتغييرات تطبيقات الويب","يجب أن يكون CI أخضر (ناجح) قبل الانتهاء","يتجنب أوامر git المدمرة ما لم يُطلب ذلك صراحةً"]},"version":3},"contentHash":"deb84f9d8c8578935e2d8322ebc62d1b5515e2f3597b19bb8077efd31fda0e4a","qualityScore":18}');
