INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('pockfojoh/alumnos/pest-testing', 'community', 'pockfojoh', 'alumnos', 'pockfojoh/alumnos', 'pest-testing', 0, 0, 18, '2026-03-04T13:07:01.891Z', '2026-03-04T14:54:43.863Z', '05bb6cfd7acdeeaa3c2b2317ed71bb6fe329eafd204a072cfced0157e6ebd473', '{"id":"pockfojoh/alumnos/pest-testing","name":"pest-testing","description":{"zh":"pest-testing技能是一种数据库测试技术，通过自动化测试提高开发效率","ja":"pest-testingスキルはデータベーステスト技術で、自動テストにより開発効率を向上させる","ko":"pest-testing 기능은 데이터베이스 테스트 기술로 자동 테스트를 통해 개발 효율을 향상","es":"La tarea de base de datos 2 implica pruebas de pest para garantizar la calidad de los datos","fr":"La tâche de base de données 2 implique des tests de pest pour garantir la qualité des données","de":"Die Aufgabe der Datenbank 2 umfasst Pest-Tests, um die Qualität der Daten zu gewährleisten","pt":"A skill de pest-testing utiliza agentes de IA para melhorar a eficiência e reduzir custos no teste de pragas. Aprenda a implementar essa tecnologia.","ru":"Навык pest-testing использует ИИ Агенты для улучшения эффективности и снижения затрат при тестировании на вредителей. Узнайте, как реализовать эту технологию.","ar":"مهارة اختبار الآفات تستخدم وكلاء الذكاء الاصطناعي لتحسين الكفاءة وتقليل التكاليف في اختبار الآفات. تعلم كيفية تنفيذ هذه التكنولوجيا.","en":"tarea de base de datos 2"},"seo":{"title":{"zh":"AI工具：pest-testing技能","ja":"AIエージェント：pest-testingスキル","ko":"AI 에이전트: pest-testing 기능","es":"Herramientas de pruebas de pest para bases de datos","fr":"Outils de test de pest pour les bases de données","de":"Pest-Testtools für Datenbanken","pt":"Ferramentas de Teste de Pragas com Agentes de IA","ru":"ИИ Агенты для Тестирования на Вредителях","ar":"أدوات اختبار الآفات مع وكلاء الذكاء الاصطناعي","en":"pest-testing"},"description":{"zh":"pest-testing技能是一种数据库测试技术，通过自动化测试提高开发效率","ja":"pest-testingスキルはデータベーステスト技術で、自動テストにより開発効率を向上させる","ko":"pest-testing 기능은 데이터베이스 테스트 기술로 자동 테스트를 통해 개발 효율을 향상","es":"La tarea de base de datos 2 implica pruebas de pest para garantizar la calidad de los datos","fr":"La tâche de base de données 2 implique des tests de pest pour garantir la qualité des données","de":"Die Aufgabe der Datenbank 2 umfasst Pest-Tests, um die Qualität der Daten zu gewährleisten","pt":"A skill de pest-testing utiliza agentes de IA para melhorar a eficiência e reduzir custos no teste de pragas. Aprenda a implementar essa tecnologia.","ru":"Навык pest-testing использует ИИ Агенты для улучшения эффективности и снижения затрат при тестировании на вредителей. Узнайте, как реализовать эту технологию.","ar":"مهارة اختبار الآفات تستخدم وكلاء الذكاء الاصطناعي لتحسين الكفاءة وتقليل التكاليف في اختبار الآفات. تعلم كيفية تنفيذ هذه التكنولوجيا.","en":"tarea de base de datos 2"},"definition":{"en":"tarea de base de datos 2"},"features":{"zh":["自动化数据库测试","提高开发效率","支持多种数据库","简单易用","提高代码质量"],"ja":["自動化データベーステスト","開発効率の向上","複数のデータベースをサポート","シンプルで使いやすい","コード品質の向上"],"ko":["자동화 데이터베이스 테스트","개발 효율성 향상","다중 데이터베이스 지원","단순하고 사용하기 쉬움","코드 품질 향상"],"es":["Pruebas de pest automatizadas","Detección de errores en bases de datos","Integración con herramientas de AI","Informes detallados de pruebas"," Mejora de la calidad de los datos"],"fr":["Tests de pest automatisés","Détection d''erreurs dans les bases de données","Intégration avec des outils d''IA","Rapports détaillés de tests","Amélioration de la qualité des données"],"de":["Automatisierte Pest-Tests","Fehlererkennung in Datenbanken","Integration mit AI-Tools","Detaillierte Testberichte","Qualitätsverbesserung der Daten"],"pt":["Automação do teste de pragas","Melhoria da eficiência","Redução de custos","Integração com tecnologias de IA","Fácil implementação"],"ru":["Автоматизация тестирования на вредителей","Улучшение эффективности","Снижение затрат","Интеграция с технологиями ИИ","Легкая реализация"],"ar":["آليّة اختبار الآفات","تحسين الكفاءة","تقليل التكاليف","التكامل مع تكنولوجيا الذكاء الاصطناعي","تنفيذ سهل"]},"keywords":{"zh":["如何使用pest-testing","什么是数据库测试","pest-testing替代方案","pest-testing vs 其他工具","pest-testing安装","pest-testing设置指南","数据库测试工具","自动化测试"],"ja":["pest-testingの使い方","データベーステストとは","pest-testingの代替","pest-testing vs 他のツール","pest-testingのインストール","pest-testingの設定ガイド","データベーステストツール","自動テスト"],"ko":["pest-testing 사용법","데이터베이스 테스트란","pest-testing 대안","pest-testing vs 다른 도구","pest-testing 설치","pest-testing 설정 가이드","데이터베이스 테스트 도구","자동 테스트"],"es":["herramientas de pruebas de pest","pruebas de pest automatizadas","qué es el pest-testing","cómo usar herramientas de pruebas de pest","pest-testing vs testing manual","instalación de herramientas de pruebas de pest"],"fr":["outils de test de pest","tests de pest automatisés","quoi est le test de pest","comment utiliser des outils de test de pest","test de pest vs test manuel","installation d''outils de test de pest"],"de":["Pest-Testtools","automatisierte Pest-Tests","was ist Pest-Testing","wie man Pest-Testtools verwendet","Pest-Testing vs manuelles Testing","Installation von Pest-Testtools"],"pt":["como usar agentes de IA","o que é pest-testing","alternativas para teste de pragas","pest-testing vs outros métodos","instalar pest-testing","guia de configuração do pest-testing"],"ru":["как использовать ИИ Агенты","что такое pest-testing","альтернативы для тестирования на вредителей","pest-testing vs другие методы","установить pest-testing","руководство по настройке pest-testing"],"ar":["كيفية استخدام وكلاء الذكاء الاصطناعي","ما هي مهارة اختبار الآفات","بديل لاختبار الآفات","اختبار الآفات مقابل أساليب أخرى","تثبيت اختبار الآفات","دليل إعداد اختبار الآفات"]}},"owner":"pockfojoh","repo":"alumnos","repoPath":"pockfojoh/alumnos","stars":0,"forks":0,"updatedAt":"2026-03-04T13:07:01.891Z","topics":[],"category":"community","skillMd":{"name":"pest-testing","description":">-","bodyPreview":"# Pest Testing 3\n\n## When to Apply\n\nActivate this skill when:\n- Creating new tests (unit or feature)\n- Modifying existing tests\n- Debugging test failures\n- Working with datasets, mocking, or test organization\n- Writing architecture tests\n\n## Documentation\n\nUse `search-docs` for detailed Pest 3 patterns and documentation.\n\n## Basic Usage\n\n### Creating Tests\n\nAll tests must be written using Pest. Use `php artisan make:test --pest {name}`.\n\n### Test Organization\n\n- Tests live in the `tests/Feature`","body":"# Pest Testing 3\n\n## When to Apply\n\nActivate this skill when:\n- Creating new tests (unit or feature)\n- Modifying existing tests\n- Debugging test failures\n- Working with datasets, mocking, or test organization\n- Writing architecture tests\n\n## Documentation\n\nUse `search-docs` for detailed Pest 3 patterns and documentation.\n\n## Basic Usage\n\n### Creating Tests\n\nAll tests must be written using Pest. Use `php artisan make:test --pest {name}`.\n\n### Test Organization\n\n- Tests live in the `tests/Feature` and `tests/Unit` directories.\n- Do NOT remove tests without approval - these are core application code.\n- Test happy paths, failure paths, and edge cases.\n\n### Basic Test Structure\n\n<code-snippet name=\"Basic Pest Test Example\" lang=\"php\">\n\nit(''is true'', function () {\n    expect(true)->toBeTrue();\n});\n\n</code-snippet>\n\n### Running Tests\n\n- Run minimal tests with filter before finalizing: `php artisan test --compact --filter=testName`.\n- Run all tests: `php artisan test --compact`.\n- Run file: `php artisan test --compact tests/Feature/ExampleTest.php`.\n\n## Assertions\n\nUse specific assertions (`assertSuccessful()`, `assertNotFound()`) instead of `assertStatus()`:\n\n<code-snippet name=\"Pest Response Assertion\" lang=\"php\">\n\nit(''returns all'', function () {\n    $this->postJson(''/api/docs'', [])->assertSuccessful();\n});\n\n</code-snippet>\n\n| Use | Instead of |\n|-----|------------|\n| `assertSuccessful()` | `assertStatus(200)` |\n| `assertNotFound()` | `assertStatus(404)` |\n| `assertForbidden()` | `assertStatus(403)` |\n\n## Mocking\n\nImport mock function before use: `use function Pest\\Laravel\\mock;`\n\n## Datasets\n\nUse datasets for repetitive tests (validation rules, etc.):\n\n<code-snippet name=\"Pest Dataset Example\" lang=\"php\">\n\nit(''has emails'', function (string $email) {\n    expect($email)->not->toBeEmpty();\n})->with([\n    ''james'' => ''james@laravel.com'',\n    ''taylor'' => ''taylor@laravel.com'',\n]);\n\n</code-snippet>\n\n## Pest 3 Features\n\n### Architecture Testing\n\nPest 3 includes architecture testing to enforce code conventions:\n\n<code-snippet name=\"Architecture Test Example\" lang=\"php\">\n\narch(''controllers'')\n    ->expect(''App\\Http\\Controllers'')\n    ->toExtendNothing()\n    ->toHaveSuffix(''Controller'');\n\narch(''models'')\n    ->expect(''App\\Models'')\n    ->toExtend(''Illuminate\\Database\\Eloquent\\Model'');\n\narch(''no debugging'')\n    ->expect([''dd'', ''dump'', ''ray''])\n    ->not->toBeUsed();\n\n</code-snippet>\n\n### Type Coverage\n\nPest 3 provides improved type coverage analysis. Run with `--type-coverage` flag.\n\n## Common Pitfalls\n\n- Not importing `use function Pest\\Laravel\\mock;` before using mock\n- Using `assertStatus(200)` instead of `assertSuccessful()`\n- Forgetting datasets for repetitive validation tests\n- Deleting tests without approval"},"lastSynced":"2026-03-04T14:54:43.863Z","agentAnalysis":{"suitability":{"en":"Perfect for PHP-based AI Agents needing advanced test automation and debugging capabilities with Pest 3","zh":"非常适合需要使用Pest 3进行高级测试自动化和调试的PHP-based AI Agents","ja":"Pest 3を使用して高度なテスト自動化とデバッグ機能を必要とするPHPベースのAIエージェントに最適","ko":"Pest 3를 사용하여 고급 테스트 자동화 및 디버깅 기능이 필요한 PHP 기반 AI 에이전트에 적합","es":"Perfecto para Agentes de Inteligencia Artificial basados en PHP que necesitan capacidades avanzadas de automatización y depuración de pruebas con Pest 3","fr":"Parfait pour les Agents d''Intelligence Artificielle basés sur PHP ayant besoin de capacités avancées d''automatisation et de débogage de tests avec Pest 3","de":"Perfekt für PHP-basierte KI-Agents, die erweiterte Testautomatisierungs- und Debugging-Funktionen mit Pest 3 benötigen","pt":"Perfeito para Agentes de IA baseados em PHP que necessitam de capacidades avançadas de automação de teste e depuração com Pest 3","ru":"Идеально подходит для агентов ИИ на основе PHP, требующих расширенных возможностей автоматизации тестирования и отладки с помощью Pest 3","ar":"مثالي للوكلاء الذكاء الاصطناعي الذين يستندون إلى PHP الذين يحتاجون إلى قدرات متقدمة في أتمتة الاختبار وإصلاح الأخطاء باستخدام Pest 3"},"recommendation":{"en":"Empowers agents to create and manage tests using Pest, leveraging php artisan commands for test creation and organization, and utilizing datasets for mocking and test validation","zh":"赋予代理创建和管理使用Pest的测试的能力，利用php artisan命令进行测试创建和组织，并利用数据集进行模拟和测试验证","ja":"Pestを使用してテストを作成および管理するエージェントの能力を付与し、php artisanコマンドを使用してテストの作成と組織を行い、データセットを使用してモッキングとテストの検証を行う","ko":"Pest를 사용하여 테스트를 생성하고 관리하는 에이전트의 능력을 부여하며, php artisan 명령어를 사용하여 테스트 생성과 조직을 수행하고, 데이터셋을 사용하여 모의와 테스트 검증을 진행","es":"Habilita a los agentes a crear y gestionar pruebas con Pest, aprovechando los comandos php artisan para la creación y organización de pruebas, y utilizando conjuntos de datos para la simulación y validación de pruebas","fr":"Permet aux agents de créer et de gérer des tests à l''aide de Pest, en exploitant les commandes php artisan pour la création et l''organisation de tests, et en utilisant des jeux de données pour la simulation et la validation de tests","de":"Ermöglicht es den Agents, Tests mit Pest zu erstellen und zu verwalten, indem sie php artisan-Befehle für die Testerstellung und -organisation nutzen und Datenmengen für Mocking und Testvalidierung verwenden","pt":"Habilita os agentes a criar e gerenciar testes usando Pest, aproveitando comandos php artisan para criação e organização de testes e utilizando conjuntos de dados para simulação e validação de testes","ru":"Наделяет агентов возможностью создавать и управлять тестами с помощью Pest, используя команды php artisan для создания и организации тестов, а также используя наборы данных для имитации и проверки тестов","ar":"يمنح الوكلاء القدرة على إنشاء وتحكم الاختبارات باستخدام Pest، مستفيداً من أوامر php artisan لإنشاء الاختبارات وتنظيمها، واستخدام مجموعات البيانات لمحاكاة وتحقق الاختبارات"},"useCases":{"en":["Creating unit and feature tests with Pest","Debugging test failures and organizing test suites","Writing architecture tests and mocking datasets"],"zh":["使用Pest创建单元和功能测试","调试测试失败并组织测试套件","编写架构测试并模拟数据集"],"ja":["Pestを使用してユニットと機能テストを作成する","テストの失敗をデバッグし、テストスイートを組織する","アーキテクチャテストを記述し、データセットをモッキングする"],"ko":["Pest를 사용하여 유닛 및 기능 테스트를 생성","테스트 실패를 디버깅하고 테스트 스위트를 조직","아키텍처 테스트를 작성하고 데이터셋을 모의"],"es":["Creación de pruebas unitarias y de características con Pest","Depuración de fallos de pruebas y organización de conjuntos de pruebas","Escritura de pruebas de arquitectura y simulación de conjuntos de datos"],"fr":["Création de tests unitaires et de fonctionnalités avec Pest","Débogage des échecs de tests et organisation de suites de tests","Écriture de tests d''architecture et simulation de jeux de données"],"de":["Erstellung von Unit- und Feature-Tests mit Pest","Fehlerbehebung bei Testfehlern und Organisation von Test-Suiten","Schreiben von Architektur-Tests und Mocking von Datenmengen"],"pt":["Criar testes unitários e de recurso com Pest","Depurar falhas de teste e organizar conjuntos de testes","Escrever testes de arquitetura e simular conjuntos de dados"],"ru":["Создание модульных и функциональных тестов с помощью Pest","Отладка неудач тестов и организация наборов тестов","Написание тестов архитектуры и имитация наборов данных"],"ar":["إنشاء اختبارات الوحدة والسمة باستخدام Pest","تصحيح اخفاقات الاختبار وتنظيم مجموعات الاختبار","كتابة اختبارات الهيكلة ومحاكاة مجموعات البيانات"]},"limitations":{"en":["Requires PHP environment","Pest 3 compatibility needed","Limited to tests/Feature directory organization"],"zh":["需要PHP环境","需要Pest 3兼容性","仅限于tests/Feature目录组织"],"ja":["PHP環境が必要","Pest 3との互換性が必要","tests/Featureディレクトリの組織のみ"],"ko":["PHP 환경 필요","Pest 3 호환성 필요","tests/Feature 디렉토리 조직만"],"es":["Requiere entorno PHP","Se necesita compatibilidad con Pest 3","Limitado a la organización del directorio tests/Feature"],"fr":["Nécessite un environnement PHP","Compatibilité avec Pest 3 requise","Limité à l''organisation du répertoire tests/Feature"],"de":["Benötigt PHP-Umgebung","Pest 3-Kompatibilität erforderlich","Begrenzt auf die Organisation des Verzeichnisses tests/Feature"],"pt":["Requer ambiente PHP","Compatibilidade com Pest 3 necessária","Limitado à organização do diretório tests/Feature"],"ru":["Требуется среда PHP","Необходима совместимость с Pest 3","Ограниченная организация директории tests/Feature"],"ar":["يتطلب بيئة PHP","مطلوبة التوافق مع Pest 3","محدود بتنظيم دليل tests/Feature"]},"version":3},"contentHash":"05bb6cfd7acdeeaa3c2b2317ed71bb6fe329eafd204a072cfced0157e6ebd473","qualityScore":18}');
