INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('Texarkanine/ai-rizz/niko-plan', 'niko-plan', 'Texarkanine', 'ai-rizz', 'community', 'niko-plan Texarkanine ai-rizz community ai cursor developer-tools niko-plan是一个CLI工具，用于管理Cursor规则，帮助开发者提高开发效率 niko-planはカーソル規則を管理するCLIツールで、開発者の開発効率を向上させます niko-plan은 커서 규칙을 관리하는 CLI 도구로 개발자의 개발 효율을 향상합니다 niko-plan es una herramienta de línea de comandos para gestionar reglas de cursor niko-plan est un outil en ligne de commande pour gérer les règles de curseur niko-plan ist ein Kommandozeilen-Tool für die Verwaltung von Cursor-Regeln CLI tool for managing Cursor rules 如何使用niko-plan 什么是光标规则 niko-plan替代品 niko-plan vs 其他工具 niko-plan安装 niko-plan设置指南 AI智能工具 CLI工具 开发者工具 CLI tool for managing Cursor rules');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('faisalanjum/EventTrader/mock-orchestrator', 'community', 'faisalanjum', 'EventTrader', 'faisalanjum/EventTrader', 'mock-orchestrator', 0, 0, 18, '2026-03-03T13:05:37.068Z', '2026-03-03T14:19:33.049Z', 'a69c532a0245c71c8b958640909a5a62a691d391681bf680fb86dd7fc491a928', '{"id":"faisalanjum/EventTrader/mock-orchestrator","name":"mock-orchestrator","description":{"zh":"Mock Orchestrator是一个专为开发者设计的AI代理工具，它利用图数据库技术分析XBRL财务数据、新闻和市场报告，构建智能交易策略。该工具提供完整的模拟交易环境，支持Python和Node.js集成。","ja":"Mock Orchestratorは開発者向けAIエージェントツールで、グラフデータベースを活用してXBRL財務データ、ニュース、市場レポートを分析し、智能的な取引戦略を構築します。PythonとNode.js統合をサポートする完全な模拟取引環境を提供。","ko":"Mock Orchestrator는 개발자를 위한 AI 에이전트 도구로, 그래프 데이터베이스를 활용하여 XBRL 재무 데이터, 뉴스, 시장 리포트를 분석하고 지능형 트레이딩 전략을 구축합니다. Python과 Node.js 통합을 지원하는 완전한 모의 트레이딩 환경을 제공합니다.","es":"Mock Orchestrator es una skill para agentes de IA que automatiza estrategias de trading mediante el análisis de bases de datos de grafos. Procesa datos de XBRL, noticias financieras y reports para ejecutar operaciones simuladas.","fr":"Mock Orchestrator est une compétence pour agents IA qui automatise les stratégies de trading via l''analyse de bases de données graphes. Traite les données XBRL, actualités financières et rapports pour exécuter des opérations simulées.","de":"Mock Orchestrator ist eine KI-Agenten-Fähigkeit, die Handelsstrategien durch die Analyse von Graph-Datenbanken automatisiert. Verarbeitet XBRL-Daten, Finanznachrichten und Berichte für simulierte Handelsoperationen.","pt":"O mock-orchestrator é uma ferramenta de IA que utiliza bancos de dados gráficos para negociar. Ele é projetado para desenvolvedores que buscam criar aplicações de trading avançadas.","ru":"Mock-orchestrator - это инструмент ИИ, который использует графические базы данных для торговли. Он предназначен для разработчиков, которые хотят создавать продвинутые 