INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('MykolaPinchuk/QAMAS/onboard', 'onboard', 'MykolaPinchuk', 'QAMAS', 'community', 'onboard MykolaPinchuk QAMAS community onboard是VSC Codex中的Q/A MAS工具仓库，用于AI智能代理开发。它提供了开发者所需的工具和资源 onboardはVSC CodexのQ/A MASツールリポジトリで、AIエージェント開発に特化しています。開発者に必要なツールとリソースを提供 onboard는 VSC Codex의 Q/A MAS 도구 저장소로, AI 에이전트 개발을 위한 최적의 도구입니다. 개발자에게 필요한 도구와 리소스를 제공 Onboard es una herramienta de inteligencia artificial para Q/A MAS en VSC Codex, que facilita la integración y el análisis de datos Onboard est un outil d''intelligence artificielle pour Q/A MAS dans VSC Codex, qui facilite l''intégration et l''analyse des données Onboard ist ein KI-Tool für Q/A-MAS in VSC Codex, das die Integration und Analyse von Daten erleichtert O Onboard é uma ferramenta de Q/A MAS em VSC Codex para desenvolvedores Onboard - это инструмент Q/A MAS в VSC Codex для разработчиков اللوحة Onboard هي أداة Q/A MAS في VSC Codex لمطوري البرامج Repo for Q/A MAS tool in VSC Codex AI智能代理 onboard工具 VSC Codex Q/A MAS AI开发 AI模型管理 onboard安装 onboard设置指南 Repo for Q/A MAS tool in VSC Codex');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('fermaf/cgr/cgr-docs-governance', 'community', 'fermaf', 'cgr', 'fermaf/cgr', 'cgr-docs-governance', 0, 0, 18, '2026-02-28T01:32:52.722Z', '2026-02-28T03:12:34.814Z', 'd2be49a710820ea270323a4decfad962eaf6b43fe23a04260d33d4d153f1b03d', '{"id":"fermaf/cgr/cgr-docs-governance","name":"cgr-docs-governance","description":{"zh":"cgr-docs-governance是一种Jurisprudencia Administrativa的AI智能工具，帮助开发者提高效率","ja":"cgr-docs-governanceはJurisprudencia AdministrativaのAIエージェントであり、開発者の効率を向上させるために設計されたものです","ko":"cgr-docs-governance는 Jurisprudencia Administrativa의 AI 에이전트로 개발자에게 효율성을 높여줍니다","es":"cgr-docs-governance es una herramienta de inteligencia artificial que ayuda a mejorar la toma de decisiones en Jurisprudencia Administrativa.","fr":"cgr-docs-governance est un outil d''intelligence artificielle qui aide à améliorer la prise de décision en matière de jurisprudence administrative.","de":"cgr-docs-governance ist ein künstliches Intelligenz-Tool, das die Entscheidungsfindung im Verwaltungsrecht verbessert.","pt":"O cgr-docs-governance é uma ferramenta de IA que ajuda na Jurisprudencia Administrativa, fornecendo recursos para desenvolvedores.","ru":"cgr-docs-governance - это инструмент ИИ, помогающий в Административной Юриспруденции, предоставляющий ресурсы для разработчиков.","ar":"cgr-docs-governance هو أداة ذكاء اصطناعي تساعد في Jurisprudencia Administrativa، وتوفر موارد للمطورين.","en":"Jurisprudencia Administrativa"},"seo":{"title":{"zh":"AI智能工具：cgr-docs-governance概述","ja":"AIエージェント：cgr-docs-governanceの概要","ko":"AI 에이전트: cgr-docs-governance 소개","es":"Herramientas de inteligencia artificial para Jurisprudenc...","fr":"Outils d''intelligence artificielle pour la jurisprudence ...","de":"Künstliche Intelligenz-Tools für Verwaltungsrecht","pt":"Ferramentas de IA: cgr-docs-governance para Jurisprudenci...","ru":"ИИ Агенты: cgr