INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('LoopedLMs/ouro_rl/read-arxiv-paper', 'read-arxiv-paper', 'LoopedLMs', 'ouro_rl', 'community', 'read-arxiv-paper LoopedLMs ouro_rl community Ouro LM是AIエージェント中的一个重要组成部分，用于自然语言处理和生成文本 Ouro LMはAIエージェントにおける自然言語処理とテキスト生成の重要なコンポーネントです Ouro LM은 AI 에이전트에서 자연어 처리와 텍스트 생성을 위한 중요한 구성 요소입니다 read-arxiv-paper es una herramienta de IA que facilita la exploración de Ouro LM, permitiendo a los desarrolladores mejorar su flujo de trabajo read-arxiv-paper est un outil d''IA qui simplifie l''exploration de Ouro LM, permettant aux développeurs d''améliorer leur flux de travail read-arxiv-paper ist ein KI-Tool, das die Erforschung von Ouro LM vereinfacht und es Entwicklern ermöglicht, ihre Arbeitsabläufe zu verbessern A ferramenta de IA Ouro LM permite a leitura e exploração de papéis do ArXiv de forma eficiente, utilizando técnicas de processamento de linguagem natural ИИ Агент Ouro LM позволяет читать и исследовать статьи ArXiv эффективно, используя методы обработки естественного языка أداة الذكاء الاصطناعي Ouro LM تمكنك من قراءة واستكشاف ورقات ArXiv بفعالية، باستخدام تقنيات معالجة اللغة الطبيعية Exploration of Ouro LM AIエージェント Ouro LM 自然语言处理 语言模型 如何使用Ouro LM Ouro LM安装 Ouro LM设置指南 Exploration of Ouro LM');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('joshband/LocusQ/skill_design', 'community', 'joshband', 'LocusQ', 'joshband/LocusQ', 'skill_design', 1, 0, 15, '2026-02-27T04:26:57Z', '2026-02-28T01:40:38.433Z', 'a52d8160061d35f9470ce0578a513ae6564ae34c0706bde305fb152cebadeb7c', '{"id":"joshband/LocusQ/skill_design","name":"skill_design","description":{"zh":"LocusQ是一款四声道3D空间音频工具，使用JUCE 8 VST3/AU插件创建身临其境的音频体验","ja":"LocusQは四声道3D空間オーディオツールであり、JUCE 8 VST3/AUプラグインを使用して没入感の高い音響体験を作成します","ko":"LocusQ는 쿼드라포닉 3D 공간 오디오 툴로, JUCE 8 VST3/AU 플러그인을 사용하여 몰입감 있는 오디오 경험을 생성합니다","es":"LocusQ es una herramienta de audio 3D espacial quadrafónica para desarrolladores, compatible con JUCE 8 y plugins VST3/AU","fr":"LocusQ est un outil d''audio 3D spatial quadriphonique pour les développeurs, compatible avec JUCE 8 et plugins VST3/AU","de":"LocusQ ist ein 3D-Audio-Tool für Entwickler, kompatibel mit JUCE 8 und VST3/AU-Plugins","pt":"LocusQ é uma ferramenta de áudio 3D espacial quadrafônica baseada em JUCE 8 VST3/AU Plugin","ru":"LocusQ - это инструмент для 3D Spatial Audio, основанный на JUCE 8 VST3/AU Plugin","ar":"LocusQ هي أداة صوت مكاني ثلاثي الأبعاد quadraphonic مبنية على JUCE 8 VST3/AU Plugin","en":"LocusQ - Quadraphonic 3D Spatial Audio Tool (JUCE 8 VST3/AU Plugin)"},"seo":{"title":{"zh":"LocusQ AIエージェント - 四声道3D空间音频工具","ja":"LocusQ AIエージェント - 四声道3D空間オーディオツール","ko":"LocusQ AI 에이전트 - 쿼드라포닉 3D 공간 오디오 툴","es":"Herramienta de Audio 3D LocusQ - Plugin VST3/AU para desa...","fr":"Outil de Audio 3D LocusQ - Plugin VST3/AU pour les dévelo...","de":"LocusQ 3D-Audio-Tool - VST3/AU-Plugin für Entwickler","pt":"Ferramentas de Áudio 3D: LocusQ - Quadraphonic","ru":"ИИ Агенты: LocusQ - Инструмент для 3D Spatial Audio","ar":"أدوات ذكاء اصطناعي: LocusQ - أداة صوت مكاني ثلاثي الأبعاد","en":"skill_design"},"description":{"zh":"LocusQ是一款四声道3D空间音频工具，使用JUCE 8 VST3/AU插件创建身临其境的音频体验","ja":"LocusQは四声道3D空間オーディオツールであり、JUCE 8 VST3/AUプラグインを使用して没入感の高い音響体験を作成します","ko":"LocusQ는 쿼드라포닉 3D 공간 오디오 툴로, JUCE 8 VST3/AU 플러그인을 사용하여 몰입감 있는 오디오 경험을 생성합니다","es":"LocusQ es una herramienta de audio 3D espacial quadrafónica para desarrolladores, compatible con JUCE 8 y plugins VST3/AU","fr":"LocusQ est un outil d''audio 3D spatial quadriphonique pour les développeurs, compatible avec JUCE 8 et plugins VST3/AU","de":"LocusQ ist ein 3D-Audio-Tool für Entwickler, kompatibel mit JUCE 8 und VST3/AU-Plugins","pt":"LocusQ é uma ferramenta de áudio 3D espacial quadrafônica baseada em JUCE 8 VST3/AU Plugin","ru":"LocusQ - это инструмент для 3D Spatial Audio, основанный на JUCE 8 VST3/AU Plugin","ar":"LocusQ هي أداة صوت مكاني ثلاثي الأبعاد quadraphonic مبنية على JUCE 8 VST3/AU Plugin","en":"LocusQ - Quadraphonic 3D Spatial Audio Tool (JUCE 8 VST3/AU Plugin)"},"definition":{"en":"LocusQ - Quadraphonic 3D Spatial Audio Tool (JUCE 8 VST3/AU Plugin)"},"features":{"zh":["四声道3D空间音频","JUCE 8 VST3/AU插件","创建身临其境的音频体验","支持多种音频格式","易于使用的界面"],"ja":["四声道3D空間オーディオ","JUCE 8 VST3/AUプラグイン","没入感の高い音響体験の作成","複数のオーディオ形式をサポート","使いやすいインターフェース"],"ko":["쿼드라포닉 3D 공간 오디오","JUCE 8 VST3/AU 플러그인","몰입감 있는 오디오 경험 생성","여러 오디오 형식을 지원","사용하기 쉬운 인터페이스"],"es":["Compatibilidad con JUCE 8","Plugins VST3/AU","Audio 3D espacial quadrafónico","Herramienta de audio para desarrolladores","Creación de experiencias de audio inmersivas"],"fr":["Compatibilité avec JUCE 8","Plugins VST3/AU","Audio 3D spatial quadriphonique","Outil d''audio pour les développeurs","Création d''expériences audio immersives"],"de":["Kompatibilität mit JUCE 8","VST3/AU-Plugins","3D-Audio mit Quadrofonie-Technologie","Audio-Tool für Entwickler","Erstellung immersiver Audio-Erfahrungen"],"pt":["Suporte a áudio 3D espacial","Quadrafonia para uma experiência de som imersiva","Baseado em JUCE 8 VST3/AU Plugin","Fácil integração com projetos de desenvolvimento","Compatível com múltiplas plataformas"],"ru":["Поддержка 3D Spatial Audio","Квадрофония для погружающегося звукового опыта","Основан на JUCE 8 VST3/AU Plugin","Легкая интеграция с проектами разработки","Совместим с несколькими платформами"],"ar":["دعم صوت مكاني ثلاثي الأبعاد","الكوادروفونيا لتحقيق تجربة صوتية غامرة","مبني على JUCE 8 VST3/AU Plugin","إضافة سهلة إلى مشاريع التطوير","متوافق مع منصات متعددة"]},"keywords":{"zh":["如何使用LocusQ","什么是四声道3D空间音频","LocusQ替代品","LocusQ与竞争对手的比较","LocusQ安装","LocusQ设置指南","四声道3D空间音频工具","JUCE 8 VST3/AU插件"],"ja":["LocusQの使用方法","四声道3D空間オーディオとは","LocusQの代替品","LocusQと競合するツールの比較","LocusQのインストール","LocusQの設定ガイド","四声道3D空間オーディオツール","JUCE 8 VST3/AUプラグイン"],"ko":["LocusQ 사용법","쿼드라포닉 3D 공간 오디오란","LocusQ 대체품","LocusQ와 경쟁사 툴 비교","LocusQ 설치","LocusQ 설정 가이드","쿼드라포닉 3D 공간 오디오 툴","JUCE 8 VST3/AU 플러그인"],"es":["cómo usar LocusQ","qué es el audio 3D","alternativas a LocusQ","LocusQ vs otros plugins de audio","instalación de LocusQ","guía de configuración de LocusQ","desarrollo de audio 3D","herramientas de audio para desarrolladores"],"fr":["comment utiliser LocusQ","qu''est-ce que l''audio 3D","alternatives à LocusQ","LocusQ vs autres plugins audio","installation de LocusQ","guide de configuration de LocusQ","développement d''audio 3D","outils d''audio pour les développeurs"],"de":["wie man LocusQ verwendet","was ist 3D-Audio","Alternativen zu LocusQ","LocusQ vs andere Audio-Plugins","Installation von LocusQ","Konfigurationsanleitung für LocusQ","Entwicklung von 3D-Audio","Audio-Tools für Entwickler"],"pt":["como usar LocusQ","o que é áudio 3D espacial","LocusQ alternativa","LocusQ vs outros plugins","instalar LocusQ","guia de configuração do LocusQ"],"ru":["как использовать LocusQ","что такое 3D Spatial Audio","LocusQ альтернатива","LocusQ vs другие плагины","установить LocusQ","руководство по настройке LocusQ"],"ar":["كيفية استخدام LocusQ","ما هو صوت مكاني ثلاثي الأبعاد","بديل LocusQ","LocusQ مقابل برامج أخرى","تثبيت LocusQ","دليل إعداد LocusQ"]}},"owner":"joshband","repo":"LocusQ","repoPath":"joshband/LocusQ","stars":1,"forks":0,"updatedAt":"2026-02-27T04:26:57Z","topics":[],"category":"community","skillMd":{"name":"skill_design","description":"Alias router for the design phase skill in LocusQ. Use when user references `skill_design` explicitly or requests UI/interface design work.","bodyPreview":"Title: LocusQ Claude Skill Design Router\nDocument Type: Skill Router\nAuthor: APC Codex\nCreated Date: 2026-02-23\nLast Modified Date: 2026-02-23\n\nFollow the APC required load sequence:\n1. Read `.codex/rules/agent.md`\n2. Read `.codex/workflows/design.md`\n3. Read `.codex/skills/design/SKILL.md`\n4. Execute the design skill with any arguments provided.","body":"Title: LocusQ Claude Skill Design Router\nDocument Type: Skill Router\nAuthor: APC Codex\nCreated Date: 2026-02-23\nLast Modified Date: 2026-02-23\n\nFollow the APC required load sequence:\n1. Read `.codex/rules/agent.md`\n2. Read `.codex/workflows/design.md`\n3. Read `.codex/skills/design/SKILL.md`\n4. Execute the design skill with any arguments provided.\n"},"lastSynced":"2026-02-28T01:40:38.433Z","agentAnalysis":{"suitability":{"en":"Perfect for Audio Plugin Development Agents needing advanced JUCE-based VST3/AU design capabilities.","zh":"非常适合需要基于 JUCE 的高级 VST3/AU 设计功能的音频插件开发智能体。","ja":"高度な JUCE ベースの VST3/AU 設計機能を必要とするオーディオプラグイン開発エージェントに最適です。","ko":"고급 JUCE 기반 VST3/AU 설계 기능이 필요한 오디오 플러그인 개발 에이전트에 완벽합니다.","es":"Perfecto para agentes de desarrollo de plugins de audio que necesitan capacidades avanzadas de diseño VST3/AU basadas en JUCE.","fr":"Parfait pour les agents de développement de plugins audio ayant besoin de capacités avancées de conception VST3/AU basées sur JUCE.","de":"Perfekt für Audio-Plugin-Entwicklungs-Agents, die erweiterte JUCE-basierte VST3/AU-Designfähigkeiten benötigen.","pt":"Perfeito para Agentes de Desenvolvimento de Plug-ins de Áudio que necessitam de capacidades avançadas de design baseadas em JUCE para VST3/AU.","ru":"Идеально подходит для агентов разработки аудиоплагинов, которым требуются продвинутые возможности проектирования на основе JUCE для VST3/AU.","ar":"مثالي لعميل تطوير البرامج المساعدة الصوتية الذين يحتاجون إلى إمكانيات تصميم متقدمة مستندة إلى JUCE لـ VST3/AU."},"recommendation":{"en":"Enables comprehensive quadraphonic 3D spatial audio plugin design using JUCE 8 framework. Provides structured workflow integration through APC Codex design protocols and VST3/AU plugin specification compliance.","zh":"支持使用 JUCE 8 框架进行全面的四声道 3D 空间音频插件设计。通过 APC Codex 设计协议和 VST3/AU 插件规范合规性提供结构化的工作流集成。","ja":"JUCE 8 フレームワークを使用した包括的な4チャンネル 3D 空間オーディオプラグインの設計を可能にします。APC Codex 設計プロトコルと VST3/AU プラグイン仕様への準拠を通じて、構造化されたワークフロー統合を提供します。","ko":"JUCE 8 프레임워크를 사용한 포괄적인 4채널 3D 공간 오디오 플러그인 설계를 가능하게 합니다. APC Codex 설계 프로토콜 및 VST3/AU 플러그인 사양 준수를 통해 구조화된 워크플로 통합을 제공합니다.","es":"Permite un diseño integral de plugins de audio espacial 3D cuadrafónico utilizando el framework JUCE 8. Proporciona integración de flujo de trabajo estructurado a través de los protocolos de diseño APC Codex y cumplimiento de las especificaciones de plugins VST3/AU.","fr":"Permet une conception complète de plugins d''audio spatial 3D quadriphoniques en utilisant le framework JUCE 8. Fournit une intégration de flux de travail structuré grâce aux protocoles de conception APC Codex et au respect des spécifications de plugins VST3/AU.","de":"Ermöglicht umfassendes quadraphonisches 3D-Raumklang-Plugin-Design unter Verwendung des JUCE 8-Frameworks. Bietet strukturierte Workflow-Integration durch APC Codex-Designprotokolle und Einhaltung der VST3/AU-Plugin-Spezifikationen.","pt":"Permite o design de plug-ins de áudio espaciais 3D quadrafônicos abrangentes usando o framework JUCE 8. Fornece integração de fluxo de trabalho estruturada por meio dos protocolos de design APC Codex e conformidade com a especificação de plug-ins VST3/AU.","ru":"Позволяет разрабатывать комплексные квадрофонические плагины 3D-аудио, используя фреймворк JUCE 8. Обеспечивает структурированную интеграцию рабочего процесса посредством протоколов дизайна APC Codex и соответствие спецификации плагинов VST3/AU.","ar":"يمكّن تصميم برامج مساعدة صوتية متعددة الأبعاد 3D quadrafonic شاملة باستخدام إطار العمل JUCE 8. يوفر تكامل سير عمل منظم من خلال بروتوكولات تصميم APC Codex وامتثال لمواصفات البرامج المساعدة VST3/AU."},"useCases":{"en":["Designing quadraphonic audio processing chains","Implementing 3D spatial audio algorithms","Generating VST3/AU plugin architectures","Routing audio signals through spatial environments"],"zh":["设计四声道音频处理链","实现 3D 空间音频算法","生成 VST3/AU 插件架构","在空间环境中路由音频信号"],"ja":["4チャンネルオーディオ処理チェーンの設計","3D 空間オーディオアルゴリズムの実装","VST3/AU プラグインアーキテクチャの生成","空間環境を通じたオーディオ信号のルーティング"],"ko":["4채널 오디오 처리 체인 설계","3D 공간 오디오 알고리즘 구현","VST3/AU 플러그인 아키텍처 생성","공간 환경을 통한 오디오 신호 라우팅"],"es":["Diseñando cadenas de procesamiento de audio cuadrafónicas","Implementando algoritmos de audio espacial 3D","Generando arquitecturas de plugins VST3/AU","Enrutando señales de audio a través de entornos espaciales"],"fr":["Conception de chaînes de traitement audio quadriphoniques","Implémentation d''algorithmes d''audio spatial 3D","Génération d''architectures de plugins VST3/AU","Routage de signaux audio à travers des environnements spatiaux"],"de":["Entwerfen quadraphonischer Audioverarbeitungsketten","Implementieren von 3D-Raumklangalgorithmen","Erzeugen von VST3/AU-Plugin-Architekturen","Weiterleiten von Audiosignalen durch räumliche Umgebungen"],"pt":["Projetar cadeias de processamento de áudio quadrafônicas","Implementar algoritmos de áudio espacial 3D","Gerar arquiteturas de plug-ins VST3/AU","Encaminhar sinais de áudio por meio de ambientes espaciais"],"ru":["Проектировать квадрофонические цепочки аудиопереработки","Реализовывать алгоритмы 3D-пространственного аудио","Генерировать архитектуры плагинов VST3/AU","Маршрутизировать аудиосигналы через пространственные среды"],"ar":["تصميم سلاسل معالجة الصوت الرباعية","تنفيذ خوارزميات الصوت المكاني ثلاثي الأبعاد","генерировать هياكل برامج مساعدة VST3/AU","توجيه إشارات الصوت من خلال بيئات مكانية"]},"limitations":{"en":["Requires JUCE 8 framework","Limited to VST3/AU plugin formats","Depends on APC Codex workflow compliance","Requires specific load sequence execution"],"zh":["需要 JUCE 8 框架","仅限于 VST3/AU 插件格式","依赖 APC Codex 工作流合规性","需要特定的加载顺序执行"],"ja":["JUCE 8 フレームワークが必要","VST3/AU プラグインフォーマットに限定","APC Codex ワークフロー準拠に依存","特定のロードシーケンス実行が必要"],"ko":["JUCE 8 프레임워크 필요","VST3/AU 플러그인 형식으로 제한됨","APC Codex 워크플로 준수에 의존","특정 로드 시퀀스 실행 필요"],"es":["Requiere el framework JUCE 8","Limitado a los formatos de plugin VST3/AU","Depende del cumplimiento del flujo de trabajo APC Codex","Requiere una secuencia de carga específica"],"fr":["Nécessite le framework JUCE 8","Limité aux formats de plugins VST3/AU","Dépend du respect du flux de travail APC Codex","Nécessite une séquence de chargement spécifique"],"de":["Erfordert das JUCE 8-Framework","Beschränkt auf VST3/AU-Plugin-Formate","Hängt von der Einhaltung des APC Codex-Workflows ab","Erfordert eine spezifische Ladesequenzausführung"],"pt":["Requer o framework JUCE 8","Limitado a formatos de plug-ins VST3/AU","Depende da conformidade do fluxo de trabalho APC Codex","Requer sequência de carga de execução específica"],"ru":["Требуется фреймворк JUCE 8","Ограничен форматами плагинов VST3/AU","Зависит от соблюдения протоколов рабочего процесса APC Codex","Требуется определенная последовательность выполнения загрузки"],"ar":["يتطلب إطار العمل JUCE 8","محدود بصيغ برامج المساعدة VST3/AU","يعتمد على امتثال بروتوكول سير العمل APC Codex","يتطلب تسلسل تنفيذ تحميل محدد"]},"version":3},"contentHash":"a52d8160061d35f9470ce0578a513ae6564ae34c0706bde305fb152cebadeb7c","qualityScore":15}');
