INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('tdhopper/dotfiles2.0/home-network-admin', 'home-network-admin', 'tdhopper', 'dotfiles2.0', 'community', 'home-network-admin tdhopper dotfiles2.0 community home-network-admin是使用yadm管理dotfiles仓库的AI智能代理，提供简化的网络管理解决方案 home-network-adminはyadmで管理するdotfilesリポジトリのAIエージェント、簡素化されたネットワーク管理ソリューションを提供 home-network-admin은 yadm으로 관리하는 dotfiles 리포지토리의 AI 에이전트로, 간소화된 네트워크 관리 솔루션을 제공 El nuevo repositorio de dotfiles gestionado con yadm permite a los administradores de redes domésticas gestionar sus archivos de configuración de manera más eficiente Le nouveau dépôt de dotfiles géré avec yadm permet aux administrateurs de réseaux domestiques de gérer leurs fichiers de configuration de manière plus efficace Das neue Repository von Dotfiles, das mit yadm verwaltet wird, ermöglicht es den Administratoren von Heimnetzwerken, ihre Konfigurationsdateien effizienter zu verwalten O repositório de dotfiles gerenciado com yadm permite uma administração de rede doméstica eficiente. Aprenda a configurar sua rede Репозиторий dotfiles, управляемый с помощью yadm, позволяет эффективно администрировать домашнюю сеть. Узнайте, как настроить сеть مستودع dotfiles المُدارة مع يادم يسمح بإدارة شبكة محلية فعالة. تعلم كيفية ضبط شبكتك The new dotfiles repo managed with yadm 如何使用home-network-admin 什么是dotfiles仓库 home-network-admin安装 home-network-admin配置 home-network-admin alternative home-network-admin vs 其他AI代理 dotfiles仓库管理 网络管理解决方案 AI智能代理 The new dotfiles repo managed with yadm');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('atlanhq/atlan-sample-apps/atlan-sql-connector-patterns', 'community', 'atlanhq', 'atlan-sample-apps', 'atlanhq/atlan-sample-apps', 'atlan-sql-connector-patterns', 0, 0, 15, '2026-03-04T13:07:01.707Z', '2026-03-04T13:42:16.884Z', '89e1e1206f17a7bc4b2259f7f3ee8662588affd482af92b71d2ef1ab13200873', '{"id":"atlanhq/atlan-sample-apps/atlan-sql-connector-patterns","name":"atlan-sql-connector-patterns","description":{"zh":"Atlan SQL 连接器模式是使用 Atlan 应用程序 SDK 构建的示例应用","ja":"Atlan SQL コネクタ パターンは、Atlan Application SDK を使用して構築されたサンプル アプリケーションです","ko":"Atlan SQL 커넥터 패턴은 Atlan Application SDK로 구축된 샘플 애플리케이션입니다","es":"La aplicación de ejemplo Atlan utiliza el SDK de Atlan para demostrar patrones de conector SQL. Es una herramienta de agente de IA para desarrolladores.","fr":"L''application exemple Atlan utilise le SDK Atlan pour démontrer des modèles de connecteur SQL. C''est un outil d''agent IA pour les développeurs.","de":"Die Beispielanwendung Atlan verwendet das Atlan-SDK, um Muster für den SQL-Connector zu demonstrieren. Es ist ein KI-Tool-Agent für Entwickler.","pt":"A aplicação de exemplo Atlan SDK demonstra como usar conectores SQL para desenvolvedores","ru":"Примерная aplikatsiya Atlan SDK показывает, как использовать коннекторы SQL для разработчиков","ar":"تُظهر تطبيقنا العينة Atlan SDK كيفية استخدام موصلات SQL لل مطورين","en":"Sample application built using Atlan Application SDK"},"seo":{"title":{"zh":"Atlan SQL 连接器模式 - AI 工具","ja":"Atlan SQL コネクタ パターン - AI エージェント","ko":"Atlan SQL 커넥터 패턴 - AI 에이전트","es":"Patrones de Conector SQL Atlan - Herramientas de Agente d...","fr":"Modèles de Connecteur SQL Atlan - Outils d''Agent IA","de":"Atlan SQL-Connector-Muster - KI-Tool-Agent","pt":"Conectores SQL Atlan: Ferramentas de IA para Desenvolvedores","ru":"ИИ Агенты Atlan: Шаблоны коннекторов SQL","ar":"أدوات الذكاء الاص