INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('Exaphis/baby-copilot/unslop', 'unslop', 'Exaphis', 'baby-copilot', 'community', 'unslop Exaphis baby-copilot community unslop是一个小巧的代码补全工具，能够帮助开发者提高编码效率 unslopはコンパクトなコード補完ツールで、開発者の生産性を向上させます unslop는 코드 자동 완성을 제공하는 작은 도구로 개발자에게 효율성을 제공합니다 unslop es una herramienta de finalización de código minimalista para desarrolladores. Mejora tu productividad con esta herramienta de AI unslop est un outil de complétion de code minimaliste pour les développeurs. Améliorez votre productivité avec cet outil d''IA unslop ist ein minimalistisches Code-Vervollständigungstool für Entwickler. Verbessern Sie Ihre Produktivität mit diesem KI-Tool O unslop é uma ferramenta de conclusão de código para desenvolvedores, projetada para melhorar a produtividade e reduzir o tempo de desenvolvimento Unslop - это инструмент завершения кода для разработчиков, предназначенный для повышения производительности и сокращения времени разработки unslop هي أداة استكمال الشفرة للمطورين، مصممة لتحسين الإنتاجية وتقليل وقت التطوير A teeny code completion tool. 代码补全工具 AI代码补全 代码自动补全 开发者工具 编程效率 unslop介绍 unslop教程 代码补全插件 A teeny code completion tool.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('elmagnificogi/elmagnificogi.github.io/article-review', 'community', 'elmagnificogi', 'elmagnificogi.github.io', 'elmagnificogi/elmagnificogi.github.io', 'article-review', 0, 0, 15, '2026-03-04T13:07:01.795Z', '2026-03-04T14:28:24.226Z', '33652c68f2e04e57d21e2899b5a65b49acd846771e67d4ae6a4e33eacb7219fb', '{"id":"elmagnificogi/elmagnificogi.github.io/article-review","name":"article-review","description":{"zh":"文章审查是AI智能工具的一项功能，用于审查和评估文章内容","ja":"記事レビューはAIエージェントの機能の一つで、記事の内容を審査・評価します","ko":"기사 리뷰는 AI 에이전트의 기능 중 하나로 기사 내용을審査・評価합니다","es":"La herramienta de revisión de artículos utiliza Agentes de IA para mejorar la eficiencia y la precisión en la revisión de contenido","fr":"L''outil de révision d''articles utilise les Agents d''IA pour améliorer l''efficacité et la précision dans la révision de contenu","de":"Das Artikel-Überprüfungstool verwendet KI-Agenten, um die Effizienz und Genauigkeit bei der Überprüfung von Inhalten zu verbessern","pt":"Os Agentes de IA podem ajudar na revisão de artigos de forma eficiente. Clique aqui para saber mais sobre essa tecnologia","ru":"ИИ Агенты могут помочь в проверке статей эффективно. Нажмите здесь, чтобы узнать больше об этой технологии","ar":"يمكن لوكلاء الذكاء الاصطناعي مساعدتك في مراجعة المقالات بفعالية. انقر هنا لمعرفة المزيد حول هذه التكنولوجيا","en":"Click here to see my blog"},"seo":{"title":{"zh":"AI智能工具 - 文章审查","ja":"AIエージェント - 記事レビュー","ko":"AI 에이전트 - 기사 리뷰","es":"Herramientas de revisión de artículos con Agentes de IA","fr":"Outils de révision d''articles avec les Agents d''IA","de":"Artikel-Überprüfungstools mit KI-Agenten","pt":"Ferramentas de Revisão de Artigos com Agentes de IA","ru":"ИИ Агенты для Проверки Статей","ar":"أدوات مراجعة المقال مع وكلاء الذكاء الاصطناعي","en":"article-review"},"description":{"zh":"文章审查是AI智能工具的一项功能，用于审查和评估文章内容","ja":"記事レビューはAIエージェントの機能の一つで、記事の内容を審査・評価します","ko":"기사 리뷰는 AI 에이전트의 기능 중 하나로 기사 내용을審査・評価합니다","es":"La herramienta de revisión de artículos utiliza Agentes de IA para mejorar la eficiencia y la precisión en la revisión de contenido","fr":"L''outil de révision d''articles utilise les Agents d''IA pour améliorer l''efficacité et la précision dans la révision de contenu","de":"Das Artikel-Überprüfungstool verwendet KI-Agenten, um die Effizienz und Genauigkeit bei der Überprüfung von Inhalten zu verbessern","pt":"Os Agentes de IA podem ajudar na revisão de artigos de forma eficiente. Clique aqui para saber mais sobre essa tecnologia","ru":"ИИ Агенты могут помочь в проверке статей эффективно. Нажмите здесь, чтобы узнать больше об этой технологии","ar":"يمكن لوكلاء الذكاء الاصطناعي مساعدتك في مراجعة المقالات بفعالية. انقر هنا لمعرفة المزيد حول هذه التكنولوجيا","en":"Click here to see my blog"},"definition":{"en":"Click here to see my blog"},"features":{"zh":["支持多种文章格式","提供详细的审查报告","集成React、Python、Node.js等开发工具","支持CLI命令行操作","提供实时审查结果"],"ja":["多種の記事形式をサポート","詳細な審査レポートを提供","React、Python、Node.jsなどの開発ツールと統合","CLIコマンドライン操作をサポート","リアルタイムの審査結果を提供"],"ko":["다양한 기사 형식을 지원","詳細한審査 보고서를 제공","React、Python、Node.jsなどの 개발 도구와 통합","CLI 명령줄操作을 지원","실시간 기사審査 결과를 제공"],"es":["Revisión de artículos automatizada","Análisis de contenido con Agentes de IA","Mejora de la eficiencia en la revisión de contenido","Integración con herramientas de desarrollo como React y Node.js","Compatibilidad con interfaces de línea de comandos (CLI)"],"fr":["Révision d''articles automatisée","Analyse de contenu avec les Agents d''IA","Amélioration de l''efficacité dans la révision de contenu","Intégration avec des outils de développement comme React et Node.js","Compatibilité avec les interfaces de ligne de commande (CLI)"],"de":["Automatisierte Artikel-Überprüfung","Inhaltsanalyse mit KI-Agenten","Verbesserung der Effizienz bei der Überprüfung von Inhalten","Integration mit Entwicklungstools wie React und Node.js","Kompatibilität mit Kommandozeilen-Schnittstellen (CLI)"],"pt":["Revisão de artigos eficiente com Agentes de IA","Análise de conteúdo com tecnologia de ponta","Integração com ferramentas de desenvolvimento como React e Node.js","Suporte a CLI para uso fácil","Integração com tecnologias de IA como Python"],"ru":["Эффективная проверка статей с помощью ИИ Агентов","Анализ контента с использованием передовых технологий","Интеграция с инструментами разработки như React и Node.js","Поддержка CLI для легкого использования","Интеграция с технологиями ИИ như Python"],"ar":["مراجعة مقالات فعالة مع وكلاء الذكاء الاصطناعي","تحليل المحتوى باستخدام تكنولوجيا متقدمة","التكامل مع أدوات التطوير مثل React و Node.js","دعم CLI لاستخدام سهل","التكامل مع تكنولوجيا الذكاء الاصطناعي مثل Python"]},"keywords":{"zh":["如何使用AI智能工具","什么是文章审查","AI智能工具替代品","AI智能工具与其他工具的比较","AI智能工具安装","AI智能工具设置指南","文章审查工具","AI开发工具"],"ja":["AIエージェントの使い方","記事レビューとは","AIエージェントの代替品","AIエージェントと他のツールの比較","AIエージェントのインストール","AIエージェントの設定ガイド","記事レビューツール","AI開発ツール"],"ko":["AI 에이전트 사용법","기사 리뷰란 무엇인가","AI 에이전트 대체품","AI 에이전트와 다른 도구의 비교","AI 에이전트 설치","AI 에이전트 설정 가이드","기사 리뷰 도구","AI 개발 도구"],"es":["cómo usar herramientas de revisión de artículos","qué es un Agente de IA","alternativas a herramientas de revisión de artículos","herramientas de revisión de artículos vs competidores","instalación de herramientas de revisión de artículos","guía de configuración de herramientas de revisión de artículos","desarrollo de herramientas de revisión de artículos con Python","herramientas de revisión de artículos para desarrolladores"],"fr":["comment utiliser des outils de révision d''articles","quoi est un Agent d''IA","alternatives aux outils de révision d''articles","outils de révision d''articles vs concurrents","installation d''outils de révision d''articles","guide de configuration d''outils de révision d''articles","développement d''outils de révision d''articles avec Python","outils de révision d''articles pour développeurs"],"de":["wie man Artikel-Überprüfungstools verwendet","was ist ein KI-Agent","Alternativen zu Artikel-Überprüfungstools","Artikel-Überprüfungstools vs Wettbewerber","Installation von Artikel-Überprüfungstools","Konfigurationshandbuch für Artikel-Überprüfungstools","Entwicklung von Artikel-Überprüfungstools mit Python","Artikel-Überprüfungstools für Entwickler"],"pt":["como usar Agentes de IA para revisão de artigos","o que é Agente de IA para revisão de artigos","Agentes de IA vs revisão de artigos manual","instalação de Agentes de IA para revisão de artigos","guia de configuração de Agentes de IA para revisão de artigos","alternativas para Agentes de IA para revisão de artigos"],"ru":["как использовать ИИ Агенты для проверки статей","что такое ИИ Агент для проверки статей","ИИ Агенты vs ручная проверка статей","установка ИИ Агентов для проверки статей","руководство по настройке ИИ Агентов для проверки статей","альтернативы ИИ Агентам для проверки статей"],"ar":["كيفية استخدام وكلاء الذكاء الاصطناعي لمراجعة المقالات","ما هو وكيل الذكاء الاصطناعي لمراجعة المقالات","وكلاء الذكاء الاصطناعي vs مراجعة المقالات يدويا","تثبيت وكلاء الذكاء الاصطناعي لمراجعة المقالات","دليل إعداد وكلاء الذكاء الاصطناعي لمراجعة المقالات","بديلات لوكلاء الذكاء الاصطناعي لمراجعة المقالات"]}},"owner":"elmagnificogi","repo":"elmagnificogi.github.io","repoPath":"elmagnificogi/elmagnificogi.github.io","stars":0,"forks":0,"updatedAt":"2026-03-04T13:07:01.795Z","topics":[],"category":"community","skillMd":{"name":"article-review","description":"审查和润色博客文章内容，检查书写错误并根据既有风格进行润色。用于处理符合“年-月-日-文章标题”命名规则的文章文件。","bodyPreview":"# 文章内容审查\n\n为 Agent 提供的详细指令。\n\n## 使用时机\n\n- 在以下情况使用此技能\n- 如果文档名称符合“年-月-日-文章标题”的规则，类似：`2015-11-11-RaspberryStartup-5`\n- 如果只是要审查文章，那么只用执行指令的1、2、3步骤即可\n- 如果要审查润色文章，那么执行所有步骤\n\n## 指令\n\n- 1.帮我检查一下当前文档中是否存在文字书写错误\n- 2.忽略标点符号、中英混排的问题\n- 3.完成上述检查和修改后，先向我简要汇报修改点，等待我确认\n- 4.阅读当前文档，并模仿文档中书写的风格和语气，对全文进行润色","body":"# 文章内容审查\n\n为 Agent 提供的详细指令。\n\n## 使用时机\n\n- 在以下情况使用此技能\n- 如果文档名称符合“年-月-日-文章标题”的规则，类似：`2015-11-11-RaspberryStartup-5`\n- 如果只是要审查文章，那么只用执行指令的1、2、3步骤即可\n- 如果要审查润色文章，那么执行所有步骤\n\n## 指令\n\n- 1.帮我检查一下当前文档中是否存在文字书写错误\n- 2.忽略标点符号、中英混排的问题\n- 3.完成上述检查和修改后，先向我简要汇报修改点，等待我确认\n- 4.阅读当前文档，并模仿文档中书写的风格和语气，对全文进行润色\n"},"lastSynced":"2026-03-04T14:28:24.226Z","agentAnalysis":{"suitability":{"en":"Ideal for Language Agents like Claude Code, AutoGPT, and LangChain needing advanced article review and editing capabilities.","zh":"适合于 Claude Code、AutoGPT 和 LangChain 等语言代理，需要高级的文章审查和编辑功能。","ja":"Claude Code、AutoGPT、LangChain などの言語エージェントが高度な記事のレビューと編集機能を必要とする場合に最適です。","ko":"Claude Code, AutoGPT, LangChain 등과 같은 언어 에이전트가 고급 기사 검토 및 편집 기능을 필요로 하는 경우에 적합합니다.","es":"Ideal para Agentes de Lenguaje como Claude Code, AutoGPT y LangChain que necesitan capacidades avanzadas de revisión y edición de artículos.","fr":"Idéal pour les Agents de Langage tels que Claude Code, AutoGPT et LangChain nécessitant des capacités de révision et de modification d''articles avancées.","de":"Ideal für Sprachagenten wie Claude Code, AutoGPT und LangChain, die erweiterte Artikel-Überprüfungs- und Bearbeitungsfunktionen benötigen.","pt":"Ideal para Agentes de Linguagem como Claude Code, AutoGPT e LangChain que necessitam de capacidades avançadas de revisão e edição de artigos.","ru":"Идеально для языковых агентов, таких как Claude Code, AutoGPT и LangChain, требующих расширенных возможностей проверки и редактирования статей.","ar":"مثالي للوكلاء اللغويين مثل Claude Code و AutoGPT و LangChain الذين يحتاجون إلى قدرات متقدمة لمراجعة وتحرير المقال"},"recommendation":{"en":"Empowers agents to perform comprehensive content analysis, ignoring markups and syntax, and providing detailed modification reports, utilizing natural language processing to refine article quality, and mimicking the author''s style for rewriting and editing, all while handling specific file naming conventions like ''年-月-日-文章标题''","zh":"赋予代理进行全面内容分析的能力，忽略标记和语法，并提供详细的修改报告，利用自然语言处理来提高文章质量，并模仿作者的风格进行重写和编辑，同时处理特定的文件命名约定，如 ''年-月-日-文章标题''","ja":"マークアップや構文を無視し、詳細な修正レポートを提供して記事の品質を向上させるために自然言語処理を利用し、著者のスタイルを模倣して書き直しや編集を行うなど、包括的なコンテンツ分析を実行するエージェントに力を与え、特定のファイル命名規則（例： ''年-月-日-記事タイトル''）も処理します。","ko":"마크업이나 구문을 무시하고, 상세한 수정 보고서를 제공하여 기사의 품질을 향상시키기 위한 자연어 처리를 활용하고, 저자의 스타일을 모방하여 다시 작성하고 편집하는 등, 포괄적인 콘텐츠 분석을 수행하는 에이전트에 힘을 부여하고, 특정 파일 이름 규칙(예: ''년-월-일-기사제목'')도 처리합니다.","es":"Permite a los agentes realizar un análisis de contenido integral, ignorando marcas y sintaxis, y proporcionando informes de modificación detallados, utilizando el procesamiento de lenguaje natural para refinar la calidad del artículo y imitar el estilo del autor para la reescritura y edición, todo mientras maneja convenciones de nombres de archivos específicas como ''年-月-日-文章标题''","fr":"Permet aux agents d''effectuer une analyse de contenu complète, en ignorant les balises et la syntaxe, et en fournissant des rapports de modification détaillés, en utilisant le traitement automatique des langues pour affiner la qualité de l''article et imiter le style de l''auteur pour la réécriture et l''édition, le tout en gérant des conventions de nommage de fichiers spécifiques comme ''年-月-日-文章标题''","de":"Ermöglicht es Agenten, eine umfassende Inhaltsanalyse durchzuführen, Markup und Syntax zu ignorieren und detaillierte Änderungsberichte bereitzustellen, wobei die natürliche Sprachverarbeitung zur Verfeinerung der Artikelqualität eingesetzt wird und den Stil des Autors für das Umschreiben und Bearbeiten nachahmt, während spezifische Dateinamenskonventionen wie ''年-月-日-文章标题'' gehandhabt werden","pt":"Habilita os agentes a realizar análise de conteúdo abrangente, ignorando marcações e sintaxe, e fornecendo relatórios de modificação detalhados, utilizando o processamento de linguagem natural para refinar a qualidade do artigo e imitar o estilo do autor para reescrever e editar, tudo isso lidando com convenções de nomenclatura de arquivos específicas como ''年-月-日-文章标题''","ru":"Наделяет агентов возможностью проводить всесторонний анализ контента, игнорируя маркировку и синтаксис, и предоставляет подробные отчеты о модификациях, используя обработку естественного языка для совершенствования качества статьи и имитации стиля автора для переписывания и редактирования, все это при обработке определенных соглашений о наименовании файлов, таких как ''年-月-日-文章标题''","ar":"يتمكّن الوكلاء من أداء تحليل شامل للمحتوى، متجاهلين التعليمات والتركيب، وتقديم تقارير تعديل مفصلة، باستخدام معالجة اللغة الطبيعية لتحسين جودة المقال وتقليد أسلوب الكاتب لإعادة الكتابة والتحرير، مع التعامل مع اتفاقيات تسمية الملفات المحددة مثل ''年-月-日-文章标题''"},"useCases":{"en":["Automating article proofreading for typo detection","Generating rewritten articles in the original author''s style","Debugging content inconsistencies and suggesting improvements"],"zh":["自动化文章校对以检测打字错误","生成以原始作者风格重写的文章","调试内容不一致性并建议改进"],"ja":["タイポ検出のための記事の校正を自動化する","元の著者のスタイルで書き直された記事を生成する","コンテンツの不一致をデバッグし、改善を提案する"],"ko":["오류 검출을 위한 기사 校正을 자동화하는 것","원래 저자의 스타일로 다시 작성된 기사를 생성하는 것","콘텐츠의 불일치를 디버깅하고 개선을 제안하는 것"],"es":["Automatización de la corrección de pruebas de artículos para la detección de errores de escritura","Generación de artículos reescritos en el estilo del autor original","Depuración de inconsistencias de contenido y sugerencia de mejoras"],"fr":["Automatisation de la correction de preuves d''articles pour la détection d''erreurs de frappe","Génération d''articles réécrits dans le style de l''auteur original","Débogage des incohérences de contenu et suggestion d''améliorations"],"de":["Automatisierung der Korrektur von Artikelbeweisen für die Erkennung von Tippfehlern","Erzeugung von umgeschriebenen Artikeln im Stil des ursprünglichen Autors","Fehlerbehebung bei Inhalten und Vorschlägen zur Verbesserung"],"pt":["Automatizar a revisão de provas de artigos para detecção de erros de digitação","Gerar artigos reescritos no estilo do autor original","Depurar inconsistências de conteúdo e sugerir melhorias"],"ru":["Автоматизировать проверку корректуры статей для обнаружения опечаток","Генерировать переписанные статьи в стиле оригинального автора","Отладить несоответствия контента и предложить улучшения"],"ar":["أتمتة تصحيح البراهين للمقالات للكشف عن الأخطاء الإملائية","إعادة كتابة المقالات بأسلوب المؤلف الأصلي","تصحيح عدم التماثل في المحتوى وتقديم مقترحات للتحسين"]},"limitations":{"en":["Requires specific file naming format","Limited to text-based article review and editing"],"zh":["需要特定的文件命名格式","仅限于基于文本的文章审查和编辑"],"ja":["特定のファイル命名形式が必要","テキストベースの記事のレビューと編集に限定される"],"ko":["특정 파일 이름 형식이 필요","텍스트 기반의 기사 검토 및 편집에만 제한"],"es":["Requiere un formato de nombre de archivo específico","Limitado a la revisión y edición de artículos basados en texto"],"fr":["Nécessite un format de nom de fichier spécifique","Limité à la révision et à l''édition d''articles basés sur le texte"],"de":["Benötigt ein bestimmtes Dateinamensformat","Begrenzt auf die Überprüfung und Bearbeitung von textbasierten Artikeln"],"pt":["Exige formato de nomenclatura de arquivo específico","Limitado à revisão e edição de artigos baseados em texto"],"ru":["Требует определенного формата наименования файла","Ограничен проверкой и редактированием статей на основе текста"],"ar":["يتطلب تنسيقًا محددًا لاسم الملف","محدود بالمراجعة والتحرير للمقالات القائمة على النص"]},"version":3},"contentHash":"33652c68f2e04e57d21e2899b5a65b49acd846771e67d4ae6a4e33eacb7219fb","qualityScore":15}');
