INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('xiaoshenming/aiteacher-monorepo/nx-plugins', 'nx-plugins', 'xiaoshenming', 'aiteacher-monorepo', 'community', 'nx-plugins xiaoshenming aiteacher-monorepo community nx-plugins是AI Teacher项目的Monorepo，使用Nx管理多个应用和服务，实现高效的开发和部署 nx-pluginsはAI TeacherプロジェクトのMonorepoで、Nxを使用して複数のアプリケーションとサービスを管理することで、効率的な開発とデプロイを実現 nx-plugins는 AI Teacher 프로젝트의 Monorepo로, Nx를 사용하여 여러 애플리케이션과 서비스를 관리하여 효율적인 개발과 배포를 실현 nx-plugins es un proyecto de Monorepo que utiliza Nx para gestionar múltiples aplicaciones y servicios de Inteligencia Artificial nx-plugins est un projet de Monorepo qui utilise Nx pour gérer plusieurs applications et services d''Intelligence Artificielle nx-plugins ist ein Projekt von Monorepo, das Nx verwendet, um mehrere Anwendungen und Dienstleistungen für KI zu verwalten O nx-plugins é um projeto de monorepo que utiliza Nx para gerenciar múltiplos aplicativos e serviços, ideal para desenvolvedores que buscam uma solução eficaz nx-plugins - это проект монорепозитория, который использует Nx для управления несколькими приложениями и сервисами, подходящий для разработчиков, ищущих эффективное решение nx-plugins هو مشروع مونو ريبوزиторي يستخدم Nx لإدارة تطبيقات وخدمات متعددة، مثالي للمطورين الذين يبحثون عن حل فعال AI Teacher 项目的 Monorepo，使用 Nx 管理多个应用和服务。 nx-plugins AI智能工具 Monorepo Nx 如何使用nx-plugins nx-plugins安装 nx-plugins设置指南 nx-plugins vs 其他工具 AI Teacher 项目的 Monorepo，使用 Nx 管理多个应用和服务。');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('shiguruikai/cam-head-tracker/doc-reviewer', 'community', 'shiguruikai', 'cam-head-tracker', 'shiguruikai/cam-head-tracker', 'doc-reviewer', 0, 0, 15, '2026-03-04T13:07:01.893Z', '2026-03-04T14:55:09.477Z', 'cf42d754a05642ebc411bc1d31f0ea1fa679b2aabe384248c2835ec561971711', '{"id":"shiguruikai/cam-head-tracker/doc-reviewer","name":"doc-reviewer","description":{"zh":"doc-reviewer是一个使用UDP向opentrack发送姿势数据的AI智能头部跟踪应用，用于跟踪用户的头部运动","ja":"doc-reviewerは、カメラベースのヘッドトラッキングアプリで、opentrackにUDPで姿勢データを送信できます","ko":"doc-reviewer는 UDP를 통해 opentrack에 자세 데이터를 보내는 AI 기반 헤드 트래킹 애플리케이션입니다","es":"doc-reviewer es una aplicación de seguimiento de cabeza basada en cámaras que envía datos de postura a opentrack mediante UDP","fr":"doc-reviewer est une application de suivi de tête basée sur les caméras qui envoie des données de posture à opentrack via UDP","de":"doc-reviewer ist eine kamerabasierte Head-Tracking-App, die Posturdaten an opentrack über UDP sendet","pt":"O Doc Reviewer é uma aplicação de rastreamento de cabeça com base em câmera que envia dados de postura para o OpenTrack via UDP.","ru":"Doc Reviewer - это камера-базированное приложение для отслеживания головы, которое отправляет данные о позе в OpenTrack через UDP.","ar":"Doc Reviewer هو تطبيق لتعقب الرأس باستخدام الكاميرا الذي يرسل بيانات الموقف إلى OpenTrack عبر بروتوكول UDP.","en":"カメラベースのヘッドトラッキングアプリ。姿勢データをopentrackにUDPで送信できます。"},"seo":{"title":{"zh":"AI智能工具：doc-reviewer头部跟踪应用","ja":"AIエージェント：doc-reviewerカメラベースのヘッドトラッキングアプリ","ko":"AI 에이전트: doc-reviewer 카메라 기반 헤드 트래킹 애플리케이션","es":"Herramientas de IA: doc-reviewer, seguimiento de cabeza","fr":"Outils d''IA: doc-reviewer, suivi de tête","de":"KI-Tools: doc-reviewer, Head-Tracking","pt":"Ferramentas de IA: Doc Reviewer","ru":"ИИ Агенты: Doc Reviewer","ar":"أدوات الذكاء الاصطناعي: Doc Reviewer","en":"doc-reviewer"},"description":{"zh":"doc-reviewer是一个使用UDP向opentrack发送姿势数据的AI智能头部跟踪应用，用于跟踪用户的头部运动","ja":"doc-reviewerは、カメラベースのヘッドトラッキングアプリで、opentrackにUDPで姿勢データを送信できます","ko":"doc-reviewer는 UDP를 통해 opentrack에 자세 데이터를 보내는 AI 기반 헤드 트래킹 애플리케이션입니다","es":"doc-reviewer es una aplicación de seguimiento de cabeza basada en cámaras que envía datos de postura a opentrack mediante UDP","fr":"doc-reviewer est une application de suivi de tête basée sur les caméras qui envoie des données de posture à opentrack via UDP","de":"doc-reviewer ist eine kamerabasierte Head-Tracking-App, die Posturdaten an opentrack über UDP sendet","pt":"O Doc Reviewer é uma aplicação de rastreamento de cabeça com base em câmera que envia dados de postura para o OpenTrack via UDP.","ru":"Doc Reviewer - это камера-базированное приложение для отслеживания головы, которое отправляет данные о позе в OpenTrack через UDP.","ar":"Doc Reviewer هو تطبيق لتعقب الرأس باستخدام الكاميرا الذي يرسل بيانات الموقف إلى OpenTrack عبر بروتوكول UDP.","en":"カメラベースのヘッドトラッキングアプリ。姿勢データをopentrackにUDPで送信できます。"},"definition":{"en":"カメラベースのヘッドトラッキングアプリ。姿勢データをopentrackにUDPで送信できます。"},"features":{"zh":["使用UDP向opentrack发送姿势数据","支持头部跟踪和运动分析","基于AI的智能头部跟踪算法","跨平台支持","易于集成和使用"],"ja":["opentrackにUDPで姿勢データを送信","ヘッドトラッキングと運動分析をサポート","AIベースのスマートヘッドトラッキングアルゴリズム","クロスプラットフォーム対応","簡単な統合と使用"],"ko":["UDP를 통해 opentrack에 자세 데이터 전송","헤드 트래킹과 동작 분석을 지원","AI 기반의 스마트 헤드 트래킹 알고리즘","크로스 플랫폼 지원","쉽게 통합하고 사용"],"es":["Seguimiento de cabeza basado en cámaras","Envío de datos de postura a opentrack mediante UDP","Compatibilidad con opentrack","Tecnología de seguimiento de cabeza avanzada","Facilidad de uso y configuración"],"fr":["Suivi de tête basé sur les caméras","Envoi de données de posture à opentrack via UDP","Compatibilité avec opentrack","Technologie de suivi de tête avancée","Facilité d''utilisation et de configuration"],"de":["Kamerabasiertes Head-Tracking","Übertragung von Posturdaten an opentrack über UDP","Kompatibilität mit opentrack","Fortgeschrittene Head-Tracking-Technologie","Einfache Bedienung und Konfiguration"],"pt":["Rastreamento de cabeça com base em câmera","Envio de dados de postura para o OpenTrack via UDP","Integração com o OpenTrack","Suporte a UDP para transmissão de dados","Aplicação de IA para análise de postura"],"ru":["Отслеживание головы на основе камеры","Отправка данных о позе в OpenTrack через UDP","Интеграция с OpenTrack","Поддержка UDP для передачи данных","Приложение ИИ для анализа позы"],"ar":["تعقب الرأس باستخدام الكاميرا","إرسال بيانات الموقف إلى OpenTrack عبر بروتوكول UDP","التكامل مع OpenTrack","دعم بروتوكول UDP لنقل البيانات","تطبيق ذكاء اصطناعي لتحليل الموقف"]},"keywords":{"zh":["AI智能工具","头部跟踪应用","UDP数据发送","opentrack集成","如何使用doc-reviewer","doc-reviewer替代品","头部跟踪算法","AI头部跟踪","跨平台头部跟踪"],"ja":["AIエージェント","ヘッドトラッキングアプリ","UDPデータ送信","opentrack統合","doc-reviewerの使い方","doc-reviewerの代替","ヘッドトラッキングアルゴリズム","AIヘッドトラッキング","クロスプラットフォームヘッドトラッキング"],"ko":["AI 에이전트","헤드 트래킹 애플리케이션","UDP 데이터 전송","opentrack 통합","doc-reviewer 사용 방법","doc-reviewer 대체","헤드 트래킹 알고리즘","AI 헤드 트래킹","크로스 플랫폼 헤드 트래킹"],"es":["herramientas de ia","seguimiento de cabeza","opentrack","udp","cámaras","desarrollo de aplicaciones","tecnología de seguimiento","guias de instalación de doc-reviewer","alternativas a doc-reviewer"],"fr":["outils d''ia","suivi de tête","opentrack","udp","caméras","développement d''applications","technologie de suivi","guides d''installation de doc-reviewer","alternatives à doc-reviewer"],"de":["ki-tools","head-tracking","opentrack","udp","kameras","anwendungsentwicklung","verfolgungstechnologie","installationsanleitungen für doc-reviewer","alternativen zu doc-reviewer"],"pt":["ferramentas de IA","rastreamento de cabeça","OpenTrack","UDP","análise de postura","como usar Doc Reviewer","o que é Doc Reviewer","Doc Reviewer vs OpenTrack","instalar Doc Reviewer","guia de configuração do Doc Reviewer"],"ru":["ИИ агенты","отслеживание головы","OpenTrack","UDP","анализ позы","как использовать Doc Reviewer","что такое Doc Reviewer","Doc Reviewer vs OpenTrack","установить Doc Reviewer","руководство по настройке Doc Reviewer"],"ar":["أدوات الذكاء الاصطناعي","تعقب الرأس","OpenTrack","بروتوكول UDP","تحليل الموقف","كيفية استخدام Doc Reviewer","ما هو Doc Reviewer","Doc Reviewer مقابل OpenTrack","تثبيت Doc Reviewer","دليل إعداد Doc Reviewer"]}},"owner":"shiguruikai","repo":"cam-head-tracker","repoPath":"shiguruikai/cam-head-tracker","stars":0,"forks":0,"updatedAt":"2026-03-04T13:07:01.893Z","topics":[],"category":"community","skillMd":{"name":"doc-reviewer","description":"","bodyPreview":"# Document Reviewer\n\n専門的かつ徹底的なドキュメントレビューをします。\n\n## 進め方\n\n### 1. レビュー対象の把握\n\n変更の意図や背景を把握する。\n\n- **PRの場合**:\n    - **競合回避**: `git status -s`で未コミットがある場合、ユーザーに`git stash`を促す。\n    - **チェックアウト**: `gh pr checkout <pr_number>`\n    - **PR情報取得**: `gh pr view <pr_number>`\n    - **差分取得**: `gh pr diff <pr_number>`\n- **ローカル変更の場合**: レビュー対象の指定がない場合、`git diff`および`git diff --staged`で差分を確認する。\n\n### 2. 詳細な分析\n\n- **コンテキストの補完**: 詳細なレビューを要求されている場合、または、変更の意図や背景が不明瞭な場合、関連ファイルをすべて読み込み、全体の整合性を確認する。\n\n以下の観点で分析:\n\n- **正確性**: 内容は正確で、","body":"# Document Reviewer\n\n専門的かつ徹底的なドキュメントレビューをします。\n\n## 進め方\n\n### 1. レビュー対象の把握\n\n変更の意図や背景を把握する。\n\n- **PRの場合**:\n    - **競合回避**: `git status -s`で未コミットがある場合、ユーザーに`git stash`を促す。\n    - **チェックアウト**: `gh pr checkout <pr_number>`\n    - **PR情報取得**: `gh pr view <pr_number>`\n    - **差分取得**: `gh pr diff <pr_number>`\n- **ローカル変更の場合**: レビュー対象の指定がない場合、`git diff`および`git diff --staged`で差分を確認する。\n\n### 2. 詳細な分析\n\n- **コンテキストの補完**: 詳細なレビューを要求されている場合、または、変更の意図や背景が不明瞭な場合、関連ファイルをすべて読み込み、全体の整合性を確認する。\n\n以下の観点で分析:\n\n- **正確性**: 内容は正確で、誤りがないか？\n- **明確性**: 曖昧な表現はなく、誰が読んでも理解しやすいか？\n- **一貫性**: 用語、書式、スタイルが一貫しているか？\n- **完全性**: 不足している情報はないか？\n- **構成**: 論理的な流れになっており、理解しやすい構成か？\n- **最新性**: 最新の情報に基づいているか？\n\n### 3. フィードバックの提示\n\n- **概要**: 変更の概要と全体的な評価\n- **指摘事項**: `重大`, `中度`, `軽微`のレベル別で記述\n- **結論**: マージやコミットの可否、推奨や提案\n"},"lastSynced":"2026-03-04T14:55:09.477Z","agentAnalysis":{"suitability":{"en":"Perfect for Code Review Agents needing comprehensive documentation analysis capabilities.","zh":"适合需要全面文档分析能力的代码审查代理。","ja":"コードレビューエージェントが包括的なドキュメント分析機能を必要とする場合に適しています。","ko":"포괄적인 문서 분석 기능이 필요한 코드 리뷰 에이전트에게 적합합니다.","es":"Perfecto para agentes de revisión de código que necesitan capacidades de análisis de documentación integral.","fr":"Parfait pour les agents de révision de code nécessitant des capacités d''analyse de documentation complètes.","de":"Perfekt für Code-Review-Agents, die umfassende Dokumentationsanalysefunktionen benötigen.","pt":"Perfeito para Agentes de Revisão de Código que necessitam de capacidades de análise de documentação abrangentes.","ru":"Идеально для агентов проверки кода, которым необходимы всесторонние возможности анализа документации.","ar":"مثالي لعميل مراجعة الشفرة الذين يحتاجون إلى قدرات تحليل مستندات شاملة."},"recommendation":{"en":"Empowers agents to perform thorough reviews of documentation changes using Git and GitHub protocols, analyzing differences with `git diff` and `gh pr diff`, and ensuring accuracy and context completion.","zh":"赋予代理使用Git和GitHub协议对文档更改进行彻底审查的能力，使用`git diff`和`gh pr diff`分析差异，并确保准确性和上下文完成。","ja":"GitおよびGitHubのプロトコルを使用してドキュメントの変更を徹底的にレビューする機能をエージェントに与え、`git diff`および`gh pr diff`を使用して差異を分析し、正確性とコンテキストの完了を確保します。","ko":"Git과 GitHub 프로토콜을 사용하여 문서의 변경 사항을 철저하게 검토할 수 있는 기능을 에이전트에게 부여하며, `git diff` 및 `gh pr diff`를 사용하여 差异을 분석하고 정확성 및 컨텍스트 완성을 보장합니다.","es":"Permite a los agentes realizar revisiones exhaustivas de los cambios en la documentación utilizando los protocolos Git y GitHub, analizando las diferencias con `git diff` y `gh pr diff`, y garantizando la precisión y la completitud del contexto.","fr":"Permet aux agents d''effectuer des révisions approfondies des modifications de la documentation en utilisant les protocoles Git et GitHub, en analysant les différences avec `git diff` et `gh pr diff`, et en assurant l''exactitude et la complétion du contexte.","de":"Ermächtigt die Agenten, gründliche Überprüfungen der Änderungen in der Dokumentation mithilfe der Git- und GitHub-Protokolle durchzuführen, indem die Unterschiede mit `git diff` und `gh pr diff` analysiert und die Genauigkeit und Kontextvollständigkeit sichergestellt werden.","pt":"Habilita os agentes a realizar revisões minuciosas das alterações de documentação usando os protocolos Git e GitHub, analisando as diferenças com `git diff` e `gh pr diff`, e garantindo a precisão e a conclusão do contexto.","ru":"Наделяет агентов возможностью проводить тщательные обзоры изменений документации с использованием протоколов Git и GitHub, анализируя различия с помощью `git diff` и `gh pr diff`, и обеспечивая точность и завершенность контекста.","ar":"يسمح للوكلاء بإجراء استعراضات دقيقة للتغييرات في المستندات باستخدام بروتوكولات Git و GitHub، وتحليل الفروق باستخدام `git diff` و `gh pr diff`، وضمان الدقة واكتمال السياق."},"useCases":{"en":["Automating PR reviews with `gh pr checkout` and `gh pr view`","Debugging local changes with `git status -s` and `git stash`","Validating documentation updates with detailed analysis and context completion"],"zh":["使用`gh pr checkout`和`gh pr view`自动执行PR审查","使用`git status -s`和`git stash`调试本地更改","使用详细分析和上下文完成验证文档更新"],"ja":["`gh pr checkout`および`gh pr view`を使用してPRレビューを自動化する","`git status -s`および`git stash`を使用してローカル変更をデバッグする","詳細な分析およびコンテキストの完了を使用してドキュメントの更新を検証する"],"ko":["`gh pr checkout` 및 `gh pr view`를 사용하여 PR 검토를 자동화하는 것","`git status -s` 및 `git stash`를 사용하여 로컬 변경 사항을 디버깅하는 것","詳細한 분석 및 컨텍스트 완성을 사용하여 문서의 업데이트를 검증하는 것"],"es":["Automatizar las revisiones de PR con `gh pr checkout` y `gh pr view`","Depurar los cambios locales con `git status -s` y `git stash`","Validar las actualizaciones de la documentación con un análisis detallado y la completitud del contexto"],"fr":["Automatiser les révisions de PR avec `gh pr checkout` et `gh pr view`","Déboguer les modifications locales avec `git status -s` et `git stash`","Valider les mises à jour de la documentation avec une analyse détaillée et la complétion du contexte"],"de":["Automatisieren von PR-Überprüfungen mit `gh pr checkout` und `gh pr view`","Lokale Änderungen mit `git status -s` und `git stash` debuggen","Überprüfen von Dokumentationsaktualisierungen mit detaillierter Analyse und Kontextvollständigkeit"],"pt":["Automatizar revisões de PR com `gh pr checkout` e `gh pr view`","Depurar alterações locais com `git status -s` e `git stash`","Validar atualizações de documentação com análise detalhada e conclusão do contexto"],"ru":["Автоматизировать обзоры PR с помощью `gh pr checkout` и `gh pr view`","Отлаживать локальные изменения с помощью `git status -s` и `git stash`","Проверять обновления документации с помощью подробного анализа и завершения контекста"],"ar":["توفير مراجعات(PR) آليًا باستخدام `gh pr checkout` و `gh pr view`","تصحيح الأخطاء في التغييرات المحلية باستخدام `git status -s` و `git stash`","التحقق من تحديثات المستندات باستخدام تحليل مفصل واكتمال السياق"]},"limitations":{"en":["Requires Git and GitHub installation","Limited to reviewing changes in Git repositories"],"zh":["需要Git和GitHub的安装","仅限于Git仓库中的更改审查"],"ja":["GitおよびGitHubのインストールが必要","Gitリポジトリ内の変更のレビューのみに限定される"],"ko":["Git 및 GitHub의 설치가 필요함","Git 리포지토리 내의 변경 사항만 검토할 수 있음"],"es":["Requiere la instalación de Git y GitHub","Limitado a la revisión de cambios en los repositorios Git"],"fr":["Nécessite l''installation de Git et GitHub","Limité à la révision des modifications dans les référentiels Git"],"de":["Erfordert die Installation von Git und GitHub","Begrenzt auf die Überprüfung von Änderungen in Git-Repositorys"],"pt":["Requer instalação do Git e do GitHub","Limitado à revisão de alterações em repositórios Git"],"ru":["Требует установки Git и GitHub","Ограничен обзором изменений в репозиториях Git"],"ar":["يتطلب تثبيت Git و GitHub","محدود بالاستعراض التغييرات في مخازن Git"]},"version":3},"contentHash":"cf42d754a05642ebc411bc1d31f0ea1fa679b2aabe384248c2835ec561971711","qualityScore":15}');
