INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('shiguruikai/cam-head-tracker/doc-reviewer', 'doc-reviewer', 'shiguruikai', 'cam-head-tracker', 'community', 'doc-reviewer shiguruikai cam-head-tracker community doc-reviewer是一个使用UDP向opentrack发送姿势数据的AI智能头部跟踪应用，用于跟踪用户的头部运动 doc-reviewerは、カメラベースのヘッドトラッキングアプリで、opentrackにUDPで姿勢データを送信できます doc-reviewer는 UDP를 통해 opentrack에 자세 데이터를 보내는 AI 기반 헤드 트래킹 애플리케이션입니다 doc-reviewer es una aplicación de seguimiento de cabeza basada en cámaras que envía datos de postura a opentrack mediante UDP doc-reviewer est une application de suivi de tête basée sur les caméras qui envoie des données de posture à opentrack via UDP doc-reviewer ist eine kamerabasierte Head-Tracking-App, die Posturdaten an opentrack über UDP sendet O Doc Reviewer é uma aplicação de rastreamento de cabeça com base em câmera que envia dados de postura para o OpenTrack via UDP. Doc Reviewer - это камера-базированное приложение для отслеживания головы, которое отправляет данные о позе в OpenTrack через UDP. Doc Reviewer هو تطبيق لتعقب الرأس باستخدام الكاميرا الذي يرسل بيانات الموقف إلى OpenTrack عبر بروتوكول UDP. カメラベースのヘッドトラッキングアプリ。姿勢データをopentrackにUDPで送信できます。 AI智能工具 头部跟踪应用 UDP数据发送 opentrack集成 如何使用doc-reviewer doc-reviewer替代品 头部跟踪算法 AI头部跟踪 跨平台头部跟踪 カメラベースのヘッドトラッキングアプリ。姿勢データをopentrackにUDPで送信できます。');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('deadronos/deadronostask/performance-optimization', 'community', 'deadronos', 'deadronostask', 'deadronos/deadronostask', 'performance-optimization', 0, 0, 15, '2026-03-04T13:07:01.907Z', '2026-03-04T14:59:08.148Z', '6c4a937921f3da5de43d3bb86984741f9403791e85e6e83f7b96395530e85ed3', '{"id":"deadronos/deadronostask/performance-optimization","name":"performance-optimization","description":{"zh":"使用AI智能工具进行性能优化，学习任务管理器项目","ja":"AIエージェントを使用したパフォーマンス最適化、タスクマネージャープロジェクト","ko":"AI 에이전트를 사용한 성능 최적화, 태스크 매니저 프로젝트","es":"El proyecto de aprendizaje de Task Manager te ayuda a optimizar el rendimiento con agentes de IA. Aprende a mejorar la eficiencia y reducir tiempos de respuesta.","fr":"Le projet d''apprentissage de Task Manager vous aide à optimiser les performances avec des agents IA. Apprenez à améliorer l''efficacité et réduire les temps de réponse.","de":"Das Lernprojekt Task Manager hilft Ihnen, die Leistung mit KI-Agents zu optimieren. Lernen Sie, die Effizienz zu verbessern und Antwortzeiten zu reduzieren.","pt":"O Task Manager é um projeto de aprendizado que ajuda a otimizar o desempenho do seu aplicativo com React, Python e Node.js","ru":"Task Manager - это проект обучения, который помогает оптимизировать производительность вашего приложения с помощью React, Python и Node.js","ar":"Task Manager هو مشروع تعليمي يساعد على تحسين أداء تطبيقك باستخدام React و Python و Node.js","en":"Task Manager (Learning Project)"},"seo":{"title":{"zh":"AI智能工具性能优化","ja":"AIエージェントのパフォーマンス最適化","ko":"AI 에이전트 성능 최적화","es":"Optimización de Rendimiento con Agentes de IA","fr":"Outil d''Optimisation de Performance avec Agents IA","de":"Leistungs-Optimierung mit KI-Agents","pt":"Otimização de Desempenho com Ferramentas de IA","ru":"Оптимизация Производительности с Помощью ИИ Агентов","ar":"تحسين الأداء باستخدام أدوات الذكاء الاصطناعي","en":"performance-optimization"},"description":{"zh":"使用AI智能工具进行性能优化，学习任务管理器项目","ja":"AIエージェントを使用したパフォーマンス最適化、タスクマネージャープロジェクト","ko":"AI 에이전트를 사용한 성능 최적화, 태스크 매니저 프로젝트","es":"El proyecto de aprendizaje de Task Manager te ayuda a optimizar el rendimiento con agentes de IA. Aprende a mejorar la eficiencia y reducir tiempos de respue...","fr":"Le projet d''apprentissage de Task Manager vous aide à optimiser les performances avec des agents IA. Apprenez à améliorer l''efficacité et réduire les temps d...","de":"Das Lernprojekt Task Manager hilft Ihnen, die Leistung mit KI-Agents zu optimieren. Lernen Sie, die Effizienz zu verbessern und Antwortzeiten zu reduzieren.","pt":"O Task Manager é um projeto de aprendizado que ajuda a otimizar o desempenho do seu aplicativo com React, Python e Node.js","ru":"Task Manager - это проект обучения, который помогает оптимизировать производительность вашего приложения с помощью React, Python и Node.js","ar":"Task Manager هو مشروع تعليمي يساعد على تحسين أداء تطبيقك باستخدام React و Python و Node.js","en":"Task Manager (Learning Project)"},"definition":{"en":"Task Manager (Learning Project)"},"features":{"zh":["使用React进行前端开发","使用Python进行后端开发","使用Node.js进行服务器端开发","使用CLI进行命令行接口开发","使用AI智能工具进行性能优化"],"ja":["Reactを使用したフロントエンド開発","Pythonを使用したバックエンド開発","Node.jsを使用したサーバーサイド開発","CLIを使用したコマンドラインインターフェース開発","AIエージェントを使用したパフォーマンス最適化"],"ko":["React를 사용한 프론트엔드 개발","Python을 사용한 백엔드 개발","Node.js를 사용한 서버사이드 개발","CLI를 사용한 명령줄 인터페이스 개발","AI 에이전트를 사용한 성능 최적화"],"es":["Análisis de rendimiento de agentes de IA","Optimización de tareas y procesos","Mejora de la eficiencia y reducción de tiempos de respuesta","Integración con herramientas de desarrollo como React y Node.js","Compatibilidad con CLI y otros entornos de desarrollo"],"fr":["Analyse de performance des agents IA","Optimisation des tâches et des processus","Amélioration de l''efficacité et réduction des temps de réponse","Intégration avec des outils de développement comme React et Node.js","Compatibilité avec CLI et d''autres environnements de développement"],"de":["Leistungs-Analyse von KI-Agents","Optimierung von Aufgaben und Prozessen","Verbesserung der Effizienz und Reduzierung von Antwortzeiten","Integration mit Entwicklungstools wie React und Node.js","Kompatibilität mit CLI und anderen Entwicklungsumgebungen"],"pt":["Otimização de código com React","Melhoria de desempenho com Python","Otimização de recursos com Node.js","Análise de desempenho com CLI","Integração com agentes de IA"],"ru":["Оптимизация кода с помощью React","Улучшение производительности с помощью Python","Оптимизация ресурсов с помощью Node.js","Анализ производительности с помощью CLI","Интеграция с ИИ Агентами"],"ar":["تحسين الكود باستخدام React","تحسين الأداء باستخدام Python","تحسين الموارد باستخدام Node.js","تحليل الأداء باستخدام CLI","التكامل مع وكلاء الذكاء الاصطناعي"]},"keywords":{"zh":["如何使用AI智能工具","什么是性能优化","任务管理器替代方案","React vs Angular","AI智能工具安装","性能优化设置指南"],"ja":["AIエージェントの使用方法","パフォーマンス最適化とは","タスクマネージャーの代替案","React vs Angular","AIエージェントのインストール","パフォーマンス最適化の設定ガイド"],"ko":["AI 에이전트의 사용 방법","성능 최적화란","태스크 매니저의 대체方案","React vs Angular","AI 에이전트의 설치","성능 최적화의 설정 가이드"],"es":["cómo usar agentes de IA","qué es la optimización de rendimiento","alternativas a Task Manager","Task Manager vs otros gestores de tareas","instalación de agentes de IA","guía de configuración de Task Manager","optimización de rendimiento en Python","herramientas de desarrollo para agentes de IA"],"fr":["comment utiliser des agents IA","quoi est l''optimisation de performance","alternatives à Task Manager","Task Manager vs d''autres gestionnaires de tâches","installation d''agents IA","guide de configuration de Task Manager","optimisation de performance en Python","outils de développement pour agents IA"],"de":["wie man KI-Agents verwendet","was ist die Leistungs-Optimierung","Alternativen zu Task Manager","Task Manager vs andere Task-Manager","Installation von KI-Agents","Anleitung zur Konfiguration von Task Manager","Leistungs-Optimierung in Python","Entwicklungstools für KI-Agents"],"pt":["como otimizar desempenho","ferramentas de IA para desenvolvedores","Task Manager alternative","React vs Angular","instalar Node.js","guia de configuração do Python"],"ru":["как оптимизировать производительность","инструменты ИИ для разработчиков","Task Manager альтернатива","React vs Angular","установить Node.js","руководство по настройке Python"],"ar":["كيفية تحسين الأداء","أدوات الذكاء الاصطناعي للمطورين","بديل Task Manager","React vs Angular","تثبيت Node.js","دليل إعداد Python"]}},"owner":"deadronos","repo":"deadronostask","repoPath":"deadronos/deadronostask","stars":0,"forks":0,"updatedAt":"2026-03-04T13:07:01.907Z","topics":[],"category":"community","skillMd":{"name":"performance-optimization","description":"Performance optimization playbook (measure → diagnose → fix → verify) for this repo (React + R3F + Three.js + Vite). Use when asked to improve FPS, reduce jank, lower draw calls, optimize loading/bundle size, or investigate CPU/GPU/memory bottlenecks.","bodyPreview":"# Performance Optimization (Opt-in)\n\nUse this skill to make performance work repeatable and evidence-driven.\n\n## Workflow (always follow)\n\n1. **Define the symptom + target**\n   - Runtime: FPS drops, stutters, GPU/CPU pegged, memory growth.\n   - Load time: slow first paint, large bundle, long shader compile.\n   - Pick a measurable target (e.g., steady 60 FPS, lower draw calls, smaller JS).\n\n2. **Measure before changing code**\n   - Reproduce the issue and capture one of:\n     - Browser Performance","body":"# Performance Optimization (Opt-in)\n\nUse this skill to make performance work repeatable and evidence-driven.\n\n## Workflow (always follow)\n\n1. **Define the symptom + target**\n   - Runtime: FPS drops, stutters, GPU/CPU pegged, memory growth.\n   - Load time: slow first paint, large bundle, long shader compile.\n   - Pick a measurable target (e.g., steady 60 FPS, lower draw calls, smaller JS).\n\n2. **Measure before changing code**\n   - Reproduce the issue and capture one of:\n     - Browser Performance trace (CPU main thread)\n     - R3F/Three stats (FPS, draw calls, triangles)\n     - Memory timeline (detached nodes, heap growth)\n\n3. **Classify the bottleneck**\n   - **CPU-bound**: heavy JS, too many React renders, expensive per-frame work.\n   - **GPU-bound**: too many draw calls, heavy shaders/postprocessing, high DPR.\n   - **IO/Load-bound**: big bundles/assets, blocking work on startup.\n   - **Memory-bound**: leaks in textures/geometries/materials, retained arrays.\n\n4. **Apply the smallest fix that moves the metric**\n   - Prefer fixes that reduce _work per frame_ and _draw calls_.\n   - Keep changes surgical and verify the metric improved.\n\n5. **Verify and guard against regressions**\n   - Run `npm test`, `npm run lint`, `npm run typecheck`.\n   - If you introduced a new helper/heuristic, add a small unit test.\n\n## R3F / Three.js tactics (common wins)\n\n- **Draw calls**: prefer instancing/merging; reduce unique materials.\n- **DPR**: cap DPR or apply device-specific caps. Dynamic DPR techniques are intended for R3F projects and are not applicable in this repo.\n- **Per-frame work**: keep `useFrame` callbacks tiny; avoid allocations inside `useFrame`.\n- **Memoization**: cache geometries/materials/textures; reuse vectors/quaternions.\n- **Postprocessing**: disable/scale effects on low perf; prefer fewer passes.\n- **Shadows**: reduce shadow map size; limit shadow-casting lights.\n\n## React tactics (common wins)\n\n- Avoid state updates every frame; use refs for frame-local values.\n- Stabilize props to prevent re-render cascades.\n- Split heavy components; lazy-load non-critical UI where appropriate.\n\n## When to load deeper reference material\n\n- For generic perf checklists across frontend/backend/db: read `references/performance-optimization.md`.\n- Dynamic DPR techniques are not applicable for this repository (no R3F usage).\n- For offloading CPU-heavy loops: consider the `js-worker-multithreading` skill.\n"},"lastSynced":"2026-03-04T14:59:08.148Z","agentAnalysis":{"suitability":{"en":"Perfect for AI Agents like Cursor, Windsurf, and Claude Code needing advanced performance optimization and debugging capabilities for runtime and load time issues.","zh":"适用于像Cursor、Windsurf和Claude Code这样的AI代理，需要高级性能优化和调试功能来解决运行时和加载时间问题。","ja":"Cursor、Windsurf、Claude CodeのようなAIエージェントに適しています。ランタイムとロード時間の問題に対する高度なパフォーマンス最適化とデバッグ機能が必要です。","ko":"Cursor, Windsurf, Claude Code와 같은 AI 에이전트에 적합합니다. 런타임 및 로드 시간 문제를 위한 고급 성능 최적화 및 디버깅 기능이 필요합니다.","es":"Perfecto para Agentes de IA como Cursor, Windsurf y Claude Code que necesitan capacidades avanzadas de optimización del rendimiento y depuración para problemas de tiempo de ejecución y carga.","fr":"Parfait pour les agents IA comme Cursor, Windsurf et Claude Code nécessitant des capacités avancées d''optimisation des performances et de débogage pour les problèmes de temps d''exécution et de chargement.","de":"Perfekt für KI-Agents wie Cursor, Windsurf und Claude Code, die erweiterte Leistungsoptimierungs- und Debugging-Funktionen für Laufzeit- und Ladezeitprobleme benötigen.","pt":"Perfeito para Agentes de IA como Cursor, Windsurf e Claude Code que necessitam de otimização de desempenho avançada e capacidades de depuração para problemas de tempo de execução e tempo de carga.","ru":"Идеально подходит для агентов ИИ, таких как Cursor, Windsurf и Claude Code, которым необходимы продвинутые возможности оптимизации производительности и отладки для проблем времени выполнения и времени загрузки.","ar":"مثالي لعميل الذكاء الاصطناعي مثل Cursor و Windsurf و Claude Code الذي يحتاج إلى تحسين أداء متقدم وخصائص فحص للأخطاء في وقت التشغيل ووقت التحميل."},"recommendation":{"en":"Empowers agents to identify and resolve performance bottlenecks using measurable targets, such as achieving steady 60 FPS, reducing draw calls, and optimizing GPU/CPU usage, all while leveraging browser performance metrics and tools.","zh":"赋予代理识别和解决性能瓶颈的能力，使用可衡量的目标，例如实现稳定的60 FPS，减少绘制调用，优化GPU/CPU使用率，同时利用浏览器性能指标和工具。","ja":"エージェントにパフォーマンスのボトルネックを特定して解決する能力を与えます。測定可能な目標を使用して、安定した60 FPSを達成し、描画コールを削減し、GPU/CPUの使用率を最適化します。ブラウザのパフォーマンスメトリックとツールも利用します。","ko":"에이전트가 성능 병목 현상을 식별하고 해결할 수 있는 능력을 부여합니다. 측정 가능한 목표를 사용하여 안정적인 60 FPS를 달성하고 렌더링 호출을 줄이고 GPU/CPU 사용率를 최적화합니다. 브라우저 성능 메트릭과 도구도 활용합니다.","es":"Permite a los agentes identificar y resolver cuellos de botella de rendimiento utilizando objetivos medibles, como lograr un rendimiento constante de 60 FPS, reducir las llamadas de dibujo y optimizar el uso de GPU/CPU, todo mientras aprovecha las métricas y herramientas de rendimiento del navegador.","fr":"Permet aux agents d''identifier et de résoudre les goulots d''étranglement des performances en utilisant des cibles mesurables, telles que l''obtention d''un rendement constant de 60 FPS, la réduction des appels de dessin et l''optimisation de l''utilisation de la GPU/CPU, le tout en exploitant les métriques et les outils de performances du navigateur.","de":"Ermöglicht es den Agents, Leistungsengpässe zu identifizieren und zu lösen, indem messbare Ziele verwendet werden, wie z. B. ein konstantes FPS von 60 erreichen, Zeichenaufgaben reduzieren und die GPU/CPU-Auslastung optimieren, während die Leistungsdaten und -tools des Browsers genutzt werden.","pt":"Permite que os agentes identifiquem e resolvam gargalos de desempenho usando alvos mensuráveis, como alcançar 60 FPS estáveis, reduzir chamadas de desenho e otimizar o uso de GPU/CPU, tudo isso aproveitando as métricas e ferramentas de desempenho do navegador.","ru":"Позволяет агентам выявлять и решать проблемы с производительностью, используя измеримые цели, такие как достижение стабильных 60 FPS, уменьшение количества вызовов отрисовки и оптимизация использования GPU/CPU, все это при помощи метрик и инструментов производительности браузера.","ar":"تمكّن الوكيل من تحديد ومعالجة مشاكل الأداء باستخدام أهداف قابلة للقياس، مثل تحقيق 60 إطارًا في الثانية بشكل مستقر، وتقليل مرات الاتصال برسم، وضبط استخدام وحدة معالجة الرسومات/وحدة المعالجة المركزية، كل ذلك بالاستفادة من مقاييس أداء المتصفح وأدواته."},"useCases":{"en":["Debugging FPS drops and stutters in real-time applications","Optimizing load times by minimizing bundle sizes and shader compile times","Analyzing and reducing memory growth in long-running processes"],"zh":["实时应用中FPS下降和卡顿的调试","通过最小化bundle大小和着色器编译时间来优化加载时间","分析和减少长时间运行的进程中的内存增长"],"ja":["リアルタイムアプリケーションでのFPS低下とスタッタのデバッグ","バンドルサイズとシェーダー編集時間を最小化してロード時間を最適化する","長時間実行されるプロセスでのメモリ増加を分析して削減する"],"ko":["실시간 애플리케이션에서 FPS 저하와 튀는 현상을 디버깅","번들 크기와 셰이더 컴파일 시간을 최소화하여 로드 시간을 최적화","오래 실행되는 프로세스에서 메모리 증가를 분석하여 줄임"],"es":["Depuración de caídas y titubeos de FPS en aplicaciones en tiempo real","Optimización de los tiempos de carga minimizando los tamaños de los paquetes y los tiempos de compilación de shaders","Análisis y reducción del crecimiento de memoria en procesos de larga duración"],"fr":["Débogage des baisses et des soubresauts de FPS dans les applications en temps réel","Optimisation des temps de chargement en minimisant les tailles des bundles et les temps de compilation des shaders","Analyse et réduction de la croissance de la mémoire dans les processus à long terme"],"de":["Fehlerbehebung von FPS-Einbrüchen und Rucklern in Echtzeit-Anwendungen","Optimierung der Ladezeiten durch Minimierung der Bundle-Größen und der Shader-Kompilierzeiten","Analyse und Reduzierung des Speicherwachstums in lang laufenden Prozessen"],"pt":["Depuração de quedas e tremores de FPS em aplicações em tempo real","Otimização de tempos de carga minimizando tamanhos de pacotes e tempos de compilação de shader","Análise e redução do crescimento de memória em processos de longa duração"],"ru":["Отладка падений и задержек FPS в реальных приложениях","Оптимизация времени загрузки путем минимизации размеров пакетов и времени компиляции шейдеров","Анализ и уменьшение роста памяти в长-ожидаемых процессах"],"ar":["فحص الأخطاء في انخفاضات وتناقضات معدل الإطار في التطبيقات في الوقت الفعلي","تحسين أوقات التحميل بتحجيم أحجام الحزم وأوقات ترجمة الشفرة","تحليل وتقليل نمو الذاكرة في العمليات التي تستمر لمدة طويلة"]},"limitations":{"en":["Requires browser performance metrics and debugging tools","Limited to optimizing runtime and load time issues","Needs measurable targets for effective performance optimization"],"zh":["需要浏览器性能指标和调试工具","仅限于优化运行时和加载时间问题","需要可衡量的目标来有效地进行性能优化"],"ja":["ブラウザのパフォーマンスメトリックとデバッグツールが必要","ランタイムとロード時間の問題のみを最適化する","有効なパフォーマンス最適化には測定可能な目標が必要"],"ko":["브라우저 성능 메트릭과 디버깅 도구가 필요","런타임 및 로드 시간 문제만 최적화","유효한 성능 최적화를 위해 측정 가능한 목표가 필요"],"es":["Requiere métricas y herramientas de depuración de rendimiento del navegador","Limitado a la optimización de problemas de tiempo de ejecución y carga","Necesita objetivos medibles para una optimización efectiva del rendimiento"],"fr":["Nécessite des métriques et des outils de débogage des performances du navigateur","Limité à l''optimisation des problèmes de temps d''exécution et de chargement","Nécessite des cibles mesurables pour une optimisation efficace des performances"],"de":["Benötigt Browser-Leistungsdaten und -Debugging-Tools","Begrenzt auf die Optimierung von Laufzeit- und Ladezeitproblemen","Benötigt messbare Ziele für eine effektive Leistungsoptimierung"],"pt":["Exige métricas e ferramentas de desempenho do navegador","Limitado à otimização de problemas de tempo de execução e tempo de carga","Necessita de alvos mensuráveis para otimização de desempenho eficaz"],"ru":["Требует метрик и инструментов производительности браузера","Ограничен оптимизацией проблем времени выполнения и времени загрузки","Требует измеримых целей для эффективной оптимизации производительности"],"ar":["يتطلب مقاييس وأدوات أداء المتصفح","محدود بتحسين مشاكل وقت التشغيل ووقت التحميل","يحتاج إلى أهداف قابلة للقياس لتحسين الأداء الفعال"]},"version":3},"contentHash":"6c4a937921f3da5de43d3bb86984741f9403791e85e6e83f7b96395530e85ed3","qualityScore":15}');
