INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('rzx007/nanobot-ts/agent-browser', 'agent-browser', 'rzx007', 'nanobot-ts', 'community', 'agent-browser rzx007 nanobot-ts community ai-agent nanobot nanobot-ts nanobot-ts是nanobot的TypeScript版本，一个超轻量级的个人AI助手框架。它提供了强大的AI功能 nanobot-tsはnanobotのTypeScript版で、超軽量の個人AIアシスタントフレームワークです。強力なAI機能を提供 nanobot-ts는 nanobot의 TypeScript 버전으로, 초경량 개인 AI 어시스턴트 프레임워크입니다. 강력한 AI 기능을 제공합니다 nanobot-ts es la versión de TypeScript de nanobot, un framework de asistentes de IA ultra ligero para desarrolladores nanobot-ts est la version TypeScript de nanobot, un framework d''assistants IA ultra léger pour les développeurs nanobot-ts ist die TypeScript-Version von nanobot, einem ultra-leichten Framework für KI-Assistenten für Entwickler O nanobot-ts é uma versão TypeScript do nanobot, um framework de assistente de IA pessoal ultra-leve nanobot-ts - это версия TypeScript фреймворка nanobot, ультралегкого фреймворка для личных ИИ-ассистентов nanobot-ts هو نسخة TypeScript من nanobot، إطار عمل مساعد الذكاء الاصطناعي الشخصي الخفيف جدا nanobot-ts is the TypeScript version of nanobot, an ultra-lightweight personal AI assistant framework. AI智能代理 nanobot-ts 如何使用nanobot-ts AI助手框架 TypeScript开发 AI算法 nanobot-ts安装 nanobot-ts设置指南 nanobot-ts is the TypeScript version of nanobot, an ultra-lightweight personal AI assistant framework.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('growthxai/context-os-starterkit/account-health-scoring', 'community', 'growthxai', 'context-os-starterkit', 'growthxai/context-os-starterkit', 'account-health-scoring', 1, 2, 37, '2026-03-04T08:17:05Z', '2026-03-04T13:20:08.082Z', 'b36e1018b002581a4375c4f2e1402981976a4bdc93c39a0d85598e77f6d2c4b0', '{"id":"growthxai/context-os-starterkit/account-health-scoring","name":"account-health-scoring","description":{"zh":"Context OS提供结构化知识库，用于公司的AI智能体账户健康评分","ja":"Context OSは、企業のAIエージェントのアカウントヘルススコアリングに必要な構造化された知識ベースを提供","ko":"Context OS는 기업의 AI 에이전트 계정 건강 점수를 위한 구조화된 지식베이스를 제공","es":"Context OS es una base de conocimiento estructurada para empresas que utilizan Agentes de IA, mejorando la salud de sus cuentas.","fr":"Context OS est une base de connaissances structurée pour les entreprises utilisant des Outils d''IA, améliorant la santé de leurs comptes.","de":"Context OS ist eine strukturierte Wissensbasis für Unternehmen, die KI-Agents verwenden, um die Gesundheit ihrer Konten zu verbessern.","pt":"A pontuação de saúde de conta é uma solução baseada em Ferramentas de IA que ajuda a melhorar a saúde da sua conta. Context OS é uma base de conhecimento estruturada para empresas que usam Ferramentas de IA.","ru":"Оценка здоровья аккаунта - это решение на основе ИИ Агентов, которое помогает улучшить здоровье вашего аккаунта. Context OS - это структурированная база знаний для компаний, использующих ИИ Агенты.","ar":"تقييم صحة الحساب هو حل مستند إلى أدوات الذكاء الاصطناعي الذي يساعد على تحسين صحة حسابك. Context OS هي قاعدة معرفة منظمة للشركات التي تستخدم أدوات الذكاء الاصطناعي.","en":"Context OS — a structured knowledge base for companies using AI agents"},"seo":{"title":{"zh":"AI智能体账户健康评分","ja":"AIエージェントのアカウントヘルススコアリング","ko":"AI 에이전트 계정 건강 점수","es":"Puntuación de Salud de Cuenta con Agentes de IA","fr":"Notation de Sant